window.KURS={"units":[{"id":"01","n":"1","t":"Gelenke und innere Kehlkopfmuskeln","file":"01-gelenke-muskeln.html"},{"id":"02","n":"2","t":"N. laryngeus superior","file":"02-n-laryngeus-superior.html"},{"id":"03","n":"3","t":"N. laryngeus recurrens","file":"03-n-laryngeus-recurrens.html"},{"id":"04","n":"4","t":"Die Gesamtkarte","file":"04-gesamtkarte.html"},{"id":"05","n":"5","t":"Stimmentstehung","file":"05-stimmentstehung.html"},{"id":"06","n":"6","t":"Schutzfunktionen","file":"06-schutzfunktionen.html"},{"id":"07","n":"7","t":"Kehlkopflähmungen im Überblick","file":"07-laehmungen.html"},{"id":"08","n":"8","t":"Abgrenzung und Warnzeichen","file":"08-abgrenzung.html"},{"id":"09","n":"9–10","t":"Wiederholung und Probeprüfung","file":"09-10-wiederholung-pruefung.html"},{"id":"00","n":"·","t":"Visueller Styleguide","file":"00-styleguide.html"}],"cards":[{"id":"01-F1","unit":"01","n":"F1","sec":"h-1-1-von-den-knorpeln-zum-ventil","secT":"1.1 · Von den Knorpeln zum Ventil","q":"Zwischen welchen zwei Punkten spannt sich jede Stimmlippe?","ctx":null,"a":"Von der Innenseite des Schildknorpelwinkels (vorne) zum Proc. vocalis des Stellknorpels (hinten)."},{"id":"01-F2","unit":"01","n":"F2","sec":"h-1-1-von-den-knorpeln-zum-ventil","secT":"1.1 · Von den Knorpeln zum Ventil","q":"Nenne die zwei Teile der Rima glottidis. Welcher liegt zwischen Knorpel?","ctx":null,"a":"Pars intermembranacea (vorne, zwischen den weichen Stimmlippen, der größere Teil) und Pars intercartilaginea (hinten, zwischen den Stellknorpeln)."},{"id":"01-F3","unit":"01","n":"F3","sec":"h-1-2-gelenk-1-das-krikothyreoidgelenk-kippt","secT":"1.2 · Gelenk 1: Das Krikothyreoidgelenk kippt","q":"Was ist die Hauptbewegung im Krikothyreoidgelenk, und um welche Achse?","ctx":null,"a":"Drehung (Kippen) um eine quere Achse durch beide Krikothyreoidgelenke; dazu leichtes Gleiten."},{"id":"01-F4","unit":"01","n":"F4","sec":"h-1-2-gelenk-1-das-krikothyreoidgelenk-kippt","secT":"1.2 · Gelenk 1: Das Krikothyreoidgelenk kippt","q":"In einem Satz: Warum hebt die Kontraktion des M. cricothyroideus die Tonhöhe?","ctx":null,"a":"Das Kippen vergrößert den Abstand zwischen Schildknorpelwinkel und Stellknorpeln, sodass die Stimmlippe länger, dünner und straffer wird und schneller schwingt."},{"id":"01-F5","unit":"01","n":"F5","sec":"h-1-3-gelenk-2-das-krikoarytaenoidgelenk-schwenkt-den-proc-voc","secT":"1.3 · Gelenk 2: Das Krikoarytänoidgelenk schwenkt den Proc. vocalis","q":"Nenne die zwei Fortsätze des Stellknorpels und was an jedem ansetzt.","ctx":null,"a":"Processus vocalis: die Stimmlippe (Stimmband und Vocalis). Processus muscularis: Postikus und Lateralis."},{"id":"01-F6","unit":"01","n":"F6","sec":"h-1-3-gelenk-2-das-krikoarytaenoidgelenk-schwenkt-den-proc-voc","secT":"1.3 · Gelenk 2: Das Krikoarytänoidgelenk schwenkt den Proc. vocalis","q":"Der Proc. muscularis wird nach hinten gezogen. Wohin geht der Proc. vocalis, und was passiert mit der Stimmritze?","ctx":null,"a":"Der Proc. vocalis schwenkt nach außen (und etwas nach oben); die Stimmritze öffnet sich."},{"id":"01-F7","unit":"01","n":"F7","sec":"h-1-3-gelenk-2-das-krikoarytaenoidgelenk-schwenkt-den-proc-voc","secT":"1.3 · Gelenk 2: Das Krikoarytänoidgelenk schwenkt den Proc. vocalis","q":"Welche zwei Bewegungen kombinieren sich im Krikoarytänoidgelenk?","ctx":null,"a":"Kippen um die Längsachse der Gelenkfläche des Ringknorpels und Gleiten entlang dieser Fläche."},{"id":"01-F8","unit":"01","n":"F8","sec":"h-1-5-drei-aufgaben-oeffnen-schliessen-spannen","secT":"1.5 · Drei Aufgaben: öffnen, schließen, spannen","q":"Welcher ist der einzige innere Kehlkopfmuskel, der außen am Kehlkopf liegt?","ctx":null,"a":"M. cricothyroideus (Antikus)."},{"id":"01-F9","unit":"01","n":"F9","sec":"h-1-5-drei-aufgaben-oeffnen-schliessen-spannen","secT":"1.5 · Drei Aufgaben: öffnen, schließen, spannen","q":"Zähle die Schließer auf. Welcher schließt den hinteren Teil der Stimmritze?","ctx":null,"a":"Lateralis, Transversus (Interarytänoid) und Thyroarytänoid; der Transversus schließt hinten."},{"id":"01-F10","unit":"01","n":"F10","sec":"h-1-5-drei-aufgaben-oeffnen-schliessen-spannen","secT":"1.5 · Drei Aufgaben: öffnen, schließen, spannen","q":"Welche zwei Muskeln steuern die Spannung, und wie unterscheiden sie sich?","ctx":null,"a":"M. cricothyroideus: dehnt und verlängert die Stimmlippe von außen. Vocalis: verkürzt sie und versteift ihren Körper von innen. Ihr Gleichgewicht bestimmt Tonhöhe und Register."},{"id":"01-F11","unit":"01","n":"F11","sec":"h-1-6-zwei-mini-faelle-vom-muskel-zum-symptom","secT":"1.6 · Zwei Mini-Fälle: vom Muskel zum Symptom","q":"Welches Gelenk hat wahrscheinlich seinen Antriebsmuskel verloren, und warum kostet sie das die hohen Töne, aber nicht das Öffnen und Schließen?","ctx":{"head":"Erwachsene · Frau K., 34, Chorsopranistin","html":"Zwei Monate nach einer Schilddrüsenoperation klingt ihre Sprechstimme fast normal, aber sie erreicht ihre hohen Töne nicht mehr, die Stimme ermüdet schnell und trägt in lauter Umgebung nicht mehr. In der Laryngoskopie öffnen und schließen beide Stimmlippen."},"a":"Das Krikothyreoidgelenk, angetrieben vom M. cricothyroideus. Ohne ihn lässt sich die Stimmlippe nicht dehnen, also fehlen die höchsten Töne und etwas Lautstärke und Ausdauer; Postikus und Schließer arbeiten noch, deshalb sehen Öffnen und Schließen normal aus."},{"id":"01-F12","unit":"01","n":"F12","sec":"h-1-6-zwei-mini-faelle-vom-muskel-zum-symptom","secT":"1.6 · Zwei Mini-Fälle: vom Muskel zum Symptom","q":"Welcher Muskel zieht die Stimmlippen bei jedem Einatmen normalerweise auseinander? Warum kann das Schreien recht normal bleiben, während die Atmung laut ist?","ctx":{"head":"Kind · Baby J., 6 Wochen","html":"Seit einer Herzoperation hat J. bei jedem Einatmen ein hohes Geräusch, schlimmer beim Schreien und Trinken. Sein Schreien klingt überraschend normal. Die Laryngoskopie zeigt, dass beide Stimmlippen auch beim Einatmen nahe der Mitte bleiben."},"a":"Der Postikus (beidseits). Fallen beide Öffner aus, bleiben die Stimmlippen nahe der Mitte: Die Luft muss durch einen engen Spalt, das macht beim Einatmen ein Geräusch (inspiratorischer Stridor). Weil die Stimmlippen schon nah beieinander liegen, können sie noch schwingen, deshalb kann das Schreien fast normal klingen. Genau dieses Muster triffst du später als beidseitige Rekurrensparese wieder."},{"id":"02-F1","unit":"02","n":"F1","sec":"h-2-1-ursprung-und-teilung","secT":"2.1 · Ursprung und Teilung","q":"Aus welchem Ganglion geht der N. laryngeus superior ab?","ctx":null,"a":"Aus dem Ganglion inferius (nodosum) des N. vagus, direkt unter dem Foramen jugulare."},{"id":"02-F2","unit":"02","n":"F2","sec":"h-2-1-ursprung-und-teilung","secT":"2.1 · Ursprung und Teilung","q":"In welcher Höhe teilt er sich, und wie heißen die beiden Äste?","ctx":null,"a":"Etwa in Höhe des großen Zungenbeinhorns; in R. internus und R. externus."},{"id":"02-F3","unit":"02","n":"F3","sec":"h-2-2-r-internus-der-waechter-oberhalb-der-stimmlippen","secT":"2.2 · R. internus: der „Wächter“ oberhalb der Stimmlippen","q":"Durch welche Struktur tritt der R. internus in den Kehlkopf, und mit welchem Gefäß?","ctx":null,"a":"Durch die Membrana thyrohyoidea, zusammen mit der A. laryngea superior."},{"id":"02-F4","unit":"02","n":"F4","sec":"h-2-2-r-internus-der-waechter-oberhalb-der-stimmlippen","secT":"2.2 · R. internus: der „Wächter“ oberhalb der Stimmlippen","q":"Welche Schleimhaut versorgt er sensibel, und wer übernimmt unterhalb der Stimmlippen?","ctx":null,"a":"Die Schleimhaut oberhalb der Stimmlippen: Epiglottis, aryepiglottische Falten, Vestibulum, Taschenfalten, Recessus piriformis. Unterhalb übernimmt der N. laryngeus recurrens."},{"id":"02-F5","unit":"02","n":"F5","sec":"h-2-2-r-internus-der-waechter-oberhalb-der-stimmlippen","secT":"2.2 · R. internus: der „Wächter“ oberhalb der Stimmlippen","q":"Warum schließen beim Adduktorreflex beide Stimmlippen, obwohl der R. internus „nur“ sensibel ist?","ctx":null,"a":"Der R. internus liefert nur die Meldung. Der Hirnstamm schaltet sie auf den N. laryngeus recurrens beider Seiten um, und dieser bewegt die Schließmuskeln."},{"id":"02-F6","unit":"02","n":"F6","sec":"h-2-3-r-externus-der-nerv-fuer-die-tonhoehe","secT":"2.3 · R. externus: der Nerv für die Tonhöhe","q":"Welchen Muskel versorgt der R. externus, und was kann dieser Muskel ohne ihn nicht mehr?","ctx":null,"a":"Den M. cricothyroideus. Ohne ihn kann der Ringknorpel nicht gegen den Schildknorpel gekippt werden, die Stimmlippe wird nicht mehr verlängert und gespannt."},{"id":"02-F7","unit":"02","n":"F7","sec":"h-2-3-r-externus-der-nerv-fuer-die-tonhoehe","secT":"2.3 · R. externus: der Nerv für die Tonhöhe","q":"Neben welcher Arterie verläuft er, und welche Cernea-Typen gelten als gefährdet?","ctx":null,"a":"Neben der A. thyroidea superior. Gefährdet sind Typ 2a (Kreuzung weniger als 1 cm über dem oberen Pol) und Typ 2b (Kreuzung unterhalb des Oberrands)."},{"id":"02-F8","unit":"02","n":"F8","sec":"h-2-4-was-passiert-wenn-ein-ast-ausfaellt","secT":"2.4 · Was passiert, wenn ein Ast ausfällt?","q":"Warum wird eine Lähmung des R. externus so oft übersehen?","ctx":null,"a":"Die Stimmlippen öffnen und schließen normal, und die Sprechstimme klingt fast normal. Der Ausfall zeigt sich vor allem in der Höhe, die man gezielt prüfen muss."},{"id":"02-F9","unit":"02","n":"F9","sec":"h-2-4-was-passiert-wenn-ein-ast-ausfaellt","secT":"2.4 · Was passiert, wenn ein Ast ausfällt?","q":"Was bedeutet „stille Aspiration“, und warum passt sie zu einem Ausfall des R. internus?","ctx":null,"a":"Material gelangt unter die Stimmlippen in die Atemwege, ohne dass Husten ausgelöst wird. Ohne Empfindung oberhalb der Stimmlippen startet der Schutzreflex nicht."},{"id":"02-F10","unit":"02","n":"F10","sec":"h-2-5-zwei-mini-faelle","secT":"2.5 · Zwei Mini-Fälle","q":"Welcher Nerv ist wahrscheinlich verletzt? Welche zwei Untersuchungen würden den Verdacht stützen, und was erwartest du im Stimmfeld?","ctx":{"head":"Erwachsene · Frau K., 34, Chorsopranistin (aus Abschnitt 1)","html":"Zur Erinnerung: Nach der Schilddrüsenoperation erreicht sie ihre hohen Töne nicht mehr, ihre Stimme ermüdet, beide Stimmlippen öffnen und schließen. Im Operationsbericht steht, dass die Gefäße am oberen Pol schwierig darzustellen waren."},"a":"Der R. externus des N. laryngeus superior, beim Abbinden der Gefäße am oberen Pol gefährdet. Stützen: Stimmfeldmessung bzw. Glissando (die obere Grenze ist abgesenkt, der Umfang kleiner) und Larynx-EMG des M. cricothyroideus."},{"id":"02-F11","unit":"02","n":"F11","sec":"h-2-5-zwei-mini-faelle","secT":"2.5 · Zwei Mini-Fälle","q":"Welcher Nerv meldet die Flüssigkeit am Kehlkopfeingang an den Hirnstamm? Warum reagiert ein Frühgeborenes eher mit Atempause als mit Husten, und was tust du als Logopädin zuerst?","ctx":{"head":"Kind · Lena, Frühgeborene, 4 Wochen alt","html":"Beim Trinken aus der Flasche macht Lena manchmal eine Atempause, wird blass und ihr Herzschlag wird langsamer. Husten tut sie dabei kaum."},"a":"Der N. laryngeus superior (R. internus). Beim unreifen Säugling überwiegt der laryngeale Chemoreflex mit Atempause und langsamerem Herzschlag; Husten entwickelt sich erst mit der Reifung. Zuerst: Trinken unterbrechen, das Kind beobachten und die Episoden umgehend an die Ärztin melden; die Schluckabklärung erfolgt im Team."},{"id":"03-F1","unit":"03","n":"F1","sec":"h-3-1-der-umweg-erst-nach-unten-dann-zurueck-nach-oben","secT":"3.1 · Der Umweg: erst nach unten, dann zurück nach oben","q":"Um welche Arterie schlingt sich der rechte, um welche der linke N. laryngeus recurrens?","ctx":null,"a":"Rechts um die A. subclavia dextra, links um den Aortenbogen (seitlich vom Lig. arteriosum)."},{"id":"03-F2","unit":"03","n":"F2","sec":"h-3-1-der-umweg-erst-nach-unten-dann-zurueck-nach-oben","secT":"3.1 · Der Umweg: erst nach unten, dann zurück nach oben","q":"In welcher Rinne steigen beide Nerven zum Kehlkopf auf?","ctx":null,"a":"In der Rinne zwischen Luftröhre und Speiseröhre (Sulcus tracheooesophageus)."},{"id":"03-F3","unit":"03","n":"F3","sec":"h-3-2-warum-der-umweg-ein-blick-in-die-embryologie","secT":"3.2 · Warum der Umweg? Ein Blick in die Embryologie","q":"Unter welchem embryonalen Gefäß hakt sich der Nerv ursprünglich ein, und was wird daraus links?","ctx":null,"a":"Unter der Arterie des 6. Schlundbogens. Links bleibt sie als Ductus arteriosus erhalten und wird zum Lig. arteriosum."},{"id":"03-F4","unit":"03","n":"F4","sec":"h-3-2-warum-der-umweg-ein-blick-in-die-embryologie","secT":"3.2 · Warum der Umweg? Ein Blick in die Embryologie","q":"Was ist ein nicht-rekurrenter N. laryngeus, auf welcher Seite kommt er vor, und womit hängt er zusammen?","ctx":null,"a":"Ein Nerv, der direkt am Hals vom N. vagus zum Kehlkopf zieht, ohne Schlinge. Fast nur rechts (≈ 0,7 %), meist zusammen mit einer A. lusoria, also einer rechten Schlüsselbeinarterie, die hinter der Speiseröhre von der Aorta abgeht."},{"id":"03-F5","unit":"03","n":"F5","sec":"h-3-3-am-hals-die-gefaehrdete-strecke","secT":"3.3 · Am Hals: die gefährdete Strecke","q":"An welchem Band ist der Nerv bei der Schilddrüsenoperation am stärksten gefährdet?","ctx":null,"a":"Am Berry-Band, wo die Schilddrüse seitlich an der Luftröhre befestigt ist."},{"id":"03-F6","unit":"03","n":"F6","sec":"h-3-3-am-hals-die-gefaehrdete-strecke","secT":"3.3 · Am Hals: die gefährdete Strecke","q":"Wo tritt der Nerv in den Kehlkopf ein, und wie heißt sein Endstück?","ctx":null,"a":"Unter dem Unterrand des unteren Schlundschnürers, direkt hinter dem Krikothyreoidgelenk; das Endstück heißt N. laryngeus inferior."},{"id":"03-F7","unit":"03","n":"F7","sec":"h-3-3-am-hals-die-gefaehrdete-strecke","secT":"3.3 · Am Hals: die gefährdete Strecke","q":"Welcher Ast führt bei einer Teilung die motorischen Fasern?","ctx":null,"a":"Der vordere Ast."},{"id":"03-F8","unit":"03","n":"F8","sec":"h-3-4-was-der-n-laryngeus-recurrens-versorgt","secT":"3.4 · Was der N. laryngeus recurrens versorgt","q":"Welchen inneren Kehlkopfmuskel versorgt der N. laryngeus recurrens <i>nicht</i>?","ctx":null,"a":"Den M. cricothyroideus (Antikus); den versorgt der R. externus des N. laryngeus superior."},{"id":"03-F9","unit":"03","n":"F9","sec":"h-3-4-was-der-n-laryngeus-recurrens-versorgt","secT":"3.4 · Was der N. laryngeus recurrens versorgt","q":"Welche Schleimhaut versorgt er sensibel, und mit welchem Nerv ist er oft über die Galen-Anastomose verbunden?","ctx":null,"a":"Die Schleimhaut unterhalb der Stimmlippen; über die Galen-Anastomose ist er mit dem R. internus des N. laryngeus superior verbunden."},{"id":"03-F10","unit":"03","n":"F10","sec":"h-3-5-vom-verlauf-zur-klinik-wer-ist-gefaehrdet","secT":"3.5 · Vom Verlauf zur Klinik: wer ist gefährdet?","q":"Nenne zwei Gründe, warum der linke Nerv häufiger ausfällt als der rechte.","ctx":null,"a":"Er ist länger und hat einen langen Abschnitt im Brustraum; dort liegen viele mögliche Ursachen wie Lungen- und Speiseröhrentumoren, Lymphknoten, Aorta und Herz bzw. Operationen daran."},{"id":"03-F11","unit":"03","n":"F11","sec":"h-3-5-vom-verlauf-zur-klinik-wer-ist-gefaehrdet","secT":"3.5 · Vom Verlauf zur Klinik: wer ist gefährdet?","q":"Warum ist ein Frühgeborenes nach Verschluss des Ductus arteriosus besonders gefährdet, und auf welcher Seite?","ctx":null,"a":"Der linke N. laryngeus recurrens schlingt sich direkt neben dem Ductus arteriosus um den Aortenbogen und kann beim Verschluss verletzt werden. Links."},{"id":"03-F12","unit":"03","n":"F12","sec":"h-3-6-zwei-mini-faelle","secT":"3.6 · Zwei Mini-Fälle","q":"Welcher Nerv ist betroffen? Warum ist gerade die linke Seite in seiner Situation verdächtig, und welche Untersuchung muss jetzt folgen, bevor Stimmtherapie geplant wird?","ctx":{"head":"Erwachsene · Herr M., 67, Raucher","html":"Herr M. ist seit sechs Wochen heiser, seine Stimme ist leise und behaucht, beim Trinken verschluckt er sich öfter. Er hat in den letzten Monaten abgenommen. Operiert wurde er nie. Die Laryngoskopie zeigt eine stillstehende linke Stimmlippe."},"a":"Der linke N. laryngeus recurrens. Ohne Operation in der Vorgeschichte, als Raucher mit Gewichtsverlust, ist ein Tumor im Brustraum (z. B. Lungenkrebs oder Lymphknoten am Aortenbogen) verdächtig. Vor jeder Therapieplanung: ärztliche Abklärung mit Bildgebung des ganzen Nervenverlaufs, von der Schädelbasis bis zum Aortenbogen."},{"id":"03-F13","unit":"03","n":"F13","sec":"h-3-6-zwei-mini-faelle","secT":"3.6 · Zwei Mini-Fälle","q":"Welcher Nerv, welche Seite? Warum ist ihre Atmung ruhig, obwohl der Nerv auch den einzigen Öffner versorgt?","ctx":{"head":"Kind · Mia, 3 Monate, ehemaliges Frühgeborenes","html":"Mia hatte in der 2. Lebenswoche eine Operation zum Verschluss des Ductus arteriosus. Seitdem schreit sie leise und heiser und verschluckt sich beim Trinken; sie atmet ruhig und ohne Geräusch."},"a":"Der linke N. laryngeus recurrens. Ihre Atmung ist ruhig, weil nur eine Seite betroffen ist: Der rechte Postikus öffnet die Stimmritze weiter, das reicht zum Atmen. Gefährlich eng wird es erst, wenn beide Seiten ausfallen."},{"id":"04-F1","unit":"04","n":"F1","sec":"h-4-1-die-karte-und-was-bei-ausfall-verloren-geht","secT":"4.1 · Die Karte, und was bei Ausfall verloren geht","q":"Welche Funktionen bleiben erhalten, wenn auf einer Seite nur der N. laryngeus recurrens ausfällt?","ctx":null,"a":"Die Funktionen des N. laryngeus superior: Spannung und Tonhöhe über den Antikus sowie die Empfindung oberhalb der Stimmlippen mit dem Schutzreflex. Außerdem arbeitet die andere Seite normal."},{"id":"04-F2","unit":"04","n":"F2","sec":"h-4-1-die-karte-und-was-bei-ausfall-verloren-geht","secT":"4.1 · Die Karte, und was bei Ausfall verloren geht","q":"Bei welchem Ausfall bleibt die Stimme normal, und warum ist er trotzdem gefährlich?","ctx":null,"a":"Beim Ausfall des R. internus. Ohne Empfindung oberhalb der Stimmlippen startet der Schutzreflex nicht, und es kommt zu stiller Aspiration."},{"id":"04-F3","unit":"04","n":"F3","sec":"h-4-1-die-karte-und-was-bei-ausfall-verloren-geht","secT":"4.1 · Die Karte, und was bei Ausfall verloren geht","q":"Welche Wirkung in der Karte gibt es nur einmal, und welcher Muskel erzeugt sie?","ctx":null,"a":"„Öffnet die Glottis“, erzeugt allein vom Postikus (M. cricoarytaenoideus posterior)."},{"id":"04-F4","unit":"04","n":"F4","sec":"h-4-2-die-empfindungskarte-oben-mitte-unten","secT":"4.2 · Die Empfindungskarte: oben, Mitte, unten","q":"Welcher Nerv versorgt den Recessus piriformis sensibel?","ctx":null,"a":"Der R. internus des N. laryngeus superior."},{"id":"04-F5","unit":"04","n":"F5","sec":"h-4-2-die-empfindungskarte-oben-mitte-unten","secT":"4.2 · Die Empfindungskarte: oben, Mitte, unten","q":"Warum ist der Ausfall der Empfindung <i>oberhalb</i> der Stimmlippen für das Schlucken wichtiger als der unterhalb?","ctx":null,"a":"Material, das falsch läuft, trifft zuerst die Schleimhaut oberhalb der Stimmlippen. Fehlt dort die Empfindung, wird der Schutzreflex nicht ausgelöst, bevor das Material die Stimmlippen erreicht."},{"id":"04-F6","unit":"04","n":"F6","sec":"h-4-4-gemischte-uebung-der-laesionsdetektiv","secT":"4.4 · Gemischte Übung: der Läsionsdetektiv","q":"Eine Lehrerin kann nach einer Schilddrüsenoperation nicht mehr laut über die Klasse rufen, ihre Sprechstimme klingt normal, in der Laryngoskopie bewegen sich beide Stimmlippen.","ctx":null,"a":"R. externus des N. laryngeus superior (Antikus): Spannung und Tragfähigkeit fehlen, Beweglichkeit normal. Seite: die verletzte; nach Schilddrüsenoperation kann auch beidseits betroffen sein."},{"id":"04-F7","unit":"04","n":"F7","sec":"h-4-4-gemischte-uebung-der-laesionsdetektiv","secT":"4.4 · Gemischte Übung: der Läsionsdetektiv","q":"Ein Patient verschluckt sich nicht hörbar, aber in der Schluckendoskopie liegt Joghurt im Kehlkopfvorhof, ohne dass er reagiert. Die Stimme ist normal.","ctx":null,"a":"R. internus des N. laryngeus superior: fehlende Empfindung oberhalb der Stimmlippen, stille Aspiration bzw. Penetration."},{"id":"04-F8","unit":"04","n":"F8","sec":"h-4-4-gemischte-uebung-der-laesionsdetektiv","secT":"4.4 · Gemischte Übung: der Läsionsdetektiv","q":"Eine Frau hat seit einer Herzoperation eine behauchte, leise Stimme; die linke Stimmlippe steht still.","ctx":null,"a":"Linker N. laryngeus recurrens; er schlingt sich um den Aortenbogen und ist bei Herzoperationen gefährdet."},{"id":"04-F9","unit":"04","n":"F9","sec":"h-4-4-gemischte-uebung-der-laesionsdetektiv","secT":"4.4 · Gemischte Übung: der Läsionsdetektiv","q":"Beide Stimmlippen stehen nahe der Mitte, beim Einatmen pfeift es, die Stimme ist fast normal.","ctx":null,"a":"N. laryngeus recurrens beidseits: Beide Postikusmuskeln fehlen, die Stimmlippen stehen nahe der Mitte, deshalb Stridor bei guter Stimme."},{"id":"04-F10","unit":"04","n":"F10","sec":"h-4-4-gemischte-uebung-der-laesionsdetektiv","secT":"4.4 · Gemischte Übung: der Läsionsdetektiv","q":"Die rechte Stimmlippe steht still, <i>und</i> das Gaumensegel hebt sich rechts schlechter, <i>und</i> der Patient spürt Getränke rechts im Hals nicht. Wo liegt die Läsion eher: am N. laryngeus recurrens oder höher am N. vagus?","ctx":null,"a":"Höher am N. vagus, oberhalb des Abgangs des N. laryngeus superior: Gaumensegel (Rachenäste), Empfindung oben (R. internus) und Stimmlippe (N. laryngeus recurrens) sind zusammen betroffen. Eine reine Rekurrensparese würde Gaumen und Empfindung oben verschonen."},{"id":"04-F11","unit":"04","n":"F11","sec":"h-4-5-zwei-mini-faelle","secT":"4.5 · Zwei Mini-Fälle","q":"Welcher Nerv ist betroffen? Welche Zeilen der Tabelle in 4.3 erklären seine Symptome, und warum ist die Tonhöhe nicht ganz verloren?","ctx":{"head":"Erwachsene · Herr B., 55, nach Operation an der Halswirbelsäule von vorn","html":"Seit der Operation ist Herr B. heiser und behaucht, er hält ein „a“ nur 5 Sekunden lang und verschluckt sich bei Wasser. Hohe Töne kann er noch ansteuern, aber ohne Kraft. Die rechte Stimmlippe bewegt sich nicht."},"a":"Rechter N. laryngeus recurrens: Er läuft im Operationsgebiet an der Luftröhre vorbei, und die rechte Stimmlippe steht still. Es passen die Zeilen Lateralis/Transversus (Spalt, Behauchtheit, kurze Tonhaltedauer, Verschlucken bei Wasser) und Vokalis (wenig Kraft). Der Antikus (N. laryngeus superior) arbeitet noch, deshalb ist Tonhöhe teilweise steuerbar."},{"id":"04-F12","unit":"04","n":"F12","sec":"h-4-5-zwei-mini-faelle","secT":"4.5 · Zwei Mini-Fälle","q":"Welche Muskeln arbeiten bei Paul nicht, und warum passt ein kräftiges Schreien dazu? Warum kann die Ursache im Gehirn liegen, obwohl die Muskeln im Kehlkopf sitzen?","ctx":{"head":"Kind · Paul, 5 Monate","html":"Paul hat eine Fehlbildung am Übergang vom Gehirn zum Rückenmark (Chiari-Malformation) mit erhöhtem Hirndruck. Er atmet laut beim Einatmen, besonders im Schlaf, schreit aber kräftig. Die Endoskopie zeigt beide Stimmlippen nahe der Mitte."},"a":"Beide Postikusmuskeln, also die Öffner beider Seiten. Die Stimmlippen stehen nahe der Mitte und können gut schwingen, deshalb ist das Schreien kräftig. Die Nervenzellen für die Kehlkopfmuskeln liegen im Hirnstamm (Nucleus ambiguus), und die Nervenwurzeln des N. vagus verlassen den Hirnstamm genau im Bereich, auf den eine Chiari-Malformation mit erhöhtem Hirndruck drücken oder an dem sie ziehen kann."},{"id":"05-F1","unit":"05","n":"F1","sec":"h-5-1-der-motor-luftdruck-gegen-elastisches-gewebe","secT":"5.1 · Der Motor: Luftdruck gegen elastisches Gewebe","q":"Was machen die Muskeln bei der Stimmgebung, und was machen Luftdruck und Elastizität?","ctx":null,"a":"Die Muskeln schließen die Stimmlippen und stellen ihre Spannung ein. Luftdruck öffnet sie, die Elastizität des Gewebes schließt sie wieder; so entsteht die Schwingung von selbst."},{"id":"05-F2","unit":"05","n":"F2","sec":"h-5-1-der-motor-luftdruck-gegen-elastisches-gewebe","secT":"5.1 · Der Motor: Luftdruck gegen elastisches Gewebe","q":"Welcher Teil der Stimmlippe öffnet und schließt sich zuerst, und wie heißt die daraus entstehende Welle?","ctx":null,"a":"Die Unterkante öffnet und schließt zuerst; die Welle heißt Randkantenverschiebung (mukosale Welle)."},{"id":"05-F3","unit":"05","n":"F3","sec":"h-5-2-der-bau-der-stimmlippe-body-und-cover","secT":"5.2 · Der Bau der Stimmlippe: Body und Cover","q":"Ordne zu: Reinke-Raum, Lig. vocale, M. vocalis → Cover, Übergang, Body.","ctx":null,"a":"Reinke-Raum → Cover; Lig. vocale → Übergang; M. vocalis → Body."},{"id":"05-F4","unit":"05","n":"F4","sec":"h-5-2-der-bau-der-stimmlippe-body-und-cover","secT":"5.2 · Der Bau der Stimmlippe: Body und Cover","q":"Welche Schicht betrifft eine Rekurrensparese vor allem, welche ein Stimmlippenknötchen?","ctx":null,"a":"Rekurrensparese: Body (der M. vocalis wird schlaff). Stimmlippenknötchen: Cover."},{"id":"05-F5","unit":"05","n":"F5","sec":"h-5-3-tonhoehe-lautstaerke-register-wer-stellt-was-ein","secT":"5.3 · Tonhöhe, Lautstärke, Register: wer stellt was ein?","q":"Welcher Muskel hebt vor allem die Tonhöhe, und welcher Nerv versorgt ihn?","ctx":null,"a":"Der M. cricothyroideus (Antikus), versorgt vom R. externus des N. laryngeus superior."},{"id":"05-F6","unit":"05","n":"F6","sec":"h-5-3-tonhoehe-lautstaerke-register-wer-stellt-was-ein","secT":"5.3 · Tonhöhe, Lautstärke, Register: wer stellt was ein?","q":"Wovon hängt die Lautstärke ab? Nenne zwei Faktoren.","ctx":null,"a":"Vom subglottischen Druck (Atemdruck) und davon, wie lange und fest die Stimmlippen pro Zyklus geschlossen sind."},{"id":"05-F7","unit":"05","n":"F7","sec":"h-5-3-tonhoehe-lautstaerke-register-wer-stellt-was-ein","secT":"5.3 · Tonhöhe, Lautstärke, Register: wer stellt was ein?","q":"Welcher Muskel überwiegt in der Bruststimme, welcher in der Kopfstimme?","ctx":null,"a":"Bruststimme: Thyroarytänoid/Vokalis. Kopfstimme: Antikus."},{"id":"05-F8","unit":"05","n":"F8","sec":"h-5-5-zwei-mini-faelle","secT":"5.5 · Zwei Mini-Fälle","q":"Erkläre mit dem Schwingungszyklus, warum ihr die Luft ausgeht und warum sie nicht laut werden kann. Woher kommt der doppelte Klang?","ctx":{"head":"Erwachsene · Frau S., 48, Rekurrensparese links nach Schilddrüsenoperation","html":"Frau S. kann ein „a“ nur 4 Sekunden halten. Ihre Stimme ist leise und behaucht, bei längeren Sätzen geht ihr die Luft aus. Manchmal klingt die Stimme „doppelt“."},"a":"Die linke Stimmlippe kommt nicht zur Mitte; durch den Spalt entweicht ständig Luft. Der subglottische Druck kann sich nicht aufbauen (Schritt 1 des Zyklus fehlt teilweise), deshalb wird sie nicht laut und verbraucht ihre Luft schnell. Der doppelte Klang entsteht, weil die schlaffe linke Stimmlippe mit einer anderen Frequenz schwingt als die gesunde rechte."},{"id":"05-F9","unit":"05","n":"F9","sec":"h-5-5-zwei-mini-faelle","secT":"5.5 · Zwei Mini-Fälle","q":"Liegt hier eine Nervenlähmung vor? Welche Schicht der Stimmlippe ist betroffen, und warum klingt die Stimme eher rau als stark behaucht?","ctx":{"head":"Kind · Lukas, 7, „Schreikind“ im Fußballverein","html":"Lukas ist seit Monaten heiser, seine Stimme klingt rau. In der Laryngoskopie bewegen sich beide Stimmlippen normal; an beiden sieht man kleine Verdickungen am Übergang vom vorderen zum mittleren Drittel, beim Schließen bleibt vorne und hinten ein kleiner Spalt (Sanduhrform)."},"a":"Nein, die Beweglichkeit ist normal. Betroffen ist das Cover; die Knötchen machen die Hülle steif und unregelmäßig, deshalb schwingen die Ränder unregelmäßig und die Stimme klingt rau. Weil die Muskeln normal schließen, bleibt nur ein kleiner Spalt, also weniger Behauchtheit als bei einer Lähmung."},{"id":"06-F1","unit":"06","n":"F1","sec":"h-6-1-drei-verschlussebenen","secT":"6.1 · Drei Verschlussebenen","q":"Nenne die drei Verschlussebenen von unten nach oben.","ctx":null,"a":"Stimmlippen, Taschenfalten, Kehlkopfeingang (aryepiglottische Falten, Stellknorpel, Kehldeckel)."},{"id":"06-F2","unit":"06","n":"F2","sec":"h-6-1-drei-verschlussebenen","secT":"6.1 · Drei Verschlussebenen","q":"Warum kippt der Kehldeckel größtenteils passiv?","ctx":null,"a":"Er wird umgelegt, wenn der Kehlkopf nach oben vorn gezogen wird und der Zungengrund nach hinten drückt."},{"id":"06-F3","unit":"06","n":"F3","sec":"h-6-2-schlucken-der-anteil-des-kehlkopfs","secT":"6.2 · Schlucken: der Anteil des Kehlkopfs","q":"Welche Schritte der pharyngealen Phase steuert der N. vagus, welcher Schritt gehört nicht zu ihm?","ctx":null,"a":"N. vagus: Gaumensegelschluss, Kehlkopfverschluss, Rachenmuskeln, Öffnung des oberen Speiseröhrenschließmuskels, Empfindung am Kehlkopfeingang. Nicht: die Kehlkopfhebung (Muskeln oberhalb des Zungenbeins, andere Hirnnerven)."},{"id":"06-F4","unit":"06","n":"F4","sec":"h-6-2-schlucken-der-anteil-des-kehlkopfs","secT":"6.2 · Schlucken: der Anteil des Kehlkopfs","q":"Warum ist das Ausatmen nach dem Schlucken ein Schutz?","ctx":null,"a":"Die ausgeatmete Luft bläst Reste, die am Kehlkopfeingang liegen, nach oben weg, statt sie mit dem nächsten Atemzug in die Luftröhre zu ziehen."},{"id":"06-F5","unit":"06","n":"F5","sec":"h-6-2-schlucken-der-anteil-des-kehlkopfs","secT":"6.2 · Schlucken: der Anteil des Kehlkopfs","q":"Woran merkt man eine Stimmlippenlähmung beim Säugling oft zuerst?","ctx":null,"a":"Beim Trinken: Husten oder Verschlucken, lange Trinkzeiten, Atempausen, wiederkehrende Lungenentzündungen."},{"id":"06-F6","unit":"06","n":"F6","sec":"h-6-3-husten-und-pressen","secT":"6.3 · Husten und Pressen","q":"Welche Hustenphase fällt bei einer einseitigen Rekurrensparese am stärksten aus, und warum?","ctx":null,"a":"Die Kompressionsphase: Ohne festen Schluss baut sich kein Druck unter den Stimmlippen auf."},{"id":"06-F7","unit":"06","n":"F7","sec":"h-6-3-husten-und-pressen","secT":"6.3 · Husten und Pressen","q":"Warum ist bei beidseitigem Postikusausfall vor allem das Einatmen betroffen?","ctx":null,"a":"Beim Einatmen muss der Postikus die Stimmritze aktiv weiten; beim Ausatmen drückt die Luft die Stimmlippen von unten etwas auseinander."},{"id":"06-F8","unit":"06","n":"F8","sec":"h-6-5-zwei-mini-faelle","secT":"6.5 · Zwei Mini-Fälle","q":"Welcher Nerv? Warum gerade dünne Flüssigkeiten, und warum ist ihr Husten schwach? Warum hustet sie überhaupt, statt still zu aspirieren?","ctx":{"head":"Erwachsene · Frau R., 60, nach Operation am linken Lungenoberlappen","html":"Seit der Operation ist Frau R. heiser. Beim Wassertrinken hustet sie oft, aber der Husten ist schwach und „verhaucht“. Joghurt schluckt sie problemlos. Die linke Stimmlippe steht still."},"a":"Linker N. laryngeus recurrens (Operation in der Nähe des Aortenbogens). Dünne Flüssigkeiten fließen schnell und finden den Spalt der unvollständig schließenden Stimmritze; Joghurt fließt langsamer. Der Husten ist schwach, weil ohne Schluss kein Druck entsteht. Sie hustet, weil der R. internus des N. laryngeus superior intakt ist und die Empfindung oberhalb der Stimmlippen funktioniert."},{"id":"06-F9","unit":"06","n":"F9","sec":"h-6-5-zwei-mini-faelle","secT":"6.5 · Zwei Mini-Fälle","q":"Welcher Teil des Schutzes fehlt Mia? Warum ist das bei einem Säugling, der nur Flüssigkeit trinkt, besonders problematisch, und wer sollte an der Abklärung beteiligt sein?","ctx":{"head":"Kind · Mia, jetzt 4 Monate (aus Abschnitt 3)","html":"Mia hat eine linksseitige Rekurrensparese nach dem Verschluss des Ductus arteriosus. Sie trinkt sehr langsam, hustet beim Fläschchen, und hatte schon eine Lungenentzündung."},"a":"Der vollständige Verschluss der Stimmritze auf der linken Seite. Säuglinge trinken nur dünne Flüssigkeit, also genau die Konsistenz, die am leichtesten durch den Spalt läuft, und sie trinken viele Male am Tag. An der Abklärung beteiligt sind Kinderärztin bzw. Kinder-HNO oder Phoniatrie, Logopädin mit Schwerpunkt Schlucken und gegebenenfalls Ernährungsberatung; die instrumentelle Diagnostik entscheidet über Maßnahmen wie angedickte Nahrung oder Haltung."},{"id":"07-F1","unit":"07","n":"F1","sec":"h-7-1-wo-steht-die-gelaehmte-stimmlippe","secT":"7.1 · Wo steht die gelähmte Stimmlippe?","q":"Nenne die vier Positionsbegriffe von innen nach außen.","ctx":null,"a":"Median, paramedian, intermediär, lateral."},{"id":"07-F2","unit":"07","n":"F2","sec":"h-7-1-wo-steht-die-gelaehmte-stimmlippe","secT":"7.1 · Wo steht die gelähmte Stimmlippe?","q":"Warum kann man aus der Position nicht sicher auf den Läsionsort schließen? Zwei Gründe.","ctx":null,"a":"Zum Beispiel: Ein noch arbeitender Antikus zieht die Stimmlippe zur Mitte; nachgewachsene Fasern können in falsche Muskeln laufen (Synkinesie); der Muskel schwindet mit der Zeit."},{"id":"07-F3","unit":"07","n":"F3","sec":"h-7-2-einseitige-rekurrensparese","secT":"7.2 · Einseitige Rekurrensparese","q":"Welche Muskeln fallen bei einer einseitigen Rekurrensparese aus, welche Funktionen bleiben?","ctx":null,"a":"Aus: Postikus, Lateralis, Transversus, Thyroarytänoid auf dieser Seite. Bleiben: Antikus (N. laryngeus superior) und die Empfindung oberhalb der Stimmlippen."},{"id":"07-F4","unit":"07","n":"F4","sec":"h-7-2-einseitige-rekurrensparese","secT":"7.2 · Einseitige Rekurrensparese","q":"Warum kann sich die Stimme erholen, obwohl die Stimmlippe stillsteht?","ctx":null,"a":"Die Stellung und Spannung der gelähmten Stimmlippe können sich verbessern, und die gesunde Seite gleicht aus, indem sie über die Mitte geht."},{"id":"07-F5","unit":"07","n":"F5","sec":"h-7-2-einseitige-rekurrensparese","secT":"7.2 · Einseitige Rekurrensparese","q":"Was ist das Ziel der Stimmtherapie, und welcher Ausgleich soll vermieden werden?","ctx":null,"a":"Ein möglichst guter Schluss mit guter Atem-Stimm-Koordination und Ausdauer, ohne Pressen bzw. Taschenfaltenstimme als Ausgleich."},{"id":"07-F6","unit":"07","n":"F6","sec":"h-7-3-beidseitige-rekurrensparese","secT":"7.3 · Beidseitige Rekurrensparese","q":"Warum ist bei beidseitiger Rekurrensparese die Atmung gefährdet, die Stimme aber oft gut?","ctx":null,"a":"Beide Öffner fallen aus, die Stimmlippen stehen nahe der Mitte: zu eng zum Einatmen, aber nah genug zum Schwingen."},{"id":"07-F7","unit":"07","n":"F7","sec":"h-7-3-beidseitige-rekurrensparese","secT":"7.3 · Beidseitige Rekurrensparese","q":"Welcher Zielkonflikt besteht bei allen Operationen, die die Stimmritze erweitern?","ctx":null,"a":"Mehr Luft bedeutet schlechtere Stimme und manchmal schlechteren Schutz beim Schlucken."},{"id":"07-F8","unit":"07","n":"F8","sec":"h-7-5-hohe-vaguslaesion-und-die-frage-wie-hoch","secT":"7.5 · Hohe Vagusläsion und die Frage „Wie hoch?“","q":"Zu welcher Seite weicht das Zäpfchen bei einer hohen Vagusläsion ab?","ctx":null,"a":"Zur gesunden Seite."},{"id":"07-F9","unit":"07","n":"F9","sec":"h-7-5-hohe-vaguslaesion-und-die-frage-wie-hoch","secT":"7.5 · Hohe Vagusläsion und die Frage „Wie hoch?“","q":"Nenne drei Zeichen, die für eine hohe Vagusläsion sprechen und bei einer reinen Rekurrensparese fehlen.","ctx":null,"a":"Zum Beispiel: Gaumensegel hebt sich einseitig nicht, Zäpfchen weicht ab, Kulissenphänomen, offenes Näseln, Flüssigkeit in der Nase, fehlende Empfindung oberhalb der Stimmlippen, Speichelsee im Recessus piriformis."},{"id":"07-F10","unit":"07","n":"F10","sec":"h-7-5-hohe-vaguslaesion-und-die-frage-wie-hoch","secT":"7.5 · Hohe Vagusläsion und die Frage „Wie hoch?“","q":"Warum lähmt ein einseitiger Großhirninfarkt die Stimmlippe fast nie?","ctx":null,"a":"Die Kerngebiete für die Kehlkopfmuskeln werden von beiden Großhirnhälften angesteuert; fällt eine aus, übernimmt die andere weitgehend."},{"id":"07-F11","unit":"07","n":"F11","sec":"h-7-7-zwei-mini-faelle","secT":"7.7 · Zwei Mini-Fälle","q":"Welche Lähmung, auf welcher Höhe? Was sagst du ihr zur Prognose, und wann sollte die Stimmtherapie beginnen?","ctx":{"head":"Erwachsene · Frau D., 45, Lehrerin","html":"Nach einer Erkältung ist Frau D. seit drei Wochen heiser und behaucht. Sie hatte keine Operation. Die linke Stimmlippe steht paramedian, Gaumensegel und Rachen sind unauffällig. Die Bildgebung vom Schädel bis zum Brustkorb ist unauffällig."},"a":"Einseitige Rekurrensparese links, wahrscheinlich idiopathisch (Gaumen und Rachen unauffällig, also keine hohe Läsion; Bildgebung unauffällig). Prognose: gute Chance, dass sich die Stimme erholt, meist in den ersten Monaten; die Beweglichkeit kehrt seltener zurück. Stimmtherapie früh beginnen, jetzt."},{"id":"07-F12","unit":"07","n":"F12","sec":"h-7-7-zwei-mini-faelle","secT":"7.7 · Zwei Mini-Fälle","q":"Warum hat man zuerst den Atemweg gesichert und nicht die Stimmritze dauerhaft erweitert? Was kann die Logopädin jetzt für Paul tun?","ctx":{"head":"Kind · Paul, jetzt 7 Monate (aus Abschnitt 4)","html":"Paul hat eine beidseitige Stimmlippenlähmung bei Chiari-Malformation. Er hatte zweimal Atemnot bei Infekten und hat jetzt eine Tracheotomie."},"a":"Bei Kindern bessert sich eine beidseitige Lähmung oft spontan, und eine dauerhafte Erweiterung würde Stimme und Schluckschutz bleibend verschlechtern; deshalb erst sichern und abwarten. Die Logopädin kann mit Sprechventil an Stimme und Lautentwicklung arbeiten, das Trinken und Schlucken begleiten und die Eltern beraten."},{"id":"08-F1","unit":"08","n":"F1","sec":"h-8-1-drei-fragen-ein-entscheidungsbaum","secT":"8.1 · Drei Fragen, ein Entscheidungsbaum","q":"Was ist die erste Frage bei jeder Heiserkeit mit Laryngoskopiebefund?","ctx":null,"a":"Bewegt sich die Stimmlippe?"},{"id":"08-F2","unit":"08","n":"F2","sec":"h-8-1-drei-fragen-ein-entscheidungsbaum","secT":"8.1 · Drei Fragen, ein Entscheidungsbaum","q":"Welche Untersuchung trennt eine Nervenlähmung von einer mechanischen Fixierung, und was zeigt sie jeweils?","ctx":null,"a":"Das Larynx-EMG: bei Lähmung gestört, bei mechanischer Fixierung normal. Ergänzend die Prüfung der Gelenkbeweglichkeit in Narkose."},{"id":"08-F3","unit":"08","n":"F3","sec":"h-8-2-unbeweglich-aber-nicht-gelaehmt","secT":"8.2 · Unbeweglich, aber nicht gelähmt","q":"Nenne drei mechanische Ursachen einer unbeweglichen Stimmlippe.","ctx":null,"a":"Aryknorpelluxation, Fixierung des Krikoarytänoidgelenks (z. B. Rheuma), hintere Glottisstenose, Tumor."},{"id":"08-F4","unit":"08","n":"F4","sec":"h-8-2-unbeweglich-aber-nicht-gelaehmt","secT":"8.2 · Unbeweglich, aber nicht gelähmt","q":"Ein Patient ist nach einer langen Intensivbehandlung mit Intubation heiser, eine Stimmlippe steht still. Warum muss man an eine Aryknorpelluxation denken, und warum ist das eilig?","ctx":null,"a":"Intubation kann den Stellknorpel aus dem Gelenk drücken; das sieht aus wie eine Lähmung. Eine frühe Reposition kann die Beweglichkeit wiederherstellen; später wird das schwieriger."},{"id":"08-F5","unit":"08","n":"F5","sec":"h-8-3-beweglich-aber-auffaellig-schlussmuster-und-schleimhaut","secT":"8.3 · Beweglich, aber auffällig: Schlussmuster und Schleimhaut","q":"Welches Schlussmuster spricht für eine Lähmung oder Fixierung, welches für Knötchen?","ctx":null,"a":"Einseitiger Spalt mit unbeweglicher Seite: Lähmung oder Fixierung. Sanduhr: Knötchen."},{"id":"08-F6","unit":"08","n":"F6","sec":"h-8-3-beweglich-aber-auffaellig-schlussmuster-und-schleimhaut","secT":"8.3 · Beweglich, aber auffällig: Schlussmuster und Schleimhaut","q":"Warum spricht „behaucht, aber normale Beweglichkeit“ gegen eine Rekurrensparese?","ctx":null,"a":"Bei einer Rekurrensparese steht die Stimmlippe still. Bewegt sie sich normal, liegt der Grund für die Behauchtheit woanders, z. B. hypofunktionelle Dysphonie, Presbyphonie oder Sulcus."},{"id":"08-F7","unit":"08","n":"F7","sec":"h-8-3-beweglich-aber-auffaellig-schlussmuster-und-schleimhaut","secT":"8.3 · Beweglich, aber auffällig: Schlussmuster und Schleimhaut","q":"Woran erkennst du im Gespräch eine spasmodische Dysphonie, und warum ist sie keine Vagusstörung?","ctx":null,"a":"Die Stimme klingt gepresst und abgehackt beim Sprechen, aber besser beim Singen, Lachen oder Flüstern. Ursache ist eine Bewegungsstörung im Gehirn (Dystonie); der N. vagus und die Muskeln sind gesund."},{"id":"08-F8","unit":"08","n":"F8","sec":"h-8-6-zwei-mini-faelle","secT":"8.6 · Zwei Mini-Fälle","q":"Welche Diagnose liegt nahe, und warum ist es keine Nervenlähmung? Was unterscheidet sie von einer hyperfunktionellen Dysphonie?","ctx":{"head":"Erwachsene · Frau H., 52, Verwaltungsangestellte","html":"Seit einem Jahr klingt ihre Stimme gepresst und „abgehackt“, als würde sie gewürgt. Beim Singen und Lachen klingt sie fast normal. In Ruhe bewegen sich beide Stimmlippen normal."},"a":"Spasmodische Dysphonie vom Adduktortyp. Beweglichkeit ist in Ruhe normal, und die Auffälligkeit hängt von der Aufgabe ab. Bei einer hyperfunktionellen Dysphonie ist das Pressen gleichmäßiger und bessert sich nicht so typisch beim Singen oder Lachen; sie spricht auf Stimmtherapie an, während die spasmodische Dysphonie meist mit Botulinumtoxin behandelt wird."},{"id":"08-F9","unit":"08","n":"F9","sec":"h-8-6-zwei-mini-faelle","secT":"8.6 · Zwei Mini-Fälle","q":"Was beunruhigt dich, an welche Erkrankung denkst du, und was tust du?","ctx":{"head":"Kind · Ben, 4 Jahre","html":"Ben ist seit einigen Monaten heiser, und es wird langsam schlimmer. Neuerdings atmet er im Schlaf laut. Die Eltern denken an „Schreiknötchen“, weil er viel ruft, und möchten direkt Stimmtherapie."},"a":"Zunehmende Heiserkeit plus neues Atemgeräusch sind Warnzeichen; das passt nicht zu einfachen Knötchen. Denken muss man an eine Larynxpapillomatose. Keine Stimmtherapie beginnen, sondern umgehend zur HNO-Ärztin bzw. Kinder-HNO überweisen und den Eltern erklären, warum."}],"terms":[{"term":"6. Schlundbogens","lat":null,"ctx":"Er zieht unter dem Gefäß des 6. Schlundbogens zum Kehlkopf.","unit":"03","sec":"h-3-2-warum-der-umweg-ein-blick-in-die-embryologie","secT":"3.2 · Warum der Umweg? Ein Blick in die Embryologie","more":[]},{"term":"A. laryngea superior","lat":null,"ctx":"Der R. internus zieht zusammen mit der A. laryngea superior durch die Membrana thyrohyoidea, die Bindegewebsplatte zwischen Zungenbein und Schildknorpel.","unit":"02","sec":"h-2-2-r-internus-der-waechter-oberhalb-der-stimmlippen","secT":"2.2 · R. internus: der „Wächter“ oberhalb der Stimmlippen","more":[]},{"term":"A. lusoria","lat":null,"ctx":"Die wichtigste Variante: Wenn rechts die Schlüsselbeinarterie nicht normal angelegt ist, sondern als A. lusoria hinter der Speiseröhre von der Aorta abgeht, gibt es nichts, unter dem sich der rechte Nerv einhaken könnte.","unit":"03","sec":"h-3-2-warum-der-umweg-ein-blick-in-die-embryologie","secT":"3.2 · Warum der Umweg? Ein Blick in die Embryologie","more":[]},{"term":"A. subclavia dextra","lat":"rechte Schlüsselbeinarterie","ctx":"Rechts verlässt er den N. vagus vor der A. subclavia dextra (rechte Schlüsselbeinarterie), zieht unter ihr hindurch und steigt wieder auf.","unit":"03","sec":"h-3-1-der-umweg-erst-nach-unten-dann-zurueck-nach-oben","secT":"3.1 · Der Umweg: erst nach unten, dann zurück nach oben","more":[]},{"term":"A. thyroidea inferior","lat":null,"ctx":"die A. thyroidea inferior: Der Nerv kann vor, hinter oder zwischen ihren Ästen liegen.","unit":"03","sec":"h-3-3-am-hals-die-gefaehrdete-strecke","secT":"3.3 · Am Hals: die gefährdete Strecke","more":[]},{"term":"A. thyroidea superior","lat":null,"ctx":"Unterwegs liegt er eng an der A. thyroidea superior, die zum oberen Pol der Schilddrüse zieht.","unit":"02","sec":"h-2-3-r-externus-der-nerv-fuer-die-tonhoehe","secT":"2.3 · R. externus: der Nerv für die Tonhöhe","more":[]},{"term":"Aortenbogen","lat":"Arcus aortae","ctx":"Links verlässt er den N. vagus vor dem Aortenbogen (Arcus aortae), zieht unter ihm hindurch, direkt seitlich vom Lig. arteriosum, und steigt wieder auf.","unit":"03","sec":"h-3-1-der-umweg-erst-nach-unten-dann-zurueck-nach-oben","secT":"3.1 · Der Umweg: erst nach unten, dann zurück nach oben","more":[]},{"term":"Articulatio cricoarytenoidea","lat":"Krikoarytänoidgelenk","ctx":"Die Articulatio cricoarytenoidea (Krikoarytänoidgelenk) liegt zwischen der Basis jedes Stellknorpels und einer ovalen Gelenkfläche auf dem oberen Rand der Ringknorpelplatte.","unit":"01","sec":"h-1-3-gelenk-2-das-krikoarytaenoidgelenk-schwenkt-den-proc-voc","secT":"1.3 · Gelenk 2: Das Krikoarytänoidgelenk schwenkt den Proc. vocalis","more":[]},{"term":"Articulatio cricothyroidea","lat":"Krikothyreoidgelenk","ctx":"Die Articulatio cricothyroidea (Krikothyreoidgelenk) ist auf jeder Seite ein kleines echtes Gelenk zwischen dem unteren Horn des Schildknorpels (Cornu inferius) und einer Gelenkfläche seitlich am Ringknorpel.","unit":"01","sec":"h-1-2-gelenk-1-das-krikothyreoidgelenk-kippt","secT":"1.2 · Gelenk 1: Das Krikothyreoidgelenk kippt","more":[]},{"term":"Aryknorpelluxation","lat":null,"ctx":"Aryknorpelluxation: Der Stellknorpel springt bei einer Intubation oder Verletzung aus seinem Gelenk.","unit":"08","sec":"h-8-2-unbeweglich-aber-nicht-gelaehmt","secT":"8.2 · Unbeweglich, aber nicht gelähmt","more":[]},{"term":"Äußere","lat":null,"ctx":"Äußere Kehlkopfmuskeln, etwa die geraden Halsmuskeln, heben oder senken den ganzen Kehlkopf und gehören nicht zu diesem Abschnitt.","unit":"01","sec":"h-1-4-die-fuenf-inneren-muskelgruppen","secT":"1.4 · Die fünf inneren Muskelgruppen","more":[]},{"term":"Berry-Band","lat":null,"ctx":"das Berry-Band: ein straffes Band, das die Schilddrüse seitlich an der Luftröhre festhält.","unit":"03","sec":"h-3-3-am-hals-die-gefaehrdete-strecke","secT":"3.3 · Am Hals: die gefährdete Strecke","more":[]},{"term":"Body-Cover-Modell","lat":null,"ctx":"Im Body-Cover-Modell nach Hirano ist er der „Körper“ (Body), während die Schleimhaut darüber (Epithel plus die lockere Schicht namens Reinke-Raum) die „Hülle“ (Cover) bildet, die beim Sprechen Wellen schlägt.","unit":"01","sec":"h-1-4-die-fuenf-inneren-muskelgruppen","secT":"1.4 · Die fünf inneren Muskelgruppen","more":[]},{"term":"Bruststimme","lat":null,"ctx":"In der Bruststimme (Modalregister) überwiegt der Thyroarytänoid: Die Stimmlippen sind dick und berühren sich über eine große Fläche.","unit":"05","sec":"h-5-3-tonhoehe-lautstaerke-register-wer-stellt-was-ein","secT":"5.3 · Tonhöhe, Lautstärke, Register: wer stellt was ein?","more":[]},{"term":"Cernea","lat":null,"ctx":"Die Einteilung nach Cernea (1992) beschreibt das:","unit":"02","sec":"h-2-3-r-externus-der-nerv-fuer-die-tonhoehe","secT":"2.3 · R. externus: der Nerv für die Tonhöhe","more":[]},{"term":"Drehung um eine quere Achse","lat":null,"ctx":"Die Hauptbewegung ist eine Drehung um eine quere Achse durch beide Gelenke: Die zwei Knorpel kippen gegeneinander wie ein Visier, das sich vorne schließt.","unit":"01","sec":"h-1-2-gelenk-1-das-krikothyreoidgelenk-kippt","secT":"1.2 · Gelenk 1: Das Krikothyreoidgelenk kippt","more":[]},{"term":"Ductus arteriosus","lat":null,"ctx":"Bei Frühgeborenen wird ein offener Ductus arteriosus manchmal operativ verschlossen.","unit":"03","sec":"h-3-5-vom-verlauf-zur-klinik-wer-ist-gefaehrdet","secT":"3.5 · Vom Verlauf zur Klinik: wer ist gefährdet?","more":[]},{"term":"Epithel","lat":null,"ctx":"Cover (Hülle): das Epithel (die oberste Zellschicht) und darunter eine sehr lockere, fast gallertige Schicht, der Reinke-Raum (oberflächliche Lamina propria).","unit":"05","sec":"h-5-2-der-bau-der-stimmlippe-body-und-cover","secT":"5.2 · Der Bau der Stimmlippe: Body und Cover","more":[]},{"term":"Fixierung des Krikoarytänoidgelenks","lat":null,"ctx":"Fixierung des Krikoarytänoidgelenks, z. B. bei rheumatoider Arthritis: Das Gelenk ist entzündet oder versteift.","unit":"08","sec":"h-8-2-unbeweglich-aber-nicht-gelaehmt","secT":"8.2 · Unbeweglich, aber nicht gelähmt","more":[]},{"term":"Foramen jugulare","lat":null,"ctx":"Der N. vagus (N. X) verlässt den Schädel durch das Foramen jugulare.","unit":"02","sec":"h-2-1-ursprung-und-teilung","secT":"2.1 · Ursprung und Teilung","more":[]},{"term":"Galen-Anastomose","lat":"Ansa Galeni","ctx":"Im Kehlkopf ist er oft durch eine Verbindung mit dem R. internus des oberen Kehlkopfnervs verbunden, die Galen-Anastomose (Ansa Galeni); sie wurde in einer Studie bei 81 % der untersuchten Kehlköpfe gefunden und führt überwiegend sensible Fasern.","unit":"03","sec":"h-3-4-was-der-n-laryngeus-recurrens-versorgt","secT":"3.4 · Was der N. laryngeus recurrens versorgt","more":[]},{"term":"Ganglion","lat":null,"ctx":"Direkt darunter hat er eine Verdickung, das Ganglion inferius (Ganglion nodosum).","unit":"02","sec":"h-2-1-ursprung-und-teilung","secT":"2.1 · Ursprung und Teilung","more":[]},{"term":"Ganglion inferius","lat":"Ganglion nodosum","ctx":"Direkt darunter hat er eine Verdickung, das Ganglion inferius (Ganglion nodosum).","unit":"02","sec":"h-2-1-ursprung-und-teilung","secT":"2.1 · Ursprung und Teilung","more":[]},{"term":"Gleiten","lat":null,"ctx":"Sie erlaubt zwei gekoppelte Bewegungen: ein Kippen (Schaukeln) um die Längsachse der Gelenkfläche und ein Gleiten entlang dieser Fläche.","unit":"01","sec":"h-1-3-gelenk-2-das-krikoarytaenoidgelenk-schwenkt-den-proc-voc","secT":"1.3 · Gelenk 2: Das Krikoarytänoidgelenk schwenkt den Proc. vocalis","more":[]},{"term":"Grundfrequenz","lat":null,"ctx":"Tonhöhe ist die Zahl der Schwingungen pro Sekunde, die Grundfrequenz (F0, in Hertz).","unit":"05","sec":"h-5-3-tonhoehe-lautstaerke-register-wer-stellt-was-ein","secT":"5.3 · Tonhöhe, Lautstärke, Register: wer stellt was ein?","more":[]},{"term":"Hintere Glottisstenose","lat":null,"ctx":"Hintere Glottisstenose: eine Narbe zwischen den Stellknorpeln, oft nach langer Intubation.","unit":"08","sec":"h-8-2-unbeweglich-aber-nicht-gelaehmt","secT":"8.2 · Unbeweglich, aber nicht gelähmt","more":[]},{"term":"Innere","lat":null,"ctx":"Innere Kehlkopfmuskeln entspringen und setzen an Kehlkopfknorpeln an und bewegen diese gegeneinander.","unit":"01","sec":"h-1-4-die-fuenf-inneren-muskelgruppen","secT":"1.4 · Die fünf inneren Muskelgruppen","more":[]},{"term":"Intermediär","lat":null,"ctx":"Intermediär: zwischen Mitte und Atemstellung.","unit":"07","sec":"h-7-1-wo-steht-die-gelaehmte-stimmlippe","secT":"7.1 · Wo steht die gelähmte Stimmlippe?","more":[]},{"term":"Kippen (Schaukeln)","lat":null,"ctx":"Sie erlaubt zwei gekoppelte Bewegungen: ein Kippen (Schaukeln) um die Längsachse der Gelenkfläche und ein Gleiten entlang dieser Fläche.","unit":"01","sec":"h-1-3-gelenk-2-das-krikoarytaenoidgelenk-schwenkt-den-proc-voc","secT":"1.3 · Gelenk 2: Das Krikoarytänoidgelenk schwenkt den Proc. vocalis","more":[]},{"term":"Kopfstimme bzw. im Falsett","lat":null,"ctx":"In der Kopfstimme bzw. im Falsett überwiegt der Antikus: Die Stimmlippen sind dünn gedehnt, nur die Ränder schwingen, der Schluss ist kurz oder unvollständig.","unit":"05","sec":"h-5-3-tonhoehe-lautstaerke-register-wer-stellt-was-ein","secT":"5.3 · Tonhöhe, Lautstärke, Register: wer stellt was ein?","more":[]},{"term":"Kulissenphänomen","lat":null,"ctx":"Kulissenphänomen: Beim „a“-Sagen oder Würgen verschiebt sich die hintere Rachenwand zur gesunden Seite, wie ein Theatervorhang.","unit":"07","sec":"h-7-5-hohe-vaguslaesion-und-die-frage-wie-hoch","secT":"7.5 · Hohe Vagusläsion und die Frage „Wie hoch?“","more":[]},{"term":"Lamina","lat":null,"ctx":"Der Ringknorpel (Cartilago cricoidea) ist ein Ring, vorne niedrig und hinten hoch, wo er eine Platte bildet, die Lamina.","unit":"01","sec":"h-1-1-von-den-knorpeln-zum-ventil","secT":"1.1 · Von den Knorpeln zum Ventil","more":[]},{"term":"länger, dünner und straffer","lat":null,"ctx":"Die Stimmlippe wird länger, dünner und straffer und schwingt schneller: Die Tonhöhe steigt.","unit":"01","sec":"h-1-2-gelenk-1-das-krikothyreoidgelenk-kippt","secT":"1.2 · Gelenk 1: Das Krikothyreoidgelenk kippt","more":[]},{"term":"laryngeale Adduktorreflex","lat":null,"ctx":"Dieser laryngeale Adduktorreflex schließt sogar beide Seiten, wenn nur eine Seite gereizt wird.","unit":"02","sec":"h-2-2-r-internus-der-waechter-oberhalb-der-stimmlippen","secT":"2.2 · R. internus: der „Wächter“ oberhalb der Stimmlippen","more":[]},{"term":"laryngealen Chemoreflex","lat":null,"ctx":"Man nennt das den laryngealen Chemoreflex.","unit":"02","sec":"h-2-2-r-internus-der-waechter-oberhalb-der-stimmlippen","secT":"2.2 · R. internus: der „Wächter“ oberhalb der Stimmlippen","more":[]},{"term":"Larynx-EMG","lat":null,"ctx":"So unterscheidet man: Das Larynx-EMG ist bei mechanischer Fixierung normal, bei Lähmung gestört.","unit":"08","sec":"h-8-2-unbeweglich-aber-nicht-gelaehmt","secT":"8.2 · Unbeweglich, aber nicht gelähmt","more":[]},{"term":"Lateral","lat":null,"ctx":"Lateral: weit außen; früher „Kadaverstellung“ genannt.","unit":"07","sec":"h-7-1-wo-steht-die-gelaehmte-stimmlippe","secT":"7.1 · Wo steht die gelähmte Stimmlippe?","more":[]},{"term":"Lig. arteriosum","lat":null,"ctx":"Links verlässt er den N. vagus vor dem Aortenbogen (Arcus aortae), zieht unter ihm hindurch, direkt seitlich vom Lig. arteriosum, und steigt wieder auf.","unit":"03","sec":"h-3-1-der-umweg-erst-nach-unten-dann-zurueck-nach-oben","secT":"3.1 · Der Umweg: erst nach unten, dann zurück nach oben","more":[]},{"term":"M. cricothyroideus","lat":null,"ctx":"Zieht sich der M. cricothyroideus zusammen, zieht er den vorderen Ringknorpelbogen zum Schildknorpel hoch.","unit":"01","sec":"h-1-2-gelenk-1-das-krikothyreoidgelenk-kippt","secT":"1.2 · Gelenk 1: Das Krikothyreoidgelenk kippt","more":[{"unit":"02","sec":"h-2-3-r-externus-der-nerv-fuer-die-tonhoehe","secT":"2.3 · R. externus: der Nerv für die Tonhöhe"}]},{"term":"M. vocalis","lat":null,"ctx":"Der M. vocalis ist die Muskelschicht in der Stimmlippe.","unit":"01","sec":"h-1-4-die-fuenf-inneren-muskelgruppen","secT":"1.4 · Die fünf inneren Muskelgruppen","more":[{"unit":"05","sec":"h-5-2-der-bau-der-stimmlippe-body-und-cover","secT":"5.2 · Der Bau der Stimmlippe: Body und Cover"}]},{"term":"Median","lat":null,"ctx":"Median: in der Mitte, wie beim Sprechen.","unit":"07","sec":"h-7-1-wo-steht-die-gelaehmte-stimmlippe","secT":"7.1 · Wo steht die gelähmte Stimmlippe?","more":[]},{"term":"Membrana thyrohyoidea","lat":null,"ctx":"Der R. internus zieht zusammen mit der A. laryngea superior durch die Membrana thyrohyoidea, die Bindegewebsplatte zwischen Zungenbein und Schildknorpel.","unit":"02","sec":"h-2-2-r-internus-der-waechter-oberhalb-der-stimmlippen","secT":"2.2 · R. internus: der „Wächter“ oberhalb der Stimmlippen","more":[]},{"term":"myoelastisch-aerodynamische Theorie","lat":null,"ctx":"Das beschreibt die myoelastisch-aerodynamische Theorie (van den Berg 1958): myo-elastisch für Muskelspannung und Gewebeelastizität, aerodynamisch für den Luftstrom.","unit":"05","sec":"h-5-1-der-motor-luftdruck-gegen-elastisches-gewebe","secT":"5.1 · Der Motor: Luftdruck gegen elastisches Gewebe","more":[]},{"term":"N. laryngeus inferior","lat":null,"ctx":"Ab hier heißt sein Endstück N. laryngeus inferior.","unit":"03","sec":"h-3-3-am-hals-die-gefaehrdete-strecke","secT":"3.3 · Am Hals: die gefährdete Strecke","more":[]},{"term":"N. laryngeus superior","lat":null,"ctx":"Aus diesem Ganglion geht der N. laryngeus superior ab.","unit":"02","sec":"h-2-1-ursprung-und-teilung","secT":"2.1 · Ursprung und Teilung","more":[]},{"term":"N. vagus","lat":"N. X","ctx":"Der N. vagus (N. X) verlässt den Schädel durch das Foramen jugulare.","unit":"02","sec":"h-2-1-ursprung-und-teilung","secT":"2.1 · Ursprung und Teilung","more":[]},{"term":"Neuromonitoring","lat":null,"ctx":"Deshalb wird er heute zunehmend mit Neuromonitoring dargestellt.","unit":"02","sec":"h-2-3-r-externus-der-nerv-fuer-die-tonhoehe","secT":"2.3 · R. externus: der Nerv für die Tonhöhe","more":[]},{"term":"nicht-rekurrenter N. laryngeus","lat":null,"ctx":"Er geht dann direkt am Hals vom N. vagus ab: ein nicht-rekurrenter N. laryngeus.","unit":"03","sec":"h-3-2-warum-der-umweg-ein-blick-in-die-embryologie","secT":"3.2 · Warum der Umweg? Ein Blick in die Embryologie","more":[]},{"term":"Paramedian","lat":null,"ctx":"Paramedian: knapp neben der Mitte.","unit":"07","sec":"h-7-1-wo-steht-die-gelaehmte-stimmlippe","secT":"7.1 · Wo steht die gelähmte Stimmlippe?","more":[]},{"term":"Pars intercartilaginea","lat":null,"ctx":"Ihr größerer vorderer Teil liegt zwischen den weichen Stimmlippen (Pars intermembranacea), ihr kleinerer hinterer Teil zwischen den beiden Stellknorpeln (Pars intercartilaginea).","unit":"01","sec":"h-1-1-von-den-knorpeln-zum-ventil","secT":"1.1 · Von den Knorpeln zum Ventil","more":[]},{"term":"Pars intermembranacea","lat":null,"ctx":"Ihr größerer vorderer Teil liegt zwischen den weichen Stimmlippen (Pars intermembranacea), ihr kleinerer hinterer Teil zwischen den beiden Stellknorpeln (Pars intercartilaginea).","unit":"01","sec":"h-1-1-von-den-knorpeln-zum-ventil","secT":"1.1 · Von den Knorpeln zum Ventil","more":[]},{"term":"Penetrations-Aspirations-Skala","lat":null,"ctx":"In der Schluckdiagnostik wird das Eindringen von Material oft mit der Penetrations-Aspirations-Skala (Rosenbek et al. 1996) beschrieben: Penetration heißt, Material gelangt in den Kehlkopfeingang, bleibt aber oberhalb der Stimmlippen; Aspiration heißt, es gelangt unter die Stimmlippen.","unit":"06","sec":"h-6-4-welcher-ausfall-gefaehrdet-was","secT":"6.4 · Welcher Ausfall gefährdet was?","more":[]},{"term":"pharyngealen Phase","lat":null,"ctx":"Der Kehlkopf ist vor allem in der pharyngealen Phase beteiligt, die in weniger als einer Sekunde abläuft und von einem Schluckzentrum im Hirnstamm gesteuert wird.","unit":"06","sec":"h-6-2-schlucken-der-anteil-des-kehlkopfs","secT":"6.2 · Schlucken: der Anteil des Kehlkopfs","more":[]},{"term":"Pressen","lat":null,"ctx":"Das gleiche Prinzip nutzt das Pressen (Heben, Stuhlgang, Geburt): Der Kehlkopf schließt, oft mit den Taschenfalten, damit der Brustkorb als feste Stütze dient.","unit":"06","sec":"h-6-3-husten-und-pressen","secT":"6.3 · Husten und Pressen","more":[]},{"term":"Processus muscularis","lat":null,"ctx":"Der Processus muscularis zeigt zur Seite und nach hinten; dort setzen die wichtigsten Öffner- und Schließmuskeln an.","unit":"01","sec":"h-1-3-gelenk-2-das-krikoarytaenoidgelenk-schwenkt-den-proc-voc","secT":"1.3 · Gelenk 2: Das Krikoarytänoidgelenk schwenkt den Proc. vocalis","more":[]},{"term":"Processus vocalis","lat":null,"ctx":"Dort setzt sie am Processus vocalis an, der nach vorn zeigenden Ecke des Stellknorpels.","unit":"01","sec":"h-1-1-von-den-knorpeln-zum-ventil","secT":"1.1 · Von den Knorpeln zum Ventil","more":[{"unit":"01","sec":"h-1-3-gelenk-2-das-krikoarytaenoidgelenk-schwenkt-den-proc-voc","secT":"1.3 · Gelenk 2: Das Krikoarytänoidgelenk schwenkt den Proc. vocalis"}]},{"term":"R. externus","lat":null,"ctx":"R. externus: bleibt außen am Kehlkopf, motorisch zum M. cricothyroideus (Antikus).","unit":"02","sec":"h-2-1-ursprung-und-teilung","secT":"2.1 · Ursprung und Teilung","more":[]},{"term":"R. internus","lat":null,"ctx":"R. internus: zieht nach innen in den Kehlkopf, überwiegend sensibel.","unit":"02","sec":"h-2-1-ursprung-und-teilung","secT":"2.1 · Ursprung und Teilung","more":[]},{"term":"Randkantenverschiebung","lat":null,"ctx":"Weil Unter- und Oberkante zeitversetzt schwingen, läuft eine Welle über die Schleimhaut von unten nach oben: die Randkantenverschiebung (mukosale Welle), die man in der Stroboskopie sieht.","unit":"05","sec":"h-5-1-der-motor-luftdruck-gegen-elastisches-gewebe","secT":"5.1 · Der Motor: Luftdruck gegen elastisches Gewebe","more":[]},{"term":"Recessus piriformis","lat":"Sinus piriformis","ctx":"Danach verläuft er direkt unter der Schleimhaut des Recessus piriformis (Sinus piriformis), der Rinne seitlich vom Kehlkopfeingang, durch die der Bissen in die Speiseröhre gleitet.","unit":"02","sec":"h-2-2-r-internus-der-waechter-oberhalb-der-stimmlippen","secT":"2.2 · R. internus: der „Wächter“ oberhalb der Stimmlippen","more":[]},{"term":"Reinke-Raum","lat":"oberflächliche Lamina propria","ctx":"Cover (Hülle): das Epithel (die oberste Zellschicht) und darunter eine sehr lockere, fast gallertige Schicht, der Reinke-Raum (oberflächliche Lamina propria).","unit":"05","sec":"h-5-2-der-bau-der-stimmlippe-body-und-cover","secT":"5.2 · Der Bau der Stimmlippe: Body und Cover","more":[]},{"term":"Rekurrensparese","lat":null,"ctx":"Die Rekurrensparese, die Lähmung dieses Nervs, ist die häufigste neurogene Ursache einer Stimmlippenlähmung, die du in der Praxis sehen wirst.","unit":"03","sec":null,"secT":null,"more":[]},{"term":"Ringknorpel","lat":"Cartilago cricoidea","ctx":"Der Ringknorpel (Cartilago cricoidea) ist ein Ring, vorne niedrig und hinten hoch, wo er eine Platte bildet, die Lamina.","unit":"01","sec":"h-1-1-von-den-knorpeln-zum-ventil","secT":"1.1 · Von den Knorpeln zum Ventil","more":[]},{"term":"Schildknorpel","lat":"Cartilago thyroidea","ctx":"Der Schildknorpel (Cartilago thyroidea) sitzt vorne darüber wie ein Schild, dessen zwei Platten in einem Winkel zusammenlaufen.","unit":"01","sec":"h-1-1-von-den-knorpeln-zum-ventil","secT":"1.1 · Von den Knorpeln zum Ventil","more":[]},{"term":"Schlundbogen","lat":null,"ctx":"Er zieht unter dem Gefäß des 6. Schlundbogens zum Kehlkopf.","unit":"03","sec":"h-3-2-warum-der-umweg-ein-blick-in-die-embryologie","secT":"3.2 · Warum der Umweg? Ein Blick in die Embryologie","more":[]},{"term":"spasmodische Dysphonie","lat":null,"ctx":"Die spasmodische Dysphonie ist eine fokale Dystonie, also eine Bewegungsstörung des Gehirns, die nur bestimmte Bewegungen betrifft, hier das Sprechen.","unit":"08","sec":"h-8-3-beweglich-aber-auffaellig-schlussmuster-und-schleimhaut","secT":"8.3 · Beweglich, aber auffällig: Schlussmuster und Schleimhaut","more":[]},{"term":"Stellknorpel","lat":"Cartilagines arytenoideae, Aryknorpel","ctx":"Die beiden Stellknorpel (Cartilagines arytenoideae, Aryknorpel) sitzen hinten auf dem oberen Rand der Ringknorpelplatte.","unit":"01","sec":"h-1-1-von-den-knorpeln-zum-ventil","secT":"1.1 · Von den Knorpeln zum Ventil","more":[]},{"term":"Stimmband","lat":"Lig. vocale","ctx":"Übergang: mittlere und tiefe Lamina propria, zusammen das Stimmband (Lig. vocale), fester und faserreich.","unit":"05","sec":"h-5-2-der-bau-der-stimmlippe-body-und-cover","secT":"5.2 · Der Bau der Stimmlippe: Body und Cover","more":[]},{"term":"Stimmlippe","lat":"Plica vocalis","ctx":"Jede Stimmlippe (Plica vocalis) zieht von der Innenseite des Schildknorpelwinkels vorne zum Stellknorpel hinten.","unit":"01","sec":"h-1-1-von-den-knorpeln-zum-ventil","secT":"1.1 · Von den Knorpeln zum Ventil","more":[]},{"term":"Stimmritze","lat":"Rima glottidis","ctx":"Der Raum zwischen den beiden Stimmlippen ist die Stimmritze (Rima glottidis).","unit":"01","sec":"h-1-1-von-den-knorpeln-zum-ventil","secT":"1.1 · Von den Knorpeln zum Ventil","more":[]},{"term":"subglottischer Druck","lat":null,"ctx":"Unter den geschlossenen Stimmlippen staut sich die Ausatemluft; dieser Druck heißt subglottischer Druck (subglottisch = unterhalb der Stimmritze).","unit":"05","sec":"h-5-1-der-motor-luftdruck-gegen-elastisches-gewebe","secT":"5.1 · Der Motor: Luftdruck gegen elastisches Gewebe","more":[]},{"term":"Synkinesie","lat":null,"ctx":"Das gilt heute als unzuverlässig: Die Position hängt auch davon ab, ob der Antikus noch zieht, ob Fasern teilweise nachgewachsen sind (oft in falsche Muskeln, sogenannte Synkinesie) und wie stark der Muskel geschwunden ist.","unit":"07","sec":"h-7-1-wo-steht-die-gelaehmte-stimmlippe","secT":"7.1 · Wo steht die gelähmte Stimmlippe?","more":[]},{"term":"Taschenfalten","lat":"Plicae vestibulares","ctx":"Oberhalb der Stimmlippen liegen die Taschenfalten (Plicae vestibulares).","unit":"01","sec":"h-1-1-von-den-knorpeln-zum-ventil","secT":"1.1 · Von den Knorpeln zum Ventil","more":[]},{"term":"Wallenberg-Syndrom","lat":null,"ctx":"Ursachen sind Tumoren der Schädelbasis, Verletzungen oder ein Schlaganfall im seitlichen Hirnstamm (Wallenberg-Syndrom), bei dem der Nucleus ambiguus mitbetroffen ist.","unit":"07","sec":"h-7-5-hohe-vaguslaesion-und-die-frage-wie-hoch","secT":"7.5 · Hohe Vagusläsion und die Frage „Wie hoch?“","more":[]}],"sections":[{"unit":"01","id":null,"title":"Gelenke und innere Muskeln des Kehlkopfs","body":"Kernpfad · Abschnitt 1 von 10 Gelenke und innere Muskeln des Kehlkopfs ≈ 20 MinutenBaut auf: KehlkopfknorpelWeiter: N. laryngeus superior Nach diesem Abschnitt kannst du Die beiden Kehlkopfgelenke benennen und sagen, welche Bewegung jedes erlaubt. Erklären, warum das Kippen im Krikothyreoidgelenk die Tonhöhe hebt. Vorhersagen, wohin der Proc. vocalis geht, wenn der Proc. muscularis des Stellknorpels nach hinten oder nach vorn gezogen wird. Die fünf inneren Muskelgruppen mit ihren deutschen Spitznamen nennen und in Öffner, Schließer und Spanner einteilen. Warum das für dich als Logopädin wichtig ist Jeder Befund bei einer Nervenschädigung ist ein Muskel, der nicht mehr zieht. Wenn im HNO-Bericht steht „Stimmlippe links fixiert, Glottisschlussinsuffizienz bei Phonation“, kannst du die behauchte Stimme einer Patientin oder Eltern nur erklären und die Therapie planen, wenn du weißt, welcher Muskel diesen Spalt normalerweise schließt und wie er den Knorpel bewegt. Die Nervenabschnitte danach hängen einfach an jeden Muskel aus diesem Abschnitt einen Nerv."},{"unit":"01","id":"h-1-1-von-den-knorpeln-zum-ventil","title":"1.1 · Von den Knorpeln zum Ventil","body":"1.1 · Von den Knorpeln zum Ventil Die vier Knorpel kennst du schon. So sitzen sie zusammen, von oben gesehen. Der Ringknorpel (Cartilago cricoidea) ist ein Ring, vorne niedrig und hinten hoch, wo er eine Platte bildet, die Lamina. Der Schildknorpel (Cartilago thyroidea) sitzt vorne darüber wie ein Schild, dessen zwei Platten in einem Winkel zusammenlaufen. Die beiden Stellknorpel (Cartilagines arytenoideae, Aryknorpel) sitzen hinten auf dem oberen Rand der Ringknorpelplatte. Jede Stimmlippe (Plica vocalis) zieht von der Innenseite des Schildknorpelwinkels vorne zum Stellknorpel hinten. Dort setzt sie am Processus vocalis an, der nach vorn zeigenden Ecke des Stellknorpels. Der Raum zwischen den beiden Stimmlippen ist die Stimmritze (Rima glottidis). Ihr größerer vorderer Teil liegt zwischen den weichen Stimmlippen (Pars intermembranacea), ihr kleinerer hinterer Teil zwischen den beiden Stellknorpeln (Pars intercartilaginea). Klassische Lehrbücher geben etwa drei Fünftel zu zwei Fünfteln an; die ganze Stimmritze ist bei erwachsenen Männern etwa 23 mm lang, bei Frauen 17–18 mm. Oberhalb der Stimmlippen liegen die Taschenfalten (Plicae vestibulares). Sie bilden normalerweise keine Stimme, können sich aber beim Pressen zusammenschieben. Das wird später bei Kompensation wichtig. Abb. 1.1 Kehlkopf von oben, vorne oben. L und R sind links und rechts der Patientin: Wenn du von oben schaust und das Gesicht oben liegt, ist ihre rechte Seite auch bei dir rechts. Knorpel hellblau, Stimmlippen (sie enthalten Muskel) rotbraun. Abruf · ohne nachzusehen F1. Zwischen welchen zwei Punkten spannt sich jede Stimmlippe? F2. Nenne die zwei Teile der Rima glottidis. Welcher liegt zwischen Knorpel?"},{"unit":"01","id":"h-1-2-gelenk-1-das-krikothyreoidgelenk-kippt","title":"1.2 · Gelenk 1: Das Krikothyreoidgelenk kippt","body":"1.2 · Gelenk 1: Das Krikothyreoidgelenk kippt Die Articulatio cricothyroidea (Krikothyreoidgelenk) ist auf jeder Seite ein kleines echtes Gelenk zwischen dem unteren Horn des Schildknorpels (Cornu inferius) und einer Gelenkfläche seitlich am Ringknorpel. Die Hauptbewegung ist eine Drehung um eine quere Achse durch beide Gelenke: Die zwei Knorpel kippen gegeneinander wie ein Visier, das sich vorne schließt. Dazu kommt ein leichtes Gleiten. Warum ist das Kippen wichtig? Schau, wo die Stimmlippe befestigt ist. Vorne hängt sie am Schildknorpelwinkel, hinten an den Stellknorpeln, die auf der Ringknorpelplatte sitzen. Zieht sich der M. cricothyroideus zusammen, zieht er den vorderen Ringknorpelbogen zum Schildknorpel hoch. Die Platte hinten kippt nach hinten und nimmt die Stellknorpel mit, also wird der Abstand zwischen den beiden Ansatzpunkten größer. Die Stimmlippe wird länger, dünner und straffer und schwingt schneller: Die Tonhöhe steigt. Manche Bücher beschreiben dasselbe als Kippen des Schildknorpels nach vorn; für die Stimmlippe ist das Ergebnis gleich. Abb. 1.2 Schematische Seitenansicht. Der Schildknorpel bleibt in dieser Zeichnung stehen; der Ringknorpel kippt um das Gelenk, der Stellknorpel wandert nach hinten und die Stimmlippe wird länger. Die Bewegung ist zur Verdeutlichung übertrieben. Abruf F3. Was ist die Hauptbewegung im Krikothyreoidgelenk, und um welche Achse? F4. In einem Satz: Warum hebt die Kontraktion des M. cricothyroideus die Tonhöhe?"},{"unit":"01","id":"h-1-3-gelenk-2-das-krikoarytaenoidgelenk-schwenkt-den-proc-voc","title":"1.3 · Gelenk 2: Das Krikoarytänoidgelenk schwenkt den Proc. vocalis","body":"1.3 · Gelenk 2: Das Krikoarytänoidgelenk schwenkt den Proc. vocalis Die Articulatio cricoarytenoidea (Krikoarytänoidgelenk) liegt zwischen der Basis jedes Stellknorpels und einer ovalen Gelenkfläche auf dem oberen Rand der Ringknorpelplatte. Sie erlaubt zwei gekoppelte Bewegungen: ein Kippen (Schaukeln) um die Längsachse der Gelenkfläche und ein Gleiten entlang dieser Fläche. Kippen und Gleiten nach innen bringen die Proc. vocales zusammen (Adduktion); nach außen bewegen sie sie auseinander und etwas nach oben (Abduktion). Der Stellknorpel arbeitet wie ein Hebel mit zwei Armen. Der Processus vocalis zeigt nach vorn und trägt die Stimmlippe. Der Processus muscularis zeigt zur Seite und nach hinten; dort setzen die wichtigsten Öffner- und Schließmuskeln an. Weil die beiden Fortsätze vom Drehpunkt aus in verschiedene Richtungen zeigen, bewegt Zug am einen den anderen in die Gegenrichtung: Proc. muscularis nach hinten ziehen → Proc. vocalis schwenkt nach außen: Die Stimmritze öffnet sich. Proc. muscularis nach vorn ziehen → Proc. vocalis schwenkt nach innen: Die Stimmritze schließt sich. Abb. 1.3 Linker Stellknorpel der Patientin von oben, vorne oben, Mittellinie rechts. Grauer Umriss = Ruhelage; hellblau = nach dem Zug; schwarzer Punkt = Drehpunkt. Rotbraune Pfeile zeigen die Zugrichtung des Muskels. Abruf F5. Nenne die zwei Fortsätze des Stellknorpels und was an jedem ansetzt. F6. Der Proc. muscularis wird nach hinten gezogen. Wohin geht der Proc. vocalis, und was passiert mit der Stimmritze? F7. Welche zwei Bewegungen kombinieren sich im Krikoarytänoidgelenk?"},{"unit":"01","id":"h-1-4-die-fuenf-inneren-muskelgruppen","title":"1.4 · Die fünf inneren Muskelgruppen","body":"1.4 · Die fünf inneren Muskelgruppen Innere Kehlkopfmuskeln entspringen und setzen an Kehlkopfknorpeln an und bewegen diese gegeneinander. Äußere Kehlkopfmuskeln, etwa die geraden Halsmuskeln, heben oder senken den ganzen Kehlkopf und gehören nicht zu diesem Abschnitt. Die Phoniatrie benutzt kurze Spitznamen, und die sind Prüfungswortschatz. Die meisten sagen einfach, wo der Muskel liegt: anticus = vorne, posticus = hinten. Muskel · Spitzname Von → nach Bewegt Aufgabe Nerv (nächste Abschnitte) M. cricothyroideus „Antikus“ (CT) Vorderseitlicher Ringknorpelbogen → Unterrand und unteres Horn des Schildknorpels (Pars recta, Pars obliqua) Kippt im Krikothyreoidgelenk Verlängert und spannt die Stimmlippe: Tonhöhe ↑. Der einzige innere Muskel außen am Kehlkopf. SLN M. cricoarytaenoideus posterior „Postikus“ (PCA) Rückseite der Ringknorpelplatte → Proc. muscularis Zieht Proc. muscularis nach hinten Öffnet die Stimmritze. Der einzige Öffner. RLN M. cricoarytaenoideus lateralis „Lateralis“ (LCA) Oberrand des seitlichen Ringknorpelbogens → Proc. muscularis (vorne) Zieht Proc. muscularis nach vorn Schließt den vorderen (membranösen) Teil der Stimmritze RLN M. arytaenoideus transversus et obliquus „Transversus“ (IA, Interarytänoid) Rückseite des einen Stellknorpels → der andere (der quere Teil ist der einzige unpaare innere Muskel; die schrägen Teile kreuzen sich als X) Schiebt die Stellknorpel zusammen Schließt den hinteren (knorpeligen) Teil der Stimmritze; schräge Fasern laufen in die aryepiglottische Falte weiter und helfen, den Kehlkopfeingang zu verengen RLN* M. thyroarytaenoideus innerer Teil M. vocalis „Internus“, äußerer Teil „Externus“ (TA) Innenseite des Schildknorpelwinkels → Stellknorpel; der Vocalis zieht zum Proc. vocalis, direkt neben dem Stimmband Zieht den Stellknorpel zum Schildknorpel Verkürzt, verdickt und versteift den Stimmlippenkörper; hilft beim Schluss; lautere, bruststimmige Stimme RLN * Mögliche zusätzliche Ästchen vom R. internus des N. laryngeus superior: umstritten, kommt in den Nervenabschnitten. Der M. vocalis ist die Muskelschicht in der Stimmlippe. Im Body-Cover-Modell nach Hirano ist er der „Körper“ (Body), während die Schleimhaut darüber (Epithel plus die lockere Schicht namens Reinke-Raum) die „Hülle“ (Cover) bildet, die beim Sprechen Wellen schlägt. Die Stimmlippe ist also nicht nur ein Muskel, sondern ein Muskel mit einer weichen, geschichteten Hülle."},{"unit":"01","id":"h-1-5-drei-aufgaben-oeffnen-schliessen-spannen","title":"1.5 · Drei Aufgaben: öffnen, schließen, spannen","body":"1.5 · Drei Aufgaben: öffnen, schließen, spannen Ordnet man die Muskeln nach ihrer Aufgabe, wird das System klein. Ein Öffner: der Postikus. Mehrere Schließer: Lateralis, Transversus und Thyroarytänoid. Zwei Spanner, die gegeneinander arbeiten: Der M. cricothyroideus dehnt die Stimmlippe von außen (äußere Spannung), der Vocalis verkürzt und versteift sie von innen (innere Spannung). Feine Tonhöhen- und Registerkontrolle entsteht aus dem Gleichgewicht der beiden. Der M. cricothyroideus schiebt die Stimmlippen vielleicht auch leicht zur Mitte; wie stark, ist umstritten, deshalb ist dieser Pfeil gestrichelt. Abb. 1.4 Nur ein Pfeil erreicht ÖFFNEN. Genau das erklärt, warum der Ausfall beider Postikusmuskeln die Atmung gefährdet. Merkhilfe „Der Postikus ist der Pförtner – nur er macht die Pforte auf.“ Die Spitznamen verraten auch die Lage: Antikus = vorne und außen, Postikus = hinten, Lateralis = seitlich, Transversus = quer hinten zwischen den Stellknorpeln. Abruf F8. Welcher ist der einzige innere Kehlkopfmuskel, der außen am Kehlkopf liegt? F9. Zähle die Schließer auf. Welcher schließt den hinteren Teil der Stimmritze? F10. Welche zwei Muskeln steuern die Spannung, und wie unterscheiden sie sich?"},{"unit":"01","id":"h-1-6-zwei-mini-faelle-vom-muskel-zum-symptom","title":"1.6 · Zwei Mini-Fälle: vom Muskel zum Symptom","body":"1.6 · Zwei Mini-Fälle: vom Muskel zum Symptom Erwachsene · Frau K., 34, Chorsopranistin Zwei Monate nach einer Schilddrüsenoperation klingt ihre Sprechstimme fast normal, aber sie erreicht ihre hohen Töne nicht mehr, die Stimme ermüdet schnell und trägt in lauter Umgebung nicht mehr. In der Laryngoskopie öffnen und schließen beide Stimmlippen. F11. Welches Gelenk hat wahrscheinlich seinen Antriebsmuskel verloren, und warum kostet sie das die hohen Töne, aber nicht das Öffnen und Schließen? Kind · Baby J., 6 Wochen Seit einer Herzoperation hat J. bei jedem Einatmen ein hohes Geräusch, schlimmer beim Schreien und Trinken. Sein Schreien klingt überraschend normal. Die Laryngoskopie zeigt, dass beide Stimmlippen auch beim Einatmen nahe der Mitte bleiben. F12. Welcher Muskel zieht die Stimmlippen bei jedem Einatmen normalerweise auseinander? Warum kann das Schreien recht normal bleiben, während die Atmung laut ist? Häufige Fehlvorstellungen „Die Stimmlippe ist ein Muskel.“ Sie ist geschichtet: ein Muskelkörper (M. vocalis) unter einem Band und einer weichen Schleimhauthülle. Viele Stimmstörungen, etwa Knötchen, betreffen nur die Hülle. „Der M. cricothyroideus liegt wie die anderen im Kehlkopf.“ Er ist ein innerer Muskel (er verbindet zwei Kehlkopfknorpel), liegt aber außen auf der Oberfläche. „Der Öffner zieht direkt am Proc. vocalis.“ Der Postikus zieht den Proc. muscularis nach hinten; der Proc. vocalis schwenkt nach außen, weil der Stellknorpel als Hebel wirkt. „Die Stellknorpel drehen sich um eine senkrechte Achse wie eine Tür.“ Viele ältere Zeichnungen zeigen das. Dreidimensionale Studien zeigen vor allem ein Kippen um die Längsachse der Gelenkfläche plus Gleiten. Für die Prüfung ist das Ergebnis gleich: Der Proc. vocalis schwenkt nach innen oder außen. „Der Lateralis schließt die ganze Stimmritze allein.“ Er schließt vor allem den vorderen Teil; den hinteren schließt der Transversus. „Die Taschenfalten machen die Stimme.“ Normale Stimme entsteht an den echten Stimmlippen. Taschenfaltenstimme ist eine Kompensation und klingt rau und gepresst."},{"unit":"01","id":"h-zusammenfassung-in-fuenf-zeilen","title":"Zusammenfassung in fünf Zeilen","body":"Zusammenfassung in fünf Zeilen Die Stimmlippe zieht von der Innenseite des Schildknorpelwinkels zum Proc. vocalis des Stellknorpels. Das Krikothyreoidgelenk kippt: Der M. cricothyroideus verlängert und spannt die Stimmlippe, die Tonhöhe steigt. Das Krikoarytänoidgelenk kippt und gleitet: Proc. muscularis nach hinten = Proc. vocalis nach außen, Proc. muscularis nach vorn = Proc. vocalis nach innen. Ein Öffner (Postikus); Schließer Lateralis, Transversus und Thyroarytänoid; Spanner M. cricothyroideus (außen) und Vocalis (innen). Jede Nervenläsion in den nächsten Abschnitten liest du als: „Welcher dieser Muskeln zieht nicht mehr?“ Aus dem Gedächtnis zeichnen · 5 Minuten, leeres Blatt Zeichne den Kehlkopf von oben: ein V für den Schildknorpel oben, einen Ring für den Ringknorpel, zwei kleine Dreiecke hinten für die Stellknorpel. Markiere vorne, hinten, R und L. Zeichne die zwei Stimmlippen vom Schildknorpelwinkel zur vorderen Ecke jedes Dreiecks. Beschrifte auf einer Seite Proc. vocalis und Proc. muscularis. Zeichne an diesem Stellknorpel einen Pfeil, der den Proc. muscularis nach hinten zieht („Postikus → öffnet“), und einen nach vorn („Lateralis → schließt“). Zeichne einen Balken hinten zwischen den Stellknorpeln: „Transversus → schließt hinten“. Schreib daneben „Antikus = kippen = Tonhöhe ↑“ und „Vocalis = verkürzt, versteift“. Vergleiche mit Abb. 1.1, 1.3 und 1.4. Was fehlt, kommt auf eine Lernkarte. Lösungen zu F1–F12 (erst nach eigenem Versuch öffnen) F1. Von der Innenseite des Schildknorpelwinkels (vorne) zum Proc. vocalis des Stellknorpels (hinten). F2. Pars intermembranacea (vorne, zwischen den weichen Stimmlippen, der größere Teil) und Pars intercartilaginea (hinten, zwischen den Stellknorpeln). F3. Drehung (Kippen) um eine quere Achse durch beide Krikothyreoidgelenke; dazu leichtes Gleiten. F4. Das Kippen vergrößert den Abstand zwischen Schildknorpelwinkel und Stellknorpeln, sodass die Stimmlippe länger, dünner und straffer wird und schneller schwingt. F5. Processus vocalis: die Stimmlippe (Stimmband und Vocalis). Processus muscularis: Postikus und Lateralis. F6. Der Proc. vocalis schwenkt nach außen (und etwas nach oben); die Stimmritze öffnet sich. F7. Kippen um die Längsachse der Gelenkfläche des Ringknorpels und Gleiten entlang dieser Fläche. F8. M. cricothyroideus (Antikus). F9. Lateralis, Transversus (Interarytänoid) und Thyroarytänoid; der Transversus schließt hinten. F10. M. cricothyroideus: dehnt und verlängert die Stimmlippe von außen. Vocalis: verkürzt sie und versteift ihren Körper von innen. Ihr Gleichgewicht bestimmt Tonhöhe und Register. F11. Das Krikothyreoidgelenk, angetrieben vom M. cricothyroideus. Ohne ihn lässt sich die Stimmlippe nicht dehnen, also fehlen die höchsten Töne und etwas Lautstärke und Ausdauer; Postikus und Schließer arbeiten noch, deshalb sehen Öffnen und Schließen normal aus. F12. Der Postikus (beidseits). Fallen beide Öffner aus, bleiben die Stimmlippen nahe der Mitte: Die Luft muss durch einen engen Spalt, das macht beim Einatmen ein Geräusch (inspiratorischer Stridor). Weil die Stimmlippen schon nah beieinander liegen, können sie noch schwingen, deshalb kann das Schreien fast normal klingen. Genau dieses Muster triffst du später als beidseitige Rekurrensparese wieder."},{"unit":"01","id":"h-quellen","title":"Quellen","body":"Quellen Schünke M, Schulte E, Schumacher U. PROMETHEUS LernAtlas: Kopf, Hals und Neuroanatomie. 6. Aufl. Thieme; 2022 (Kehlkopfskelett, Gelenke, innere Muskeln). Paulsen F, Waschke J. Sobotta Atlas der Anatomie, Band 3. 25. Aufl. Elsevier; 2022. Standring S (Hrsg.). Gray's Anatomy. 42nd ed. Elsevier; 2020 (Anteile der Rima glottidis, Krikothyreoid- und Krikoarytänoidgelenk). Kenhub. Cricoarytenoid and cricothyroid joints (Gelenkbewegungen und Muskeln). Wikipedia. Rima glottidis (Längen: etwa 23 mm bei Männern, 17–18 mm bei Frauen). Wang RC. Three-dimensional analysis of cricoarytenoid joint motion. Laryngoscope 1998;108(4 Pt 2 Suppl 86):1–17. PubMed 9546282. Hirano M. Morphological structure of the vocal cord as a vibrator and its variations. Folia Phoniatr 1974;26:89–94 (Body-Cover-Modell). Wendler J, Seidner W, Eysholdt U. Lehrbuch der Phoniatrie und Pädaudiologie. 5. Aufl. Thieme; 2015 (deutsche Spitznamen, Internus-/Transversus-Begriffe)."},{"unit":"02","id":null,"title":"Der N. laryngeus superior (N. laryngeus superior, superior laryngeal nerve)","body":"Kernpfad · Abschnitt 2 von 10 Der N. laryngeus superior (N. laryngeus superior, superior laryngeal nerve) ≈ 20 MinutenBaut auf: Abschnitt 1, Gelenke und MuskelnWeiter: N. laryngeus recurrens Nach diesem Abschnitt kannst du Ursprung, Teilung und Verlauf des N. laryngeus superior beschreiben. Für den R. internus und den R. externus angeben, was sie motorisch und sensibel versorgen. Erklären, warum der R. externus bei Schilddrüsenoperationen gefährdet ist. Vorhersagen, was der Ausfall jedes Astes für Stimme und Schluckschutz bedeutet. Warum das für dich als Logopädin wichtig ist Der obere Kehlkopfnerv ist der „unauffällige“ Kehlkopfnerv. Fällt sein äußerer Ast aus, klingt die Sprechstimme fast normal und die Laryngoskopie zeigt wenig, aber Höhe, Tragfähigkeit und Ausdauer fehlen. Oft fällt das zuerst in der logopädischen Stimmdiagnostik auf. Fällt sein innerer Ast aus, merkt der Kehlkopf nicht mehr, wenn etwas hineinläuft: Speichel oder Getränke gelangen in die Atemwege, ohne dass gehustet wird. Beides landet bei dir."},{"unit":"02","id":"h-2-1-ursprung-und-teilung","title":"2.1 · Ursprung und Teilung","body":"2.1 · Ursprung und Teilung Der N. vagus (N. X) verlässt den Schädel durch das Foramen jugulare. Direkt darunter hat er eine Verdickung, das Ganglion inferius (Ganglion nodosum). Ein Ganglion ist eine Ansammlung von Nervenzellkörpern außerhalb des Gehirns; hier liegen die Zellkörper der Fasern, die Empfindungen aus Kehlkopf und Eingeweiden melden. Aus diesem Ganglion geht der N. laryngeus superior ab. Er zieht medial der Halsschlagadern an der Rachenwand nach vorn unten und teilt sich etwa in Höhe des großen Zungenbeinhorns (Cornu majus ossis hyoidei) in zwei Äste: R. internus: zieht nach innen in den Kehlkopf, überwiegend sensibel. R. externus: bleibt außen am Kehlkopf, motorisch zum M. cricothyroideus (Antikus). Abb. 2.1 Schematische Seitenansicht der linken Halsseite, vorne links. Gelb: N. vagus; türkis: N. laryngeus superior; rot: Arterien; beige: Knochen; hellblau: Knorpel; rotbraun: Muskel. Die Pfeilspitze zeigt die Richtung des Signals: beim R. internus zum Gehirn hin (Empfindung), beim R. externus zum Muskel hin (Bewegung). Der R. internus durchbohrt die Membran zusammen mit der A. laryngea superior. Abruf · ohne nachzusehen F1. Aus welchem Ganglion geht der N. laryngeus superior ab? F2. In welcher Höhe teilt er sich, und wie heißen die beiden Äste?"},{"unit":"02","id":"h-2-2-r-internus-der-waechter-oberhalb-der-stimmlippen","title":"2.2 · R. internus: der „Wächter“ oberhalb der Stimmlippen","body":"2.2 · R. internus: der „Wächter“ oberhalb der Stimmlippen Der R. internus zieht zusammen mit der A. laryngea superior durch die Membrana thyrohyoidea, die Bindegewebsplatte zwischen Zungenbein und Schildknorpel. Danach verläuft er direkt unter der Schleimhaut des Recessus piriformis (Sinus piriformis), der Rinne seitlich vom Kehlkopfeingang, durch die der Bissen in die Speiseröhre gleitet. Er versorgt sensibel die Schleimhaut oberhalb der Stimmlippen: Kehldeckel (Epiglottis), aryepiglottische Falten, Kehlkopfvorhof (Vestibulum laryngis), Taschenfalten und den Recessus piriformis. Unterhalb der Stimmlippen übernimmt der N. laryngeus recurrens; auf Höhe der Stimmlippen überlappen sich beide Gebiete. Außerdem führt er Fasern für die Schleimdrüsen und für Geschmacksknospen in der Nähe des Kehldeckels. Abb. 2.2 Frontalschnitt, von vorne gesehen: R und L sind rechts und links der Patientin. Türkis schraffiert = sensibles Gebiet des R. internus, violett = N. laryngeus recurrens. Die Beschriftung „SLN“ / „RLN“ trägt die Information auch ohne Farbe. Wozu diese Empfindung? Der R. internus ist der zuführende (afferente) Schenkel der wichtigsten Schutzreflexe. Berührt ein Tropfen die Schleimhaut oberhalb der Stimmlippen, meldet der R. internus das an den Hirnstamm. Von dort geht über den N. laryngeus recurrens beider Seiten der Befehl zurück: Stimmlippen kurz schließen, dann husten. Dieser laryngeale Adduktorreflex schließt sogar beide Seiten, wenn nur eine Seite gereizt wird. Abb. 2.3 Der Schutzreflex als Kette. Fällt das erste Glied (R. internus) aus, startet die Kette nicht, auch wenn alle Muskeln gesund sind. Kinder Bei Neugeborenen, besonders Frühgeborenen, löst eine Reizung der Kehlkopfschleimhaut oft nicht Husten aus, sondern Schlucken, eine Atempause (Apnoe) und einen langsamen Herzschlag. Man nennt das den laryngealen Chemoreflex. Auch hier ist der N. laryngeus superior der zuführende Nerv. Mit der Reifung tritt die Apnoe zurück und Husten und Schlucken übernehmen. Für dich heißt das: Atempausen oder Verfärbung beim Trinken eines Säuglings sind ein Warnzeichen, das ärztlich abgeklärt werden muss. Ein Teil dieses Wissens stammt aus Tierversuchen. Abruf F3. Durch welche Struktur tritt der R. internus in den Kehlkopf, und mit welchem Gefäß? F4. Welche Schleimhaut versorgt er sensibel, und wer übernimmt unterhalb der Stimmlippen? F5. Warum schließen beim Adduktorreflex beide Stimmlippen, obwohl der R. internus „nur“ sensibel ist?"},{"unit":"02","id":"h-2-3-r-externus-der-nerv-fuer-die-tonhoehe","title":"2.3 · R. externus: der Nerv für die Tonhöhe","body":"2.3 · R. externus: der Nerv für die Tonhöhe Der R. externus ist dünn und bleibt außen. Er zieht auf dem unteren Schlundschnürer (M. constrictor pharyngis inferior) nach unten, gibt ihm kleine Äste und erreicht dann den M. cricothyroideus, den Antikus aus Abschnitt 1. Er ist sein einziger motorischer Nerv. Fällt er aus, kann der Ringknorpel nicht mehr gegen den Schildknorpel gekippt werden: Die Stimmlippe lässt sich nicht mehr verlängern und spannen. Unterwegs liegt er eng an der A. thyroidea superior, die zum oberen Pol der Schilddrüse zieht. Bei einer Schilddrüsenoperation wird genau dieses Gefäß abgebunden, und dabei kann der Nerv mitgefasst oder gedehnt werden. Wie gefährdet er ist, hängt davon ab, wo er die Arterie kreuzt. Die Einteilung nach Cernea (1992) beschreibt das: Abb. 2.4 Grau: oberer Schilddrüsenpol; rot: A. thyroidea superior; türkis: R. externus; Kreis: Kreuzungspunkt. Bei großen Strumen ist Typ 2 häufiger, weil der Pol höher reicht. In etwa 3 % wird der Nerv gar nicht gefunden. Wie oft der R. externus bei Schilddrüsenoperationen verletzt wird, ist unklar: Die Studien berichten zwischen 0 und 58 %, je nachdem, ob man nur hinhört oder mit Elektromyographie misst. Deshalb wird er heute zunehmend mit Neuromonitoring dargestellt. Abruf F6. Welchen Muskel versorgt der R. externus, und was kann dieser Muskel ohne ihn nicht mehr? F7. Neben welcher Arterie verläuft er, und welche Cernea-Typen gelten als gefährdet?"},{"unit":"02","id":"h-2-4-was-passiert-wenn-ein-ast-ausfaellt","title":"2.4 · Was passiert, wenn ein Ast ausfällt?","body":"2.4 · Was passiert, wenn ein Ast ausfällt? Hier kommt die Karte aus dem Styleguide zurück, diesmal nur mit dem oberen Kehlkopfnerv hervorgehoben. Der N. laryngeus recurrens ist grau, weil er erst im nächsten Abschnitt dran ist. Abb. 2.5 Gleiche Karte wie im Styleguide, gleiche Anordnung. Die beiden fett umrandeten Wirkungen sind genau das, was bei einer Läsion verloren geht. Ausfall R. externus SLN Ausfall R. internus SLN Stimme Sprechstimme oft fast normal. Hohe Töne und Kopfstimme fehlen, Tonhöhenumfang eingeschränkt, Stimme ermüdet und trägt schlecht, Sprechmelodie flacher. Für Sängerinnen und Lehrer besonders spürbar. Normal Laryngoskopie In Ruhe meist unauffällig. Bei Phonation möglich: Stimmlippe der kranken Seite kürzer und durchgebogen, Proc. vocales in unterschiedlicher Höhe, Taschenfalte drückt mit. Diese Zeichen sind schwach und nicht immer da. Beweglichkeit normal. In der FEES (Schluckendoskopie) sieht man Speichel oder Nahrung im Kehlkopfeingang, ohne dass die Patientin reagiert. Schlucken, Schutz Kaum betroffen Verminderter Schutzreflex: stille Aspiration, das heißt Material gelangt in die Atemwege, ohne Husten auszulösen Diagnostik Glissando-Aufgabe (von tief nach hoch gleiten), Stimmfeldmessung (die obere Grenze fehlt), Larynx-EMG des M. cricothyroideus FEES mit Prüfung der Sensibilität, ggf. Videofluoroskopie Rolle der Logopädin Stimmfeld und Glissando dokumentieren, Stimmtherapie für Umfang und Resonanz, Überdruck als Ausgleich vermeiden Schluckdiagnostik im Team, Strategien wie Kopfhaltung und angepasste Konsistenzen Fallen beide Äste aus, etwa weil der N. vagus selbst oberhalb der Abzweigung geschädigt ist, kommen beide Probleme zusammen. Diese „hohen“ Vagusläsionen bringen noch Gaumen- und Rachenzeichen mit und kommen später im Kurs. Merkhilfe „Internus fühlt innen – Externus spannt außen.“ Der R. internus geht in den Kehlkopf hinein und fühlt dort; der R. externus bleibt draußen und versorgt den Antikus, den einzigen Kehlkopfmuskel auf der Außenseite. Abruf F8. Warum wird eine Lähmung des R. externus so oft übersehen? F9. Was bedeutet „stille Aspiration“, und warum passt sie zu einem Ausfall des R. internus?"},{"unit":"02","id":"h-2-5-zwei-mini-faelle","title":"2.5 · Zwei Mini-Fälle","body":"2.5 · Zwei Mini-Fälle Erwachsene · Frau K., 34, Chorsopranistin (aus Abschnitt 1) Zur Erinnerung: Nach der Schilddrüsenoperation erreicht sie ihre hohen Töne nicht mehr, ihre Stimme ermüdet, beide Stimmlippen öffnen und schließen. Im Operationsbericht steht, dass die Gefäße am oberen Pol schwierig darzustellen waren. F10. Welcher Nerv ist wahrscheinlich verletzt? Welche zwei Untersuchungen würden den Verdacht stützen, und was erwartest du im Stimmfeld? Kind · Lena, Frühgeborene, 4 Wochen alt Beim Trinken aus der Flasche macht Lena manchmal eine Atempause, wird blass und ihr Herzschlag wird langsamer. Husten tut sie dabei kaum. F11. Welcher Nerv meldet die Flüssigkeit am Kehlkopfeingang an den Hirnstamm? Warum reagiert ein Frühgeborenes eher mit Atempause als mit Husten, und was tust du als Logopädin zuerst? Häufige Fehlvorstellungen „Der N. laryngeus superior ist rein sensibel.“ Nein: Der R. internus ist überwiegend sensibel, der R. externus ist motorisch. „R. internus und der Muskel ‚Internus‘ sind dasselbe.“ Nein. „Internus“ ist der Spitzname für den M. vocalis aus Abschnitt 1, und den versorgt der N. laryngeus recurrens. Der R. internus ist ein Nervenast. „Der N. laryngeus inferior ist der obere Nerv von unten gesehen.“ Nein: Der N. laryngeus inferior ist das Endstück des N. laryngeus recurrens. „Normale Laryngoskopie heißt: kein Nervenschaden.“ Eine Lähmung des R. externus kann laryngoskopisch fast unsichtbar sein. Höre und miss die Tonhöhe. „Der obere Nerv versorgt die ganze Kehlkopfschleimhaut.“ Nur oberhalb der Stimmlippen; darunter ist es der N. laryngeus recurrens. „Wer nicht hustet, aspiriert auch nicht.“ Gerade bei fehlender Sensibilität wird ohne Husten aspiriert."},{"unit":"02","id":"h-zusammenfassung-in-fuenf-zeilen","title":"Zusammenfassung in fünf Zeilen","body":"Zusammenfassung in fünf Zeilen Der N. laryngeus superior entspringt am Ganglion inferius des N. vagus und teilt sich etwa in Höhe des großen Zungenbeinhorns. R. internus: durch die Membrana thyrohyoidea, sensibel für die Schleimhaut oberhalb der Stimmlippen, startet Verschluss und Husten. R. externus: außen entlang der A. thyroidea superior zum M. cricothyroideus, steuert Spannung und Tonhöhe. Ausfall außen: hohe Töne, Umfang und Tragfähigkeit fehlen, laryngoskopisch oft kaum sichtbar. Ausfall innen: Stimme normal, aber stille Aspiration; bei Frühgeborenen löst Reizung eher Atempausen aus. Aus dem Gedächtnis zeichnen · 5 Minuten, leeres Blatt Zeichne eine senkrechte gelbe Linie (N. vagus) mit einer Verdickung oben: Ganglion inferius. Zeichne darunter Zungenbein, Schildknorpel und Ringknorpel von der Seite, vorne links. Lass den oberen Nerv vom Ganglion nach vorn ziehen und sich auf Höhe des Zungenbeins teilen. R. internus: durch die Membran in den Kehlkopf, Pfeilspitze zum Hirnstamm hin, „fühlt oberhalb“. R. externus: an einer roten Arterie entlang zum Antikus, Pfeilspitze zum Muskel, „Tonhöhe ↑“. Vergleiche mit Abb. 2.1 und 2.5. Was fehlt, kommt auf eine Lernkarte. Lösungen zu F1–F11 (erst nach eigenem Versuch öffnen) F1. Aus dem Ganglion inferius (nodosum) des N. vagus, direkt unter dem Foramen jugulare. F2. Etwa in Höhe des großen Zungenbeinhorns; in R. internus und R. externus. F3. Durch die Membrana thyrohyoidea, zusammen mit der A. laryngea superior. F4. Die Schleimhaut oberhalb der Stimmlippen: Epiglottis, aryepiglottische Falten, Vestibulum, Taschenfalten, Recessus piriformis. Unterhalb übernimmt der N. laryngeus recurrens. F5. Der R. internus liefert nur die Meldung. Der Hirnstamm schaltet sie auf den N. laryngeus recurrens beider Seiten um, und dieser bewegt die Schließmuskeln. F6. Den M. cricothyroideus. Ohne ihn kann der Ringknorpel nicht gegen den Schildknorpel gekippt werden, die Stimmlippe wird nicht mehr verlängert und gespannt. F7. Neben der A. thyroidea superior. Gefährdet sind Typ 2a (Kreuzung weniger als 1 cm über dem oberen Pol) und Typ 2b (Kreuzung unterhalb des Oberrands). F8. Die Stimmlippen öffnen und schließen normal, und die Sprechstimme klingt fast normal. Der Ausfall zeigt sich vor allem in der Höhe, die man gezielt prüfen muss. F9. Material gelangt unter die Stimmlippen in die Atemwege, ohne dass Husten ausgelöst wird. Ohne Empfindung oberhalb der Stimmlippen startet der Schutzreflex nicht. F10. Der R. externus des N. laryngeus superior, beim Abbinden der Gefäße am oberen Pol gefährdet. Stützen: Stimmfeldmessung bzw. Glissando (die obere Grenze ist abgesenkt, der Umfang kleiner) und Larynx-EMG des M. cricothyroideus. F11. Der N. laryngeus superior (R. internus). Beim unreifen Säugling überwiegt der laryngeale Chemoreflex mit Atempause und langsamerem Herzschlag; Husten entwickelt sich erst mit der Reifung. Zuerst: Trinken unterbrechen, das Kind beobachten und die Episoden umgehend an die Ärztin melden; die Schluckabklärung erfolgt im Team."},{"unit":"02","id":"h-quellen","title":"Quellen","body":"Quellen Schünke M, Schulte E, Schumacher U. PROMETHEUS LernAtlas: Kopf, Hals und Neuroanatomie. 6. Aufl. Thieme; 2022 (Verlauf und Versorgungsgebiete des N. laryngeus superior). Standring S (Hrsg.). Gray's Anatomy. 42nd ed. Elsevier; 2020. Cernea CR, Ferraz AR, Nishio S et al. Surgical anatomy of the external branch of the superior laryngeal nerve. Head Neck 1992;14:380–383. Übersicht zum R. externus in der Schilddrüsenchirurgie (Cernea-Typen, Verletzungsraten 0–58 %). Front Endocrinol 2014;5:108. Volltext. Tsai V, Celmer A, Berke GS, Chhetri DK. Videostroboscopic findings in unilateral superior laryngeal nerve paralysis and paresis. Otolaryngol Head Neck Surg 2007. doi:10.1016/j.otohns.2006.11.024 (drei Fälle). Roy N et al. Exploring the phonatory effects of external superior laryngeal nerve paralysis. Laryngoscope 2009. doi:10.1002/lary.20143. Orestes MI, Chhetri DK. Superior laryngeal nerve injury. Curr Opin Otolaryngol Head Neck Surg 2014. doi:10.1097/MOO.0000000000000097. Studie zum laryngealen Chemoreflex (N. laryngeus superior als afferenter Nerv, Reifung von Apnoe zu Husten und Schlucken; Rattenjunge). PMC6985871. DGPP. S2k-Leitlinie Diagnostik und Therapie von Störungen der Stimmfunktion (Dysphonien), AWMF 049-008, 2023."},{"unit":"03","id":null,"title":"Der N. laryngeus recurrens (N. laryngeus recurrens, recurrent laryngeal nerve)","body":"Kernpfad · Abschnitt 3 von 10 Der N. laryngeus recurrens (N. laryngeus recurrens, recurrent laryngeal nerve) ≈ 20 MinutenBaut auf: Abschnitte 1 und 2Weiter: die vollständige Nerv-Muskel-Wirkung-Karte Nach diesem Abschnitt kannst du Den Verlauf des N. laryngeus recurrens rechts und links beschreiben und erklären, warum er sich unterscheidet. Die Stellen benennen, an denen er am Hals besonders gefährdet ist. Angeben, welche Muskeln und welche Schleimhaut er versorgt. Begründen, warum der linke Nerv häufiger ausfällt, auch bei Kindern nach Herzoperationen. Warum das für dich als Logopädin wichtig ist Die Rekurrensparese, die Lähmung dieses Nervs, ist die häufigste neurogene Ursache einer Stimmlippenlähmung, die du in der Praxis sehen wirst. Der Nerv steuert fast alle Kehlkopfmuskeln aus Abschnitt 1, also Öffnen und Schließen. Wo er verläuft, erklärt, wer gefährdet ist: Menschen nach Schilddrüsen- oder Brustkorboperationen, mit Tumoren im Brustraum, und Frühgeborene nach Herzoperationen."},{"unit":"03","id":"h-3-1-der-umweg-erst-nach-unten-dann-zurueck-nach-oben","title":"3.1 · Der Umweg: erst nach unten, dann zurück nach oben","body":"3.1 · Der Umweg: erst nach unten, dann zurück nach oben Recurrens heißt „zurücklaufend“. Der Nerv geht nicht wie der obere Kehlkopfnerv am Hals ab, sondern viel tiefer, im Brustraum. Dort schlingt er sich um eine große Arterie und läuft zurück nach oben zum Kehlkopf. Rechts verlässt er den N. vagus vor der A. subclavia dextra (rechte Schlüsselbeinarterie), zieht unter ihr hindurch und steigt wieder auf. Links verlässt er den N. vagus vor dem Aortenbogen (Arcus aortae), zieht unter ihm hindurch, direkt seitlich vom Lig. arteriosum, und steigt wieder auf. Das Lig. arteriosum ist der bindegewebige Rest des Ductus arteriosus, eines Gefäßes, das vor der Geburt die Lunge umgeht. Beide Nerven steigen dann in der Rinne zwischen Luftröhre und Speiseröhre (Sulcus tracheooesophageus) nach oben. Der linke Nerv ist dadurch deutlich länger und hat einen langen Abschnitt im Brustraum. Abb. 3.1 Schematische Ansicht von vorn: R und L sind rechts und links der Patientin. Gelb: N. vagus; violett: N. laryngeus recurrens, Pfeilspitze zum Kehlkopf (motorisch); rot: Arterien; grau: Schilddrüse und Lig. arteriosum. Proportionen vereinfacht; die Schilddrüse liegt in Wirklichkeit vor der Luftröhre. Merkhilfe „Links läuft's länger.“ Links um den Aortenbogen, rechts nur um die Schlüsselbeinarterie. Längerer Weg heißt mehr Stellen, an denen etwas schiefgehen kann. Abruf · ohne nachzusehen F1. Um welche Arterie schlingt sich der rechte, um welche der linke N. laryngeus recurrens? F2. In welcher Rinne steigen beide Nerven zum Kehlkopf auf?"},{"unit":"03","id":"h-3-2-warum-der-umweg-ein-blick-in-die-embryologie","title":"3.2 · Warum der Umweg? Ein Blick in die Embryologie","body":"3.2 · Warum der Umweg? Ein Blick in die Embryologie Beim Embryo ist der Nerv noch kurz. Er zieht unter dem Gefäß des 6. Schlundbogens zum Kehlkopf. Ein Schlundbogen ist eine embryonale Gewebewulst am Hals; jeder hat eine eigene Arterie, aus denen später die großen Gefäße werden. Dann wächst das Herz nach unten in den Brustkorb und zieht die Gefäße mit. Der Nerv bleibt unter „seinem“ Gefäß eingehakt und wird mit nach unten gezogen. Rechts bildet sich das untere Stück der 6. (und die 5.) Bogenarterie zurück. Der Nerv rutscht deshalb nach oben bis zur nächsten erhaltenen Arterie, der 4. Bogenarterie, die zur A. subclavia dextra wird. Links bleibt die 6. Bogenarterie als Ductus arteriosus erhalten, später als Lig. arteriosum. Der Nerv bleibt darunter, am Aortenbogen. Abb. 3.2 Stark vereinfachtes Schema. Rot = erhaltene Arterie, grau = zurückgebildet bzw. bindegewebiger Rest. Für die Prüfung reicht der Kern: Der Nerv bleibt unter der tiefsten erhaltenen Arterie eingehakt. Die wichtigste Variante: Wenn rechts die Schlüsselbeinarterie nicht normal angelegt ist, sondern als A. lusoria hinter der Speiseröhre von der Aorta abgeht, gibt es nichts, unter dem sich der rechte Nerv einhaken könnte. Er geht dann direkt am Hals vom N. vagus ab: ein nicht-rekurrenter N. laryngeus. Das kommt rechts bei etwa 0,7 % der Menschen vor, in rund 87 % davon zusammen mit einer A. lusoria. Links ist es eine große Seltenheit. Chirurgisch ist das gefährlich, weil niemand den Nerv an dieser Stelle erwartet. Abruf F3. Unter welchem embryonalen Gefäß hakt sich der Nerv ursprünglich ein, und was wird daraus links? F4. Was ist ein nicht-rekurrenter N. laryngeus, auf welcher Seite kommt er vor, und womit hängt er zusammen?"},{"unit":"03","id":"h-3-3-am-hals-die-gefaehrdete-strecke","title":"3.3 · Am Hals: die gefährdete Strecke","body":"3.3 · Am Hals: die gefährdete Strecke Im unteren Halsbereich läuft der Nerv hinter der Schilddrüse nach oben, eng an zwei Strukturen, die Chirurginnen bei jeder Schilddrüsenoperation sorgfältig darstellen: die A. thyroidea inferior: Der Nerv kann vor, hinter oder zwischen ihren Ästen liegen. Diese Lage ist so variabel, dass sie kein verlässlicher Wegweiser ist. das Berry-Band: ein straffes Band, das die Schilddrüse seitlich an der Luftröhre festhält. Hier liegt der Nerv besonders dicht an der Drüse und ist am stärksten gefährdet. Dann tritt er unter dem Unterrand des unteren Schlundschnürers, direkt hinter dem Krikothyreoidgelenk, in den Kehlkopf ein. Ab hier heißt sein Endstück N. laryngeus inferior. Bei etwa 60 % der Menschen teilt er sich schon vor dem Eintritt, meist 1–2 cm unterhalb des Gelenks, in mehrere Äste. Der vordere Ast führt fast alle motorischen Fasern; der hintere ist überwiegend sensibel. Wer bei der Operation nur einen Ast schont, kann also trotzdem die Bewegung verlieren. Abb. 3.3 Schematische Seitenansicht, vorne links. Der Nerv tritt direkt hinter dem Krikothyreoidgelenk (schwarzer Punkt) in den Kehlkopf. Die Teilung vor dem Eintritt ist häufig, aber nicht immer vorhanden. Abruf F5. An welchem Band ist der Nerv bei der Schilddrüsenoperation am stärksten gefährdet? F6. Wo tritt der Nerv in den Kehlkopf ein, und wie heißt sein Endstück? F7. Welcher Ast führt bei einer Teilung die motorischen Fasern?"},{"unit":"03","id":"h-3-4-was-der-n-laryngeus-recurrens-versorgt","title":"3.4 · Was der N. laryngeus recurrens versorgt","body":"3.4 · Was der N. laryngeus recurrens versorgt Motorisch versorgt er alle inneren Kehlkopfmuskeln außer dem M. cricothyroideus: Postikus, Lateralis, Transversus und Thyroarytänoid mit dem Vocalis. Damit steuert er die einzige Öffnung der Stimmritze und den größten Teil des Schlusses. Sensibel versorgt er die Schleimhaut unterhalb der Stimmlippen, den subglottischen Raum. Unterwegs gibt er außerdem Äste zu Luftröhre und Speiseröhre ab. Im Kehlkopf ist er oft durch eine Verbindung mit dem R. internus des oberen Kehlkopfnervs verbunden, die Galen-Anastomose (Ansa Galeni); sie wurde in einer Studie bei 81 % der untersuchten Kehlköpfe gefunden und führt überwiegend sensible Fasern. Solche Verbindungen sind ein Grund, warum Lähmungsbilder nicht immer dem Lehrbuch folgen. Abb. 3.4 Dieselbe Karte wie im Styleguide und in Abschnitt 2, diesmal mit dem N. laryngeus recurrens hervorgehoben. Fett umrandet: der Postikus, weil sein Ausfall die Atmung gefährdet. Abruf F8. Welchen inneren Kehlkopfmuskel versorgt der N. laryngeus recurrens nicht? F9. Welche Schleimhaut versorgt er sensibel, und mit welchem Nerv ist er oft über die Galen-Anastomose verbunden?"},{"unit":"03","id":"h-3-5-vom-verlauf-zur-klinik-wer-ist-gefaehrdet","title":"3.5 · Vom Verlauf zur Klinik: wer ist gefährdet?","body":"3.5 · Vom Verlauf zur Klinik: wer ist gefährdet? Mit dem Verlauf kannst du die Ursachen einer Rekurrensparese fast selbst herleiten. Überall, wo der Nerv vorbeikommt, kann er gedrückt, gedehnt oder durchtrennt werden: Stelle Typische Ursachen Seite Hals, hinter der Schilddrüse Schilddrüsen- und Nebenschilddrüsenoperationen, Schilddrüsenkrebs, Operationen an der Halswirbelsäule von vorn beide Brustraum, um den Aortenbogen Lungenkrebs (v. a. linker Oberlappen), vergrößerte Lymphknoten im Mittelfell, Speiseröhrenkrebs, Aortenaneurysma, Herz- und Brustkorboperationen; selten ein vergrößerter linker Vorhof (Ortner-Syndrom) vor allem links Rechts oben, um die A. subclavia Tumoren der Lungenspitze, Operationen in diesem Bereich rechts Kehlkopf selbst Druck durch den Manschettenballon bei der Intubation beide Fällt der Nerv auf einer Seite aus, bewegt sich die Stimmlippe dieser Seite nicht mehr: Die Stimme wird behaucht und schwach, Flüssigkeiten können in die Luftröhre gelangen. Fallen beide aus, bleiben beide Stimmlippen nahe der Mitte stehen: Die Atmung wird gefährlich eng, oft bei erstaunlich guter Stimme. Beides behandeln wir ausführlich in den Abschnitten zu den Lähmungen. Kinder Bei Frühgeborenen wird ein offener Ductus arteriosus manchmal operativ verschlossen. Der linke N. laryngeus recurrens liegt direkt daneben. Eine Metaanalyse fand nach dem chirurgischen Verschluss bei etwa 8 % der Kinder eine Stimmlippenlähmung, nach Ligatur rund 12 %; untersucht man alle Kinder gezielt mit Endoskopie, findet man noch mehr. Hinweise sind ein schwaches oder heiseres Schreien, Husten oder Verschlucken beim Trinken und Lungenentzündungen. Auch andere Herzoperationen am Aortenbogen gefährden den linken Nerv. ! Warnzeichen Eine neue Heiserkeit mit stillstehender Stimmlippe ohne erklärende Operation muss ärztlich abgeklärt werden, mit Bildgebung entlang des ganzen Nervenverlaufs von der Schädelbasis bis zum Aortenbogen. Hinter einer „einfachen“ linksseitigen Rekurrensparese kann ein Tumor im Brustraum stecken. Abruf F10. Nenne zwei Gründe, warum der linke Nerv häufiger ausfällt als der rechte. F11. Warum ist ein Frühgeborenes nach Verschluss des Ductus arteriosus besonders gefährdet, und auf welcher Seite?"},{"unit":"03","id":"h-3-6-zwei-mini-faelle","title":"3.6 · Zwei Mini-Fälle","body":"3.6 · Zwei Mini-Fälle Erwachsene · Herr M., 67, Raucher Herr M. ist seit sechs Wochen heiser, seine Stimme ist leise und behaucht, beim Trinken verschluckt er sich öfter. Er hat in den letzten Monaten abgenommen. Operiert wurde er nie. Die Laryngoskopie zeigt eine stillstehende linke Stimmlippe. F12. Welcher Nerv ist betroffen? Warum ist gerade die linke Seite in seiner Situation verdächtig, und welche Untersuchung muss jetzt folgen, bevor Stimmtherapie geplant wird? Kind · Mia, 3 Monate, ehemaliges Frühgeborenes Mia hatte in der 2. Lebenswoche eine Operation zum Verschluss des Ductus arteriosus. Seitdem schreit sie leise und heiser und verschluckt sich beim Trinken; sie atmet ruhig und ohne Geräusch. F13. Welcher Nerv, welche Seite? Warum ist ihre Atmung ruhig, obwohl der Nerv auch den einzigen Öffner versorgt? Häufige Fehlvorstellungen „Der N. laryngeus recurrens versorgt alle Kehlkopfmuskeln.“ Alle inneren außer dem M. cricothyroideus. „Beide Nerven schlingen sich um den Aortenbogen.“ Nur der linke. Der rechte schlingt sich um die A. subclavia dextra. „Der rechte Nerv ist immer rekurrent.“ Bei etwa 0,7 % geht er direkt am Hals ab, meist zusammen mit einer A. lusoria. „Bei der Teilung versorgt der vordere Ast die Schließer, der hintere den Öffner.“ Diese ältere Einteilung stimmt so nicht: Der vordere Ast führt fast alle motorischen Fasern, also auch die für den Postikus; der hintere ist überwiegend sensibel. „Der N. laryngeus inferior ist ein eigener Nerv.“ Es ist das Endstück des N. laryngeus recurrens nach dem Eintritt in den Kehlkopf. „Der Nerv liegt immer hinter der A. thyroidea inferior.“ Seine Lage zu dieser Arterie ist sehr variabel."},{"unit":"03","id":"h-zusammenfassung-in-fuenf-zeilen","title":"Zusammenfassung in fünf Zeilen","body":"Zusammenfassung in fünf Zeilen Der N. laryngeus recurrens geht im Brustraum vom N. vagus ab: rechts um die A. subclavia dextra, links um den Aortenbogen. Grund ist die Embryologie: Der Nerv bleibt unter der tiefsten erhaltenen Bogenarterie eingehakt; rechts fehlt sie selten ganz (nicht-rekurrenter Nerv, ≈ 0,7 %). Am Hals steigt er zwischen Luft- und Speiseröhre auf, ist am Berry-Band am stärksten gefährdet und tritt hinter dem Krikothyreoidgelenk ein. Er versorgt alle inneren Kehlkopfmuskeln außer dem Antikus und die Schleimhaut unterhalb der Stimmlippen. Links läuft's länger: Tumoren im Brustraum, Herz- und Aortenoperationen und bei Frühgeborenen der Ductusverschluss treffen vor allem den linken Nerv. Aus dem Gedächtnis zeichnen · 5 Minuten, leeres Blatt Zeichne in der Mitte Kehlkopf und Luftröhre von vorn. Schreib R links und L rechts. Zeichne beidseits einen gelben N. vagus nach unten. Zeichne rechts eine rote waagrechte Arterie (A. subclavia dextra), links tiefer einen roten Bogen (Aortenbogen). Lass rechts den violetten Nerv unter der Arterie hindurch und neben der Luftröhre nach oben laufen, links unter dem Bogen. Pfeilspitzen nach oben. Markiere die Eintrittsstelle hinter dem Krikothyreoidgelenk und schreib daneben: „alle inneren Muskeln außer Antikus“. Vergleiche mit Abb. 3.1 und 3.4. Was fehlt, kommt auf eine Lernkarte. Lösungen zu F1–F13 (erst nach eigenem Versuch öffnen) F1. Rechts um die A. subclavia dextra, links um den Aortenbogen (seitlich vom Lig. arteriosum). F2. In der Rinne zwischen Luftröhre und Speiseröhre (Sulcus tracheooesophageus). F3. Unter der Arterie des 6. Schlundbogens. Links bleibt sie als Ductus arteriosus erhalten und wird zum Lig. arteriosum. F4. Ein Nerv, der direkt am Hals vom N. vagus zum Kehlkopf zieht, ohne Schlinge. Fast nur rechts (≈ 0,7 %), meist zusammen mit einer A. lusoria, also einer rechten Schlüsselbeinarterie, die hinter der Speiseröhre von der Aorta abgeht. F5. Am Berry-Band, wo die Schilddrüse seitlich an der Luftröhre befestigt ist. F6. Unter dem Unterrand des unteren Schlundschnürers, direkt hinter dem Krikothyreoidgelenk; das Endstück heißt N. laryngeus inferior. F7. Der vordere Ast. F8. Den M. cricothyroideus (Antikus); den versorgt der R. externus des N. laryngeus superior. F9. Die Schleimhaut unterhalb der Stimmlippen; über die Galen-Anastomose ist er mit dem R. internus des N. laryngeus superior verbunden. F10. Er ist länger und hat einen langen Abschnitt im Brustraum; dort liegen viele mögliche Ursachen wie Lungen- und Speiseröhrentumoren, Lymphknoten, Aorta und Herz bzw. Operationen daran. F11. Der linke N. laryngeus recurrens schlingt sich direkt neben dem Ductus arteriosus um den Aortenbogen und kann beim Verschluss verletzt werden. Links. F12. Der linke N. laryngeus recurrens. Ohne Operation in der Vorgeschichte, als Raucher mit Gewichtsverlust, ist ein Tumor im Brustraum (z. B. Lungenkrebs oder Lymphknoten am Aortenbogen) verdächtig. Vor jeder Therapieplanung: ärztliche Abklärung mit Bildgebung des ganzen Nervenverlaufs, von der Schädelbasis bis zum Aortenbogen. F13. Der linke N. laryngeus recurrens. Ihre Atmung ist ruhig, weil nur eine Seite betroffen ist: Der rechte Postikus öffnet die Stimmritze weiter, das reicht zum Atmen. Gefährlich eng wird es erst, wenn beide Seiten ausfallen."},{"unit":"03","id":"h-quellen","title":"Quellen","body":"Quellen Schünke M, Schulte E, Schumacher U. PROMETHEUS LernAtlas: Kopf, Hals und Neuroanatomie. 6. Aufl. Thieme; 2022. Standring S (Hrsg.). Gray's Anatomy. 42nd ed. Elsevier; 2020 (Verlauf, Beziehungen am Hals, Versorgungsgebiet). Sadler TW. Medizinische Embryologie (Langman). Thieme, aktuelle Auflage (Schlundbogenarterien, Verlauf des Rekurrens). Henry BM, Vikse J, Graves MJ et al. Extralaryngeal branching of the recurrent laryngeal nerve: a meta-analysis of 28,387 nerves. Langenbecks Arch Surg 2016. PMC5086344 (Teilung bei 60 %, meist 1–2 cm unterhalb des Gelenks; motorische Fasern im vorderen Ast). Henry BM et al. The non-recurrent laryngeal nerve: a meta-analysis and clinical considerations. PeerJ 2017;5:e3012. doi:10.7717/peerj.3012 (0,7 % rechts, 86,7 % mit A. lusoria). Naidu L et al. Galen's „Anastomosis“ revisited. Clin Anat 2012. doi:10.1002/ca.22011 (81 % von 50 Kehlköpfen). Incidence, risk factors, and comorbidities of vocal cord paralysis after surgical closure of a patent ductus arteriosus: a meta-analysis. Pediatr Cardiol 2019. doi:10.1007/s00246-018-1967-8 (gepoolt 7,9 %, Ligatur 11,7 %). Chandrasekhar SS et al. Clinical Practice Guideline: Improving Voice Outcomes after Thyroid Surgery. Otolaryngol Head Neck Surg 2013. doi:10.1177/0194599813487301. DGPP. S2k-Leitlinie Diagnostik und Therapie von Störungen der Stimmfunktion (Dysphonien), AWMF 049-008, 2023."},{"unit":"04","id":null,"title":"Die Gesamtkarte: Nerv → Muskel → Wirkung","body":"Kernpfad · Abschnitt 4 von 10 Die Gesamtkarte: Nerv → Muskel → Wirkung ≈ 20 MinutenBaut auf: Abschnitte 1–3Weiter: Stimmentstehung Nach diesem Abschnitt kannst du Die vollständige Karte aus dem Gedächtnis zeichnen: zwei Nerven, fünf Muskelgruppen, zwei Empfindungsgebiete, ihre Wirkungen. Für den Ausfall jedes Astes vorhersagen, welche Funktionen verloren gehen und welche bleiben. Aus einem Symptom auf den beteiligten Nerv und Muskel schließen. Warum das für dich als Logopädin wichtig ist „Welcher Nerv versorgt welchen Kehlkopfmuskel, und was passiert bei Ausfall?“ ist die klassische Prüfungsfrage, mündlich wie schriftlich. In der Praxis ist es die Übersetzungshilfe zwischen dem HNO-Befund und dem, was du hörst: Diese eine Karte verbindet Anatomie, Laryngoskopie und Stimmklang. Dieser Abschnitt bringt nichts Neues; er fügt die Abschnitte 1–3 zusammen und lässt dich damit arbeiten."},{"unit":"04","id":"h-4-1-die-karte-und-was-bei-ausfall-verloren-geht","title":"4.1 · Die Karte, und was bei Ausfall verloren geht","body":"4.1 · Die Karte, und was bei Ausfall verloren geht Die Karte liest du von links nach rechts: Nerv → Ast → Muskel oder Empfindungsgebiet → Wirkung. Pfeile zum Muskel bedeuten Bewegungsbefehl, Pfeile zurück zum Nerv bedeuten eine Meldung an das Gehirn. Gelb ist der N. vagus, türkis der N. laryngeus superior, violett der N. laryngeus recurrens; jeder Muskel trägt außerdem ein Schild SLN oder RLN. So übst du damit: Bevor du einen Ausfall anklickst, sag laut, was verloren geht und was bleibt. Dann klicken und vergleichen. Das Vorhersagen ist die eigentliche Übung. Vollständige Karte Ausfall R. externus Ausfall R. internus Ausfall N. recurrens (eine Seite) Merkhilfe: die drei „Einzigen“ Der Antikus ist der einzige Muskel des N. laryngeus superior und der einzige außen am Kehlkopf. Der Postikus ist der einzige Öffner. Der Transversus ist der einzige unpaare Muskel und vielleicht der einzige mit doppelter Versorgung. Alles andere schließt und wird vom N. laryngeus recurrens versorgt. Abruf · ohne nachzusehen F1. Welche Funktionen bleiben erhalten, wenn auf einer Seite nur der N. laryngeus recurrens ausfällt? F2. Bei welchem Ausfall bleibt die Stimme normal, und warum ist er trotzdem gefährlich? F3. Welche Wirkung in der Karte gibt es nur einmal, und welcher Muskel erzeugt sie?"},{"unit":"04","id":"h-4-2-die-empfindungskarte-oben-mitte-unten","title":"4.2 · Die Empfindungskarte: oben, Mitte, unten","body":"4.2 · Die Empfindungskarte: oben, Mitte, unten Für Schutz und Schlucken zählt, wer welche Schleimhaut „spürt“. Die Grenze ist die Stimmlippe: Oberhalb (Kehldeckel, aryepiglottische Falten, Vorhof, Taschenfalten, Recessus piriformis): R. internus des N. laryngeus superior. Stimmlippenebene: beide Nerven überlappen sich. Unterhalb (subglottischer Raum, obere Luftröhre): N. laryngeus recurrens. Die meisten Bissen und Tropfen, die „falsch“ laufen, treffen zuerst die Schleimhaut oberhalb. Deshalb ist der R. internus der wichtigste Wächter, und sein Ausfall ist das typische Bild der stillen Aspiration. Abb. 4.2 Dieselbe Darstellung wie Abb. 2.2, Frontalschnitt von vorn (R und L der Patientin). Grau: Überlappungszone auf Stimmlippenhöhe. Abruf F4. Welcher Nerv versorgt den Recessus piriformis sensibel? F5. Warum ist der Ausfall der Empfindung oberhalb der Stimmlippen für das Schlucken wichtiger als der unterhalb?"},{"unit":"04","id":"h-4-3-vom-muskel-zum-befund-was-du-siehst-und-hoerst","title":"4.3 · Vom Muskel zum Befund: was du siehst und hörst","body":"4.3 · Vom Muskel zum Befund: was du siehst und hörst Fällt ein Muskel auf einer Seite aus, kannst du seine Funktion in einen Befund übersetzen. Diese Tabelle ist die Brücke zu den Lähmungsabschnitten: Muskel fällt aus Nerv Was man sieht Was man hört oder merkt Antikus SLN Bewegung normal; bei Phonation evtl. kürzere, durchgebogene Stimmlippe, oft kaum sichtbar Hohe Töne und Umfang fehlen, Stimme ermüdet, trägt schlecht Postikus RLN Stimmlippe geht beim Einatmen nicht nach außen Einseitig meist kein Atemproblem; beidseitig Stridor Lateralis, Transversus RLN Stimmlippe kommt bei Phonation nicht zur Mitte: Spalt (Glottisschlussinsuffizienz) Behauchte, leise Stimme, kurze Tonhaltedauer, schwacher Husten, Verschlucken bei Flüssigkeit Vokalis/Externus RLN Stimmlippe schlaff, kürzer, später dünner (Atrophie) Wenig Spannung und Kraft; Stimme kann zittern oder doppeltönig sein Weil der N. laryngeus recurrens alle Muskeln der Tabelle außer dem Antikus versorgt, fallen bei einer Rekurrensparese die drei unteren Zeilen zusammen aus. Wo die gelähmte Stimmlippe dann stehen bleibt, hängt unter anderem davon ab, ob der Antikus noch zieht; das ist ein Thema der Lähmungsabschnitte."},{"unit":"04","id":"h-4-4-gemischte-uebung-der-laesionsdetektiv","title":"4.4 · Gemischte Übung: der Läsionsdetektiv","body":"4.4 · Gemischte Übung: der Läsionsdetektiv Die Aufgaben sind absichtlich gemischt, damit du jedes Mal neu entscheiden musst, welcher Nerv gemeint ist. Schreib zu jeder Aufgabe Nerv, Ast und Seite auf, bevor du weiterliest. Abruf · Symptom → Nerv F6. Eine Lehrerin kann nach einer Schilddrüsenoperation nicht mehr laut über die Klasse rufen, ihre Sprechstimme klingt normal, in der Laryngoskopie bewegen sich beide Stimmlippen. F7. Ein Patient verschluckt sich nicht hörbar, aber in der Schluckendoskopie liegt Joghurt im Kehlkopfvorhof, ohne dass er reagiert. Die Stimme ist normal. F8. Eine Frau hat seit einer Herzoperation eine behauchte, leise Stimme; die linke Stimmlippe steht still. F9. Beide Stimmlippen stehen nahe der Mitte, beim Einatmen pfeift es, die Stimme ist fast normal. F10. Die rechte Stimmlippe steht still, und das Gaumensegel hebt sich rechts schlechter, und der Patient spürt Getränke rechts im Hals nicht. Wo liegt die Läsion eher: am N. laryngeus recurrens oder höher am N. vagus?"},{"unit":"04","id":"h-4-5-zwei-mini-faelle","title":"4.5 · Zwei Mini-Fälle","body":"4.5 · Zwei Mini-Fälle Erwachsene · Herr B., 55, nach Operation an der Halswirbelsäule von vorn Seit der Operation ist Herr B. heiser und behaucht, er hält ein „a“ nur 5 Sekunden lang und verschluckt sich bei Wasser. Hohe Töne kann er noch ansteuern, aber ohne Kraft. Die rechte Stimmlippe bewegt sich nicht. F11. Welcher Nerv ist betroffen? Welche Zeilen der Tabelle in 4.3 erklären seine Symptome, und warum ist die Tonhöhe nicht ganz verloren? Kind · Paul, 5 Monate Paul hat eine Fehlbildung am Übergang vom Gehirn zum Rückenmark (Chiari-Malformation) mit erhöhtem Hirndruck. Er atmet laut beim Einatmen, besonders im Schlaf, schreit aber kräftig. Die Endoskopie zeigt beide Stimmlippen nahe der Mitte. F12. Welche Muskeln arbeiten bei Paul nicht, und warum passt ein kräftiges Schreien dazu? Warum kann die Ursache im Gehirn liegen, obwohl die Muskeln im Kehlkopf sitzen? Häufige Fehlvorstellungen „Rekurrensparese = Stimmlippe steht ganz außen.“ Meist steht sie nahe der Mitte oder in Zwischenstellung, nicht ganz außen. Die genaue Stellung ist variabel und kein sicherer Hinweis auf den Läsionsort. „Wer gut spricht, hat keine Nervenlähmung.“ Ein Ausfall des R. externus oder des R. internus kann die Sprechstimme fast normal lassen, und bei beidseitiger Rekurrensparese ist die Stimme oft gut, während die Atmung gefährdet ist. „Die Empfindung ist für die Logopädie egal.“ Sie ist der Ausgangspunkt jedes Schutzreflexes und damit zentral für Schluckdiagnostik und -therapie. „Ein kleiner Spalt hinten bei normaler Beweglichkeit zeigt eine Nervenlähmung.“ Ein hinterer Spalt bei normaler Beweglichkeit ist oft ein funktionelles Schlussmuster (Transversusschwäche), keine Nervenläsion."},{"unit":"04","id":"h-zusammenfassung-in-fuenf-zeilen","title":"Zusammenfassung in fünf Zeilen","body":"Zusammenfassung in fünf Zeilen N. vagus → N. laryngeus superior (R. externus motorisch, R. internus sensibel) und N. laryngeus recurrens (motorisch und sensibel). R. externus → Antikus → Spannung und Tonhöhe. Alle anderen inneren Muskeln → N. laryngeus recurrens. Öffnen kann nur der Postikus; schließen können Lateralis, Transversus und Thyroarytänoid. Empfindung oberhalb der Stimmlippen: R. internus; unterhalb: N. laryngeus recurrens; dazwischen Überlappung. Ausfall außen = Höhe fehlt; Ausfall innen = stille Aspiration; Rekurrens einseitig = Spalt und Behauchtheit; Rekurrens beidseitig = Atemnot. Aus dem Gedächtnis zeichnen · 7 Minuten, leeres Blatt Schreib vier Spaltenüberschriften: Nerv · Ast · Muskel/Empfindung · Wirkung. Links ein gelbes Kästchen „N. vagus“. Drei Äste: R. externus und R. internus (türkis), N. laryngeus recurrens (violett). Ordne zu: R. externus → Antikus; R. internus ← Empfindung oben; Rekurrens → Postikus, Lateralis, Transversus, Vokalis; Rekurrens ← Empfindung unten. Schreib zu jedem Muskel seine Wirkung. Umrande den Postikus fett. Setz mit einem anderen Stift ein ✕ auf einen Ast deiner Wahl und schraffiere, was ausfällt. Vergleiche mit der Karte in 4.1. Jede Lücke wird eine Lernkarte. Lösungen zu F1–F12 (erst nach eigenem Versuch öffnen) F1. Die Funktionen des N. laryngeus superior: Spannung und Tonhöhe über den Antikus sowie die Empfindung oberhalb der Stimmlippen mit dem Schutzreflex. Außerdem arbeitet die andere Seite normal. F2. Beim Ausfall des R. internus. Ohne Empfindung oberhalb der Stimmlippen startet der Schutzreflex nicht, und es kommt zu stiller Aspiration. F3. „Öffnet die Glottis“, erzeugt allein vom Postikus (M. cricoarytaenoideus posterior). F4. Der R. internus des N. laryngeus superior. F5. Material, das falsch läuft, trifft zuerst die Schleimhaut oberhalb der Stimmlippen. Fehlt dort die Empfindung, wird der Schutzreflex nicht ausgelöst, bevor das Material die Stimmlippen erreicht. F6. R. externus des N. laryngeus superior (Antikus): Spannung und Tragfähigkeit fehlen, Beweglichkeit normal. Seite: die verletzte; nach Schilddrüsenoperation kann auch beidseits betroffen sein. F7. R. internus des N. laryngeus superior: fehlende Empfindung oberhalb der Stimmlippen, stille Aspiration bzw. Penetration. F8. Linker N. laryngeus recurrens; er schlingt sich um den Aortenbogen und ist bei Herzoperationen gefährdet. F9. N. laryngeus recurrens beidseits: Beide Postikusmuskeln fehlen, die Stimmlippen stehen nahe der Mitte, deshalb Stridor bei guter Stimme. F10. Höher am N. vagus, oberhalb des Abgangs des N. laryngeus superior: Gaumensegel (Rachenäste), Empfindung oben (R. internus) und Stimmlippe (N. laryngeus recurrens) sind zusammen betroffen. Eine reine Rekurrensparese würde Gaumen und Empfindung oben verschonen. F11. Rechter N. laryngeus recurrens: Er läuft im Operationsgebiet an der Luftröhre vorbei, und die rechte Stimmlippe steht still. Es passen die Zeilen Lateralis/Transversus (Spalt, Behauchtheit, kurze Tonhaltedauer, Verschlucken bei Wasser) und Vokalis (wenig Kraft). Der Antikus (N. laryngeus superior) arbeitet noch, deshalb ist Tonhöhe teilweise steuerbar. F12. Beide Postikusmuskeln, also die Öffner beider Seiten. Die Stimmlippen stehen nahe der Mitte und können gut schwingen, deshalb ist das Schreien kräftig. Die Nervenzellen für die Kehlkopfmuskeln liegen im Hirnstamm (Nucleus ambiguus), und die Nervenwurzeln des N. vagus verlassen den Hirnstamm genau im Bereich, auf den eine Chiari-Malformation mit erhöhtem Hirndruck drücken oder an dem sie ziehen kann."},{"unit":"04","id":"h-quellen","title":"Quellen","body":"Quellen Schünke M, Schulte E, Schumacher U. PROMETHEUS LernAtlas: Kopf, Hals und Neuroanatomie. 6. Aufl. Thieme; 2022. Standring S (Hrsg.). Gray's Anatomy. 42nd ed. Elsevier; 2020. Wendler J, Seidner W, Eysholdt U. Lehrbuch der Phoniatrie und Pädaudiologie. 5. Aufl. Thieme; 2015 (Lähmungsbilder, Transversusschwäche). Orestes MI, Chhetri DK. Superior laryngeal nerve injury. Curr Opin Otolaryngol Head Neck Surg 2014. doi:10.1097/MOO.0000000000000097. Lechien JR. Management of pediatric bilateral vocal fold paralysis. Children 2024;11(4):398. doi:10.3390/children11040398 (Ursachen bei Kindern, u. a. Chiari-Malformation). DGPP. S2k-Leitlinie Diagnostik und Therapie von Störungen der Stimmfunktion (Dysphonien), AWMF 049-008, 2023. Abschnitte 1–3 dieses Kurses mit ihren Einzelquellen."},{"unit":"05","id":null,"title":"Stimmentstehung: Wie aus Luft und Muskeln ein Ton wird","body":"Kernpfad · Abschnitt 5 von 10 Stimmentstehung: Wie aus Luft und Muskeln ein Ton wird ≈ 20 MinutenBaut auf: Abschnitte 1–4Weiter: Schutzfunktionen, Atmung und Schlucken Nach diesem Abschnitt kannst du Einen Schwingungszyklus der Stimmlippen in fünf Schritten erklären. Den Schichtaufbau der Stimmlippe (Body-Cover-Modell) beschreiben und sagen, wie er sich beim Kind unterscheidet. Für Tonhöhe, Lautstärke und Register angeben, welche Muskeln und Nerven sie steuern. Vorhersagen, wie sich eine Nervenlähmung auf Klang, Tonhaltedauer und Stimmumfang auswirkt. Warum das für dich als Logopädin wichtig ist Alles, was du in der Stimmdiagnostik misst, ist ein Teil dieses Abschnitts: Tonhaltedauer, Stimmfeld, Behauchtheit, Lautstärke. Wenn du verstehst, wie der Ton entsteht, kannst du erklären, warum eine Patientin mit Rekurrensparese nur 5 Sekunden ein „a“ halten kann, und deine Übungen gezielt an der Stelle ansetzen, an der der Mechanismus versagt."},{"unit":"05","id":"h-5-1-der-motor-luftdruck-gegen-elastisches-gewebe","title":"5.1 · Der Motor: Luftdruck gegen elastisches Gewebe","body":"5.1 · Der Motor: Luftdruck gegen elastisches Gewebe Die Stimme entsteht nicht dadurch, dass Muskeln jede Schwingung einzeln „schlagen“. Bei 200 Schwingungen pro Sekunde wäre das unmöglich. Die Muskeln stellen die Stimmlippen nur ein: Sie schließen sie und geben ihnen eine bestimmte Spannung. Den Rest erledigen Luftdruck und Elastizität. Das beschreibt die myoelastisch-aerodynamische Theorie (van den Berg 1958): myo-elastisch für Muskelspannung und Gewebeelastizität, aerodynamisch für den Luftstrom. Unter den geschlossenen Stimmlippen staut sich die Ausatemluft; dieser Druck heißt subglottischer Druck (subglottisch = unterhalb der Stimmritze). Ein Zyklus läuft so ab: Geschlossen: Der subglottische Druck steigt. Unten öffnet sich zuerst: Der Druck drückt die Unterkanten auseinander. Offen: Auch die Oberkanten weichen, ein kurzer Luftstoß entweicht, der Druck fällt. Unten schließt sich zuerst: Die elastischen Rückstellkräfte ziehen die Unterkanten zurück. Geschlossen: Die Oberkanten folgen, der Druck baut sich wieder auf. Weil Unter- und Oberkante zeitversetzt schwingen, läuft eine Welle über die Schleimhaut von unten nach oben: die Randkantenverschiebung (mukosale Welle), die man in der Stroboskopie sieht. Diese zeitliche Verschiebung sorgt dafür, dass die Luft beim Öffnen mehr Energie ins Gewebe bringt als beim Schließen; so hält sich die Schwingung selbst am Laufen. Der Bernoulli-Effekt (Sog im engen Spalt) trägt zum Schließen bei, wurde in älteren Büchern aber überbetont. Abb. 5.1 Ein Schwingungszyklus, Frontalschnitt durch beide Stimmlippen. Bei einer Frauenstimme läuft er etwa 200-mal pro Sekunde ab. Abruf · ohne nachzusehen F1. Was machen die Muskeln bei der Stimmgebung, und was machen Luftdruck und Elastizität? F2. Welcher Teil der Stimmlippe öffnet und schließt sich zuerst, und wie heißt die daraus entstehende Welle?"},{"unit":"05","id":"h-5-2-der-bau-der-stimmlippe-body-und-cover","title":"5.2 · Der Bau der Stimmlippe: Body und Cover","body":"5.2 · Der Bau der Stimmlippe: Body und Cover Die Schwingung funktioniert nur, weil die Stimmlippe geschichtet ist (Hirano 1974): Cover (Hülle): das Epithel (die oberste Zellschicht) und darunter eine sehr lockere, fast gallertige Schicht, der Reinke-Raum (oberflächliche Lamina propria). Sie ist weich und beweglich; sie trägt die Randkantenverschiebung. Übergang: mittlere und tiefe Lamina propria, zusammen das Stimmband (Lig. vocale), fester und faserreich. Body (Körper): der M. vocalis, dessen Spannung über den N. laryngeus recurrens gesteuert wird. Für die Praxis ist das eine Sortierhilfe: Nervenlähmungen betreffen den Body (der Muskel wird schlaff), Knötchen, Polypen und Reinke-Ödem betreffen das Cover (die Hülle wird steif oder schwer). Beides stört die Schwingung, aber auf verschiedene Weise. Abb. 5.2 Frontalschnitt durch eine Stimmlippe, Mitte rechts. Weiß mit schwarzem Rand = Cover; grau = Übergang (Stimmband); rotbraun = Body. Schematisch, nicht maßstäblich. Kinder Beim Neugeborenen ist die Lamina propria noch gleichförmig; es gibt keinen Reinke-Raum und kein abgegrenztes Stimmband. Die Schichten entwickeln sich im Lauf der Kindheit; die oberflächliche Schicht wird etwa zwischen 7 und 12 Jahren erkennbar, eine erwachsenenähnliche Faserordnung um das 13. Lebensjahr. Die Altersangaben schwanken zwischen den Studien. Dazu sind die Stimmlippen kurz: Kinderstimmen liegen deshalb hoch, etwa um 250–300 Hz in der Sprechstimme, und die junge, weiche Hülle reagiert empfindlich auf viel Schreien, was Stimmlippenknötchen bei Kindern begünstigt. Abruf F3. Ordne zu: Reinke-Raum, Lig. vocale, M. vocalis → Cover, Übergang, Body. F4. Welche Schicht betrifft eine Rekurrensparese vor allem, welche ein Stimmlippenknötchen?"},{"unit":"05","id":"h-5-3-tonhoehe-lautstaerke-register-wer-stellt-was-ein","title":"5.3 · Tonhöhe, Lautstärke, Register: wer stellt was ein?","body":"5.3 · Tonhöhe, Lautstärke, Register: wer stellt was ein? Tonhöhe ist die Zahl der Schwingungen pro Sekunde, die Grundfrequenz (F0, in Hertz). Sie steigt, wenn die Stimmlippe länger, dünner und straffer wird, also vor allem durch den Antikus (R. externus des N. laryngeus superior). Etwa: Männer 100–130 Hz, Frauen 190–230 Hz, Kinder 250–300 Hz in der Sprechstimme. Lautstärke hängt vom subglottischen Druck ab und davon, wie lange und fest die Stimmlippen pro Zyklus geschlossen sind. Dafür braucht es einen guten Schluss: Lateralis, Transversus und Thyroarytänoid (N. laryngeus recurrens) plus Atemdruck. Register sind Klangbereiche mit eigener Schwingungsform. In der Bruststimme (Modalregister) überwiegt der Thyroarytänoid: Die Stimmlippen sind dick und berühren sich über eine große Fläche. In der Kopfstimme bzw. im Falsett überwiegt der Antikus: Die Stimmlippen sind dünn gedehnt, nur die Ränder schwingen, der Schluss ist kurz oder unvollständig. Der Wechsel zwischen beiden ist das Gleichgewicht von Antikus und Vokalis aus Abschnitt 1. Abb. 5.3 Links Antrieb, Mitte Muskeln, rechts die hörbaren Stimmparameter. Fett umrandet: Tonhöhe, weil sie fast nur über einen Nerv (SLN) gesteuert wird und deshalb bei dessen Ausfall gezielt leidet. Abb. 5.4 Die Form der schwingenden Stimmlippe bestimmt das Register. Schematisch. Abruf F5. Welcher Muskel hebt vor allem die Tonhöhe, und welcher Nerv versorgt ihn? F6. Wovon hängt die Lautstärke ab? Nenne zwei Faktoren. F7. Welcher Muskel überwiegt in der Bruststimme, welcher in der Kopfstimme?"},{"unit":"05","id":"h-5-4-was-eine-laehmung-an-der-stimme-aendert","title":"5.4 · Was eine Lähmung an der Stimme ändert","body":"5.4 · Was eine Lähmung an der Stimme ändert Jetzt kannst du die Befunde aus der Stimmdiagnostik aus dem Mechanismus herleiten: Messung Was sie zeigt Einseitige Rekurrensparese RLN Ausfall R. externus SLN Tonhaltedauer (ein „a“ so lang wie möglich) Wie dicht der Schluss ist Stark verkürzt, oft unter 10 s: Luft entweicht durch den Spalt, der Druck baut sich nicht auf Meist normal Hörbarer Klang (RBH) Rauigkeit, Behauchtheit, Heiserkeit B deutlich erhöht, oft auch R; Doppeltönigkeit möglich, weil die schlaffe Seite anders schwingt Leicht, oft nur in der Höhe hörbar Stimmfeld (Phonetogramm) Tonhöhen- und Lautstärkeumfang Klein, besonders nach oben in der Lautstärke (leise Stimme) Obere Tonhöhengrenze abgesenkt Stroboskopie Schwingung und Schluss Schlussinsuffizienz, unregelmäßige und seitenungleiche Schwingung, gelähmte Seite schwingt schlaff mit großer Amplitude Oft fast normal; Asymmetrie beim Gleiten nach oben Die Werte für die Tonhaltedauer hängen von Alter, Geschlecht und Übung ab; bei Erwachsenen gelten Werte unter etwa 10 Sekunden meist als auffällig, bei Kindern liegen die Normwerte niedriger."},{"unit":"05","id":"h-5-5-zwei-mini-faelle","title":"5.5 · Zwei Mini-Fälle","body":"5.5 · Zwei Mini-Fälle Erwachsene · Frau S., 48, Rekurrensparese links nach Schilddrüsenoperation Frau S. kann ein „a“ nur 4 Sekunden halten. Ihre Stimme ist leise und behaucht, bei längeren Sätzen geht ihr die Luft aus. Manchmal klingt die Stimme „doppelt“. F8. Erkläre mit dem Schwingungszyklus, warum ihr die Luft ausgeht und warum sie nicht laut werden kann. Woher kommt der doppelte Klang? Kind · Lukas, 7, „Schreikind“ im Fußballverein Lukas ist seit Monaten heiser, seine Stimme klingt rau. In der Laryngoskopie bewegen sich beide Stimmlippen normal; an beiden sieht man kleine Verdickungen am Übergang vom vorderen zum mittleren Drittel, beim Schließen bleibt vorne und hinten ein kleiner Spalt (Sanduhrform). F9. Liegt hier eine Nervenlähmung vor? Welche Schicht der Stimmlippe ist betroffen, und warum klingt die Stimme eher rau als stark behaucht? Häufige Fehlvorstellungen „Für jede Schwingung schickt das Gehirn einen Nervenimpuls.“ Die Nerven stellen nur Schluss und Spannung ein; die Schwingung selbst entsteht passiv aus Luftdruck und Elastizität. „Der Bernoulli-Effekt erklärt die Stimme.“ Er hilft beim Schließen, ist aber nicht der Hauptmotor. Entscheidend ist der Zeitversatz zwischen Unter- und Oberkante. „Lauter heißt höher.“ Lautstärke und Tonhöhe werden getrennt gesteuert (Atemdruck und Schluss gegen Spannung), auch wenn höherer Druck die Tonhöhe etwas mit anhebt. „Kinderstimmlippen sind kleine Erwachsenenstimmlippen.“ Sie sind kürzer und anders gebaut: Die Schichten fehlen beim Neugeborenen und reifen erst bis zur Pubertät. „Heiser = gelähmt.“ Heiserkeit bei normaler Beweglichkeit spricht für eine Störung des Covers (z. B. Knötchen) oder eine funktionelle Ursache, nicht für eine Nervenlähmung."},{"unit":"05","id":"h-zusammenfassung-in-fuenf-zeilen","title":"Zusammenfassung in fünf Zeilen","body":"Zusammenfassung in fünf Zeilen Muskeln stellen Schluss und Spannung ein; Luftdruck und Elastizität erzeugen die Schwingung (myoelastisch-aerodynamische Theorie). Unterkanten öffnen und schließen zuerst; die Randkantenverschiebung läuft von unten nach oben. Body (M. vocalis) und Cover (Epithel, Reinke-Raum); beim Neugeborenen noch ohne Schichten. Tonhöhe: vor allem Antikus (SLN). Lautstärke: Atemdruck und Schluss (RLN). Register: Gleichgewicht Antikus gegen Vokalis. Rekurrensparese = Spalt: kurze Tonhaltedauer, behaucht, leise. Ausfall R. externus = Höhe fehlt. Aus dem Gedächtnis zeichnen · 5 Minuten, leeres Blatt Zeichne fünf kleine Paare von Stimmlippen im Frontalschnitt nebeneinander und skizziere den Zyklus: zu, unten auf, offen, unten zu, zu. Zeichne darunter eine einzelne Stimmlippe und schraffiere drei Schichten: Cover, Übergang, Body. Beschrifte sie. Schreib daneben drei Pfeile: „Antikus → Tonhöhe“, „Schluss + Atemdruck → Lautstärke“, „Antikus ↔ Vokalis → Register“. Vergleiche mit Abb. 5.1–5.3. Was fehlt, kommt auf eine Lernkarte. Lösungen zu F1–F9 (erst nach eigenem Versuch öffnen) F1. Die Muskeln schließen die Stimmlippen und stellen ihre Spannung ein. Luftdruck öffnet sie, die Elastizität des Gewebes schließt sie wieder; so entsteht die Schwingung von selbst. F2. Die Unterkante öffnet und schließt zuerst; die Welle heißt Randkantenverschiebung (mukosale Welle). F3. Reinke-Raum → Cover; Lig. vocale → Übergang; M. vocalis → Body. F4. Rekurrensparese: Body (der M. vocalis wird schlaff). Stimmlippenknötchen: Cover. F5. Der M. cricothyroideus (Antikus), versorgt vom R. externus des N. laryngeus superior. F6. Vom subglottischen Druck (Atemdruck) und davon, wie lange und fest die Stimmlippen pro Zyklus geschlossen sind. F7. Bruststimme: Thyroarytänoid/Vokalis. Kopfstimme: Antikus. F8. Die linke Stimmlippe kommt nicht zur Mitte; durch den Spalt entweicht ständig Luft. Der subglottische Druck kann sich nicht aufbauen (Schritt 1 des Zyklus fehlt teilweise), deshalb wird sie nicht laut und verbraucht ihre Luft schnell. Der doppelte Klang entsteht, weil die schlaffe linke Stimmlippe mit einer anderen Frequenz schwingt als die gesunde rechte. F9. Nein, die Beweglichkeit ist normal. Betroffen ist das Cover; die Knötchen machen die Hülle steif und unregelmäßig, deshalb schwingen die Ränder unregelmäßig und die Stimme klingt rau. Weil die Muskeln normal schließen, bleibt nur ein kleiner Spalt, also weniger Behauchtheit als bei einer Lähmung."},{"unit":"05","id":"h-quellen","title":"Quellen","body":"Quellen van den Berg J. Myoelastic-aerodynamic theory of voice production. J Speech Hear Res 1958;1:227–244. Titze IR. The physics of small-amplitude oscillation of the vocal folds. J Acoust Soc Am 1988;83:1536–1552 (Zeitversatz zwischen Unter- und Oberkante als Energiequelle). Hirano M. Morphological structure of the vocal cord as a vibrator and its variations. Folia Phoniatr 1974;26:89–94 (Body-Cover-Modell). Übersichtsarbeit zur Entwicklung der Lamina propria im Kindesalter (zitiert Boseley & Hartnick 2006, Hirano et al. 1983, Ishii et al. 2000, Hartnick et al. 2005). PMC4011392. Wendler J, Seidner W, Eysholdt U. Lehrbuch der Phoniatrie und Pädaudiologie. 5. Aufl. Thieme; 2015 (Register, mittlere Sprechstimmlage, Stimmfeld, Tonhaltedauer). Nawka T. Objektive Messverfahren in der Stimmdiagnostik. Forum Logopädie 2006;20(4):14–21. Hartnick C et al. Indirect vs direct voice therapy for children with vocal nodules: a randomized clinical trial. JAMA Otolaryngol Head Neck Surg 2018;144(2):156–163 (Knötchen bei Kindern). DGPP. S2k-Leitlinie Diagnostik und Therapie von Störungen der Stimmfunktion (Dysphonien), AWMF 049-008, 2023."},{"unit":"06","id":null,"title":"Schutzfunktionen: Verschluss, Husten, Atmung und Schlucken","body":"Kernpfad · Abschnitt 6 von 10 Schutzfunktionen: Verschluss, Husten, Atmung und Schlucken ≈ 20 MinutenBaut auf: Abschnitte 2–5Weiter: Lähmungen im Überblick Nach diesem Abschnitt kannst du Die drei Verschlussebenen des Kehlkopfs in der richtigen Reihenfolge nennen. Den Kehlkopfanteil am Schluckablauf beschreiben und angeben, welche Schritte der N. vagus steuert. Die drei Phasen des Hustens mit den beteiligten Muskeln erklären. Vorhersagen, welches Schutzproblem bei welchem Nervenausfall entsteht, auch beim Säugling. Warum das für dich als Logopädin wichtig ist Stammesgeschichtlich ist der Kehlkopf zuerst ein Schutzventil für die Lunge und erst danach ein Stimmorgan. Bei einer Nervenlähmung ist darum oft nicht die Stimme das gefährlichste Problem, sondern das Verschlucken mit Lungenentzündung. Schluckdiagnostik und Schlucktherapie gehören in Deutschland zum logopädischen Arbeitsfeld; die Logik dafür beginnt hier."},{"unit":"06","id":"h-6-1-drei-verschlussebenen","title":"6.1 · Drei Verschlussebenen","body":"6.1 · Drei Verschlussebenen Der Kehlkopf kann sich auf drei Höhen verschließen, wie drei hintereinanderliegende Türen: Stimmlippen (unterste Ebene): geschlossen von Lateralis, Transversus und Thyroarytänoid, versorgt vom N. laryngeus recurrens. Taschenfalten (mittlere Ebene): legen sich bei kräftigem Verschluss aneinander. Kehlkopfeingang (oberste Ebene): Die aryepiglottischen Falten ziehen sich zusammen, die Stellknorpel kippen nach vorn zum Kehldeckelstiel, und der Kehldeckel (Epiglottis) legt sich über den Eingang. Beim Schlucken läuft der Verschluss im Wesentlichen von unten nach oben: Die Stimmlippen schließen früh, zuletzt senkt sich der Kehldeckel. Wie früh und wie fest die Stimmlippen schließen, passt der Körper an: Bei großen oder flüssigen Bissen schließen sie früher. Der Kehldeckel kippt übrigens größtenteils passiv: Er wird umgelegt, wenn der Kehlkopf nach oben vorn gezogen und der Zungengrund nach hinten gedrückt wird. Abb. 6.1 Dieselbe Frontalschnitt-Darstellung wie Abb. 2.2 und 4.2, von vorn (R und L der Patientin). Die Zahlen zeigen die Reihenfolge beim Schlucken: von unten nach oben. Abruf · ohne nachzusehen F1. Nenne die drei Verschlussebenen von unten nach oben. F2. Warum kippt der Kehldeckel größtenteils passiv?"},{"unit":"06","id":"h-6-2-schlucken-der-anteil-des-kehlkopfs","title":"6.2 · Schlucken: der Anteil des Kehlkopfs","body":"6.2 · Schlucken: der Anteil des Kehlkopfs Der Schluckablauf hat eine orale, eine pharyngeale (Rachen-) und eine ösophageale (Speiseröhren-) Phase. Der Kehlkopf ist vor allem in der pharyngealen Phase beteiligt, die in weniger als einer Sekunde abläuft und von einem Schluckzentrum im Hirnstamm gesteuert wird. Der N. vagus ist hier an mehreren Stellen beteiligt: Gaumensegel schließt den Nasenrachen ab, damit nichts in die Nase läuft (Rachenäste des N. vagus). Kehlkopf hebt sich nach oben vorn, gezogen von Muskeln oberhalb des Zungenbeins. Diese werden nicht vom N. vagus versorgt, sondern von N. trigeminus, N. facialis und N. hypoglossus bzw. Halsnerven. Kehlkopf schließt von unten nach oben (6.1): N. laryngeus recurrens. Atmung pausiert kurz (Schluckapnoe); danach wird meist ausgeatmet, was Reste vom Kehlkopfeingang wegbläst. Rachenmuskeln schieben den Bissen nach unten (Rachenäste des N. vagus). Oberer Speiseröhrenschließmuskel (M. cricopharyngeus) entspannt sich und wird durch die Kehlkopfhebung aufgezogen. Empfindung am Kehlkopfeingang meldet, ob etwas falsch läuft (R. internus des N. laryngeus superior). Abb. 6.2 Pharyngeale Phase, stark vereinfacht; einige Schritte überlappen zeitlich. Schild „N. X“ = Rachenäste des N. vagus; grau = ohne Beteiligung des N. vagus. Fett umrandet: der Kehlkopfverschluss, um den es in diesem Kurs geht. Kinder Beim Säugling steht der Kehlkopf hoch (bei Geburt etwa in Höhe des 3.–4. Halswirbels) und senkt sich bis zur Jugend ab. Der Kehldeckel liegt nahe am Gaumensegel, deshalb atmen Säuglinge beim Trinken durch die Nase und müssen Saugen, Schlucken und Atmen fein abstimmen. Eine Stimmlippenlähmung zeigt sich beim Säugling deshalb oft zuerst beim Trinken: Husten oder Verschlucken, lange Trinkzeiten, Atempausen, wiederkehrende Lungenentzündungen. Ein Teil dieser Kinder aspiriert still, also ohne zu husten. Abruf F3. Welche Schritte der pharyngealen Phase steuert der N. vagus, welcher Schritt gehört nicht zu ihm? F4. Warum ist das Ausatmen nach dem Schlucken ein Schutz? F5. Woran merkt man eine Stimmlippenlähmung beim Säugling oft zuerst?"},{"unit":"06","id":"h-6-3-husten-und-pressen","title":"6.3 · Husten und Pressen","body":"6.3 · Husten und Pressen Husten ist ein kontrollierter Luftstoß, der Material aus den Atemwegen schleudert. Er hat drei Phasen, und jede braucht andere Kehlkopfmuskeln: Einatmen: Die Stimmritze ist weit offen (Postikus), die Lunge füllt sich. Kompression: Die Stimmritze schließt fest (Lateralis, Transversus, Thyroarytänoid), die Ausatemmuskeln drücken, der Druck unter den Stimmlippen steigt stark an. Ausstoß: Die Stimmritze öffnet sich schlagartig, die Luft schießt heraus. Ohne festen Schluss in Phase 2 baut sich kein Druck auf: Der Husten wird schwach und „verhaucht“. Das gleiche Prinzip nutzt das Pressen (Heben, Stuhlgang, Geburt): Der Kehlkopf schließt, oft mit den Taschenfalten, damit der Brustkorb als feste Stütze dient. Abb. 6.3 Stimmritze von oben, vorne oben (wie Abb. 1.1). Ohne Phase 2 gibt es keinen kräftigen Husten. Atmung: Auch beim ruhigen Atmen ist der Kehlkopf aktiv. Bei jedem Einatmen weitet der Postikus die Stimmritze etwas, bei Anstrengung deutlich. Beim Ausatmen wird sie leicht enger und bremst den Luftstrom. Deshalb wird bei beidseitigem Ausfall der Postikusmuskeln gerade das Einatmen laut und eng (inspiratorischer Stridor). Abruf F6. Welche Hustenphase fällt bei einer einseitigen Rekurrensparese am stärksten aus, und warum? F7. Warum ist bei beidseitigem Postikusausfall vor allem das Einatmen betroffen?"},{"unit":"06","id":"h-6-4-welcher-ausfall-gefaehrdet-was","title":"6.4 · Welcher Ausfall gefährdet was?","body":"6.4 · Welcher Ausfall gefährdet was? Ausfall Schlucken Husten Atmung R. internus SLN Stille Aspiration: Material im Kehlkopfeingang wird nicht bemerkt Reflexhusten fehlt oder kommt zu spät; willkürlicher Husten möglich Normal N. recurrens, eine Seite RLN Unvollständiger Verschluss: Verschlucken vor allem bei dünnen Flüssigkeiten Schwach, weil sich kein Druck aufbaut Meist ausreichend N. recurrens, beide Seiten RLN Oft weniger gestört als die Atmung Kann erhalten sein Eng: inspiratorischer Stridor, Atemnot bei Belastung und Infekten Hohe Vagusläsion (oberhalb des N. laryngeus superior) N. X Alles zusammen: Verschluss und Empfindung fehlen, Rachen schiebt schwach, Reste im Recessus piriformis, Flüssigkeit in die Nase Schwach und verspätet Meist ausreichend (eine Seite) In der Schluckdiagnostik wird das Eindringen von Material oft mit der Penetrations-Aspirations-Skala (Rosenbek et al. 1996) beschrieben: Penetration heißt, Material gelangt in den Kehlkopfeingang, bleibt aber oberhalb der Stimmlippen; Aspiration heißt, es gelangt unter die Stimmlippen. Die Skala unterscheidet außerdem, ob das Material wieder herausbefördert wird. ! Warnzeichen für Aspiration Husten oder Räuspern während oder kurz nach dem Schlucken „Nasse“, gurgelnde Stimme nach dem Schlucken Wiederkehrende Lungenentzündungen oder unklares Fieber Beim Säugling: Atempausen, Verfärbung oder Husten beim Trinken, sehr lange Trinkzeiten Fehlt der Husten, schließt das Aspiration nicht aus. Bei Verdacht ist eine instrumentelle Schluckdiagnostik (FEES oder Videofluoroskopie) nötig."},{"unit":"06","id":"h-6-5-zwei-mini-faelle","title":"6.5 · Zwei Mini-Fälle","body":"6.5 · Zwei Mini-Fälle Erwachsene · Frau R., 60, nach Operation am linken Lungenoberlappen Seit der Operation ist Frau R. heiser. Beim Wassertrinken hustet sie oft, aber der Husten ist schwach und „verhaucht“. Joghurt schluckt sie problemlos. Die linke Stimmlippe steht still. F8. Welcher Nerv? Warum gerade dünne Flüssigkeiten, und warum ist ihr Husten schwach? Warum hustet sie überhaupt, statt still zu aspirieren? Kind · Mia, jetzt 4 Monate (aus Abschnitt 3) Mia hat eine linksseitige Rekurrensparese nach dem Verschluss des Ductus arteriosus. Sie trinkt sehr langsam, hustet beim Fläschchen, und hatte schon eine Lungenentzündung. F9. Welcher Teil des Schutzes fehlt Mia? Warum ist das bei einem Säugling, der nur Flüssigkeit trinkt, besonders problematisch, und wer sollte an der Abklärung beteiligt sein? Häufige Fehlvorstellungen „Der Kehldeckel ist der wichtigste Schutz.“ Der Hauptschutz ist der Verschluss der Stimmlippen und des Kehlkopfeingangs. Menschen ohne Kehldeckel (z. B. nach Teilentfernung) können oft sicher schlucken lernen. „Wer hustet, aspiriert; wer nicht hustet, ist sicher.“ Husten zeigt, dass der Schutz arbeitet. Gefährlicher ist die stille Aspiration ohne Husten. „Der N. vagus hebt den Kehlkopf beim Schlucken.“ Die Hebung leisten die Muskeln oberhalb des Zungenbeins mit anderen Hirnnerven. Der N. vagus schließt, schiebt, öffnet die Speiseröhre und fühlt. „Bei beidseitiger Rekurrensparese ist das Schlucken das Hauptproblem.“ Das Hauptproblem ist die Atmung. „Breiige Kost ist bei Verschlucken immer sicherer.“ Bei schwachem Verschluss helfen dickere Konsistenzen oft, bei schwacher Rachenmuskulatur können sie aber mehr Reste hinterlassen. Das muss in der Diagnostik geprüft werden."},{"unit":"06","id":"h-zusammenfassung-in-fuenf-zeilen","title":"Zusammenfassung in fünf Zeilen","body":"Zusammenfassung in fünf Zeilen Drei Verschlussebenen: Stimmlippen, Taschenfalten, Kehlkopfeingang; beim Schlucken von unten nach oben. Der N. vagus schließt das Gaumensegel, den Kehlkopf, schiebt den Rachen, öffnet die Speiseröhre und überwacht den Kehlkopfeingang; die Kehlkopfhebung gehört zu anderen Nerven. Husten: einatmen (Postikus), komprimieren (Schließer), ausstoßen. Ohne Schluss kein kräftiger Husten. R. internus aus = stille Aspiration; Rekurrens einseitig = Verschlucken bei Flüssigkeit und schwacher Husten; beidseitig = Atemnot. Beim Säugling zeigt sich eine Stimmlippenlähmung oft zuerst beim Trinken. Aus dem Gedächtnis zeichnen · 5 Minuten, leeres Blatt Zeichne den Frontalschnitt des Kehlkopfs mit Stimmlippen und Taschenfalten und markiere die drei Verschlussebenen mit 1, 2, 3 von unten nach oben. Zeichne daneben drei kleine Stimmritzen von oben für die drei Hustenphasen und schreib die Muskeln dazu. Schreib eine Zeile mit den Schritten der pharyngealen Phase und markiere, welche der N. vagus steuert. Vergleiche mit Abb. 6.1–6.3. Was fehlt, kommt auf eine Lernkarte. Lösungen zu F1–F9 (erst nach eigenem Versuch öffnen) F1. Stimmlippen, Taschenfalten, Kehlkopfeingang (aryepiglottische Falten, Stellknorpel, Kehldeckel). F2. Er wird umgelegt, wenn der Kehlkopf nach oben vorn gezogen wird und der Zungengrund nach hinten drückt. F3. N. vagus: Gaumensegelschluss, Kehlkopfverschluss, Rachenmuskeln, Öffnung des oberen Speiseröhrenschließmuskels, Empfindung am Kehlkopfeingang. Nicht: die Kehlkopfhebung (Muskeln oberhalb des Zungenbeins, andere Hirnnerven). F4. Die ausgeatmete Luft bläst Reste, die am Kehlkopfeingang liegen, nach oben weg, statt sie mit dem nächsten Atemzug in die Luftröhre zu ziehen. F5. Beim Trinken: Husten oder Verschlucken, lange Trinkzeiten, Atempausen, wiederkehrende Lungenentzündungen. F6. Die Kompressionsphase: Ohne festen Schluss baut sich kein Druck unter den Stimmlippen auf. F7. Beim Einatmen muss der Postikus die Stimmritze aktiv weiten; beim Ausatmen drückt die Luft die Stimmlippen von unten etwas auseinander. F8. Linker N. laryngeus recurrens (Operation in der Nähe des Aortenbogens). Dünne Flüssigkeiten fließen schnell und finden den Spalt der unvollständig schließenden Stimmritze; Joghurt fließt langsamer. Der Husten ist schwach, weil ohne Schluss kein Druck entsteht. Sie hustet, weil der R. internus des N. laryngeus superior intakt ist und die Empfindung oberhalb der Stimmlippen funktioniert. F9. Der vollständige Verschluss der Stimmritze auf der linken Seite. Säuglinge trinken nur dünne Flüssigkeit, also genau die Konsistenz, die am leichtesten durch den Spalt läuft, und sie trinken viele Male am Tag. An der Abklärung beteiligt sind Kinderärztin bzw. Kinder-HNO oder Phoniatrie, Logopädin mit Schwerpunkt Schlucken und gegebenenfalls Ernährungsberatung; die instrumentelle Diagnostik entscheidet über Maßnahmen wie angedickte Nahrung oder Haltung."},{"unit":"06","id":"h-quellen","title":"Quellen","body":"Quellen Bartolome G, Schröter-Morasch H (Hrsg.). Schluckstörungen: Interdisziplinäre Diagnostik und Rehabilitation. Elsevier/Urban & Fischer, aktuelle Auflage (Schluckablauf, Verschlussebenen, Diagnostik). Inamoto Y, González-Fernández M, Saito E. Timing of true vocal cords closure for safe swallowing: a review. Dysphagia 2024;39(3):313–320. Abstract (Stimmlippenschluss passt sich Bolusgröße und Konsistenz an). Rosenbek JC, Robbins JA, Roecker EB, Coyle JL, Wood JL. A penetration-aspiration scale. Dysphagia 1996;11:93–98. Schünke M, Schulte E, Schumacher U. PROMETHEUS LernAtlas: Kopf, Hals und Neuroanatomie. 6. Aufl. Thieme; 2022 (Innervation von Gaumen, Rachen und Kehlkopf). OpenAnesthesia. Pediatric airway management (Kehlkopf bei Geburt in Höhe C3–C4, Absenkung bis zur Jugend). Lechien JR. Management of pediatric bilateral vocal fold paralysis. Children 2024;11(4):398. doi:10.3390/children11040398. DGPP. S2k-Leitlinie Diagnostik und Therapie von Störungen der Stimmfunktion (Dysphonien), AWMF 049-008, 2023."},{"unit":"07","id":null,"title":"Kehlkopflähmungen im Überblick","body":"Kernpfad · Abschnitt 7 von 10 Kehlkopflähmungen im Überblick ≈ 20–25 MinutenBaut auf: Abschnitte 1–6Weiter: Abgrenzung und Warnzeichen Nach diesem Abschnitt kannst du Für einseitige und beidseitige Rekurrensparese, Lähmung des N. laryngeus superior und hohe Vagusläsion den Mechanismus, das Laryngoskopiebild, den Stimmklang und die Folgen für Atmung und Schlucken beschreiben. Aus einer Kombination von Zeichen die Höhe der Läsion bestimmen. Die Rolle der Logopädin bei jeder Lähmung in groben Zügen beschreiben. Besonderheiten bei Kindern nennen. Warum das für dich als Logopädin wichtig ist Jetzt zahlt sich die Karte aus Abschnitt 4 aus. Du musst keine vier Krankheitsbilder auswendig lernen: Jede Lähmung ist eine Läsion an einer bestimmten Stelle der Karte, und ihre Zeichen ergeben sich aus dem, was dahinter ausfällt. Patientinnen mit Rekurrensparese gehören zu den häufigsten neurogenen Stimmpatientinnen in der logopädischen Praxis, und die Stimmtherapie beginnt idealerweise früh."},{"unit":"07","id":"h-7-1-wo-steht-die-gelaehmte-stimmlippe","title":"7.1 · Wo steht die gelähmte Stimmlippe?","body":"7.1 · Wo steht die gelähmte Stimmlippe? Im HNO-Befund wird die Position einer unbeweglichen Stimmlippe mit traditionellen Begriffen beschrieben, von innen nach außen: Median: in der Mitte, wie beim Sprechen. Paramedian: knapp neben der Mitte. Intermediär: zwischen Mitte und Atemstellung. Lateral: weit außen; früher „Kadaverstellung“ genannt. Früher hat man aus der Position auf den Läsionsort geschlossen. Das gilt heute als unzuverlässig: Die Position hängt auch davon ab, ob der Antikus noch zieht, ob Fasern teilweise nachgewachsen sind (oft in falsche Muskeln, sogenannte Synkinesie) und wie stark der Muskel geschwunden ist. Beschreibe, was du siehst, statt daraus den Ort abzuleiten. Abb. 7.1 Stimmritze von oben, vorne oben, L und R der Patientin (wie Abb. 1.1). Graue Linien = mögliche Positionen der gelähmten Stimmlippe; rotbraun = gesunde Seite in Mittelstellung. Die Begriffe sind traditionell und werden nicht überall gleich verwendet. Abruf · ohne nachzusehen F1. Nenne die vier Positionsbegriffe von innen nach außen. F2. Warum kann man aus der Position nicht sicher auf den Läsionsort schließen? Zwei Gründe."},{"unit":"07","id":"h-7-2-einseitige-rekurrensparese","title":"7.2 · Einseitige Rekurrensparese","body":"7.2 · Einseitige Rekurrensparese Mechanismus: Auf einer Seite fallen Postikus, Lateralis, Transversus und Thyroarytänoid aus (Abschnitt 4). Die Stimmlippe bewegt sich nicht und schließt nicht vollständig; der Antikus und die Empfindung oberhalb bleiben. Laryngoskopie und Stroboskopie: Unbewegliche Stimmlippe, meist paramedian oder intermediär. Beim Phonieren bleibt ein Spalt; die gesunde Seite kann über die Mitte hinaus ausgleichen. Der Proc. vocalis der gelähmten Seite steht manchmal tiefer, die Stimmlippe wird mit der Zeit dünner und durchgebogen. In der Stroboskopie schwingen beide Seiten ungleich, die gelähmte schlaff mit großer Amplitude. Stimme: Typisch behaucht und heiser, im RBH-System oft B2–3 und H2–3, R wechselnd; leise, schnell ermüdend, kurze Tonhaltedauer, manchmal doppeltönig. Steht die Stimmlippe nahe der Mitte, kann die Stimme fast normal sein. Viele Betroffene pressen zum Ausgleich, bis hin zur Taschenfaltenstimme. Atmung und Schlucken: Die Atmung reicht meist aus. Beim Trinken dünner Flüssigkeiten Verschlucken, Husten schwach. Ursachen: bei Erwachsenen vor allem Operationen (Schilddrüse, Halswirbelsäule, Brustkorb, Herz), Tumoren entlang des Nervs, unklare („idiopathische“, oft nach Virusinfekt) Lähmungen und Intubation. Nach Schilddrüsenoperationen haben laut US-Leitlinie etwa 1 von 10 Patienten vorübergehende Probleme durch Nervenschäden, bis zu 1 von 25 länger anhaltende. Verlauf: Viele Lähmungen erholen sich. In einer Studie zu idiopathischen Lähmungen erholte sich die Stimme bei 69 %, zwei Drittel davon in den ersten 6 Monaten; die Beweglichkeit kehrte deutlich seltener zurück. Die Stimme kann also wieder gut werden, obwohl die Stimmlippe stillsteht, weil die Stellung und die Muskelspannung sich verbessern und die Gegenseite ausgleicht. Behandlung und Rolle der Logopädin: Frühe Stimmtherapie mit dem Ziel eines besseren Schlusses ohne Pressen, guter Atem-Stimm-Koordination und Ausdauer; dazu Schluckberatung bzw. -therapie. Ärztlich kommen eine vorübergehende Injektion in die Stimmlippe (Augmentation), später eine dauerhafte Verschiebung zur Mitte (Thyreoplastik) oder eine Nervenumleitung (Reinnervation) infrage; dauerhafte Eingriffe meist erst nach 6–12 Monaten. Die Logopädin dokumentiert vorher und nachher und betreut weiter. Die Studienlage zur Stimmtherapie ist positiv, aber von niedriger Evidenzstufe. Abb. 7.2 Stimmritze von oben, vorne oben (wie Abb. 1.1). Magenta = gelähmte Stimmlippe, zusätzlich mit „gelähmt“ beschriftet; rotbraun = beweglich. Schematisch. Abruf F3. Welche Muskeln fallen bei einer einseitigen Rekurrensparese aus, welche Funktionen bleiben? F4. Warum kann sich die Stimme erholen, obwohl die Stimmlippe stillsteht? F5. Was ist das Ziel der Stimmtherapie, und welcher Ausgleich soll vermieden werden?"},{"unit":"07","id":"h-7-3-beidseitige-rekurrensparese","title":"7.3 · Beidseitige Rekurrensparese","body":"7.3 · Beidseitige Rekurrensparese Mechanismus: Beide Postikusmuskeln fallen aus, also kann niemand die Stimmritze öffnen. Beide Stimmlippen stehen meist paramedian. Leitsymptom ist die Atmung: Einatmen mit Geräusch (inspiratorischer Stridor), Atemnot bei Anstrengung, im Schlaf und bei Infekten. Das kann ein Notfall sein. Die Stimme ist dagegen oft erstaunlich gut, weil die Stimmlippen nahe beieinander stehen. Das ist die klassische Prüfungsfalle: gute Stimme, gefährliche Atmung. Ursachen: Operationen an beiden Seiten der Schilddrüse, neurologische Erkrankungen, Intubation. Ähnlich aussehen kann eine Narbe hinten zwischen den Stellknorpeln oder ein festgewachsenes Stellknorpelgelenk; das ist mechanisch, nicht nerval, und wird anders behandelt (Abschnitt 8). Behandlung: Zuerst den Atemweg sichern. Möglichkeiten sind ein Luftröhrenschnitt (Tracheotomie) oder eine operative Erweiterung der Stimmritze (z. B. teilweise Entfernung eines Stellknorpels, Einkerbung einer Stimmlippe oder Laterofixation, bei der eine Stimmlippe nach außen genäht wird). Jede Erweiterung verbessert die Atmung und verschlechtert die Stimme, manchmal auch den Schluss beim Schlucken. Die Logopädin übt mit Sprechkanülen bzw. Sprechventilen, begleitet Stimme und Schlucken und berät. Kinder Bei Neugeborenen ist die beidseitige Lähmung eine wichtige Ursache für Stridor. Häufige Gründe sind Fehlbildungen und Erkrankungen des Gehirns wie die Chiari-Malformation mit erhöhtem Hirndruck, Geburtsverletzungen oder keine erkennbare Ursache. Viele Kinder brauchen vorübergehend eine Tracheotomie. Weil sich ein großer Teil spontan bessert (Übersichtsarbeiten nennen etwa 48–70 %), wartet man bei Kindern oft länger als bei Erwachsenen, bevor man dauerhaft operiert; nach mehr als einem Jahr wird eine Erholung seltener. Abruf F6. Warum ist bei beidseitiger Rekurrensparese die Atmung gefährdet, die Stimme aber oft gut? F7. Welcher Zielkonflikt besteht bei allen Operationen, die die Stimmritze erweitern?"},{"unit":"07","id":"h-7-4-laehmung-des-n-laryngeus-superior-kurzfassung","title":"7.4 · Lähmung des N. laryngeus superior (Kurzfassung)","body":"7.4 · Lähmung des N. laryngeus superior (Kurzfassung) Das kennst du aus Abschnitt 2. R. externus: Bewegung normal, Laryngoskopie fast unauffällig, aber hohe Töne, Stimmumfang, Tragfähigkeit und Ausdauer fehlen; Nachweis über Stimmfeld, Glissando und Larynx-EMG. R. internus: Stimme normal, aber Empfindung oberhalb der Stimmlippen fehlt, Gefahr der stillen Aspiration. Typische Ursache ist die Schilddrüsenoperation am oberen Pol."},{"unit":"07","id":"h-7-5-hohe-vaguslaesion-und-die-frage-wie-hoch","title":"7.5 · Hohe Vagusläsion und die Frage „Wie hoch?“","body":"7.5 · Hohe Vagusläsion und die Frage „Wie hoch?“ Liegt die Schädigung oberhalb des Abgangs des N. laryngeus superior, also an der Schädelbasis, am Foramen jugulare oder im Hirnstamm selbst, fallen alle Äste gleichzeitig aus: N. laryngeus recurrens, N. laryngeus superior und die Rachenäste. Dazu kommen Zeichen, die bei einer reinen Rekurrensparese fehlen: Gaumensegel hebt sich auf der kranken Seite nicht; das Zäpfchen weicht zur gesunden Seite ab. Kulissenphänomen: Beim „a“-Sagen oder Würgen verschiebt sich die hintere Rachenwand zur gesunden Seite, wie ein Theatervorhang. Näselnde Stimme (offenes Näseln) und Flüssigkeit, die in die Nase läuft. Empfindung oberhalb der Stimmlippen fehlt; Speichel sammelt sich im Recessus piriformis. Das Schlucken ist dabei meist deutlich schwerer gestört als bei einer reinen Rekurrensparese. Ursachen sind Tumoren der Schädelbasis, Verletzungen oder ein Schlaganfall im seitlichen Hirnstamm (Wallenberg-Syndrom), bei dem der Nucleus ambiguus mitbetroffen ist. Ein einseitiger Schlaganfall in der Großhirnrinde lähmt die Stimmlippe dagegen fast nie: Die Kerngebiete für den Kehlkopf werden von beiden Hirnhälften angesteuert. Abb. 7.3 Die Läsionsleiter. Gelb: N. vagus; türkis: Abgang des N. laryngeus superior; violett: Verlauf des N. laryngeus recurrens. Liest man von unten nach oben, kommen mit jeder Stufe Zeichen hinzu. Abruf F8. Zu welcher Seite weicht das Zäpfchen bei einer hohen Vagusläsion ab? F9. Nenne drei Zeichen, die für eine hohe Vagusläsion sprechen und bei einer reinen Rekurrensparese fehlen. F10. Warum lähmt ein einseitiger Großhirninfarkt die Stimmlippe fast nie?"},{"unit":"07","id":"h-7-6-alles-auf-einen-blick","title":"7.6 · Alles auf einen Blick","body":"7.6 · Alles auf einen Blick Rekurrens einseitig RLN Rekurrens beidseitig RLN N. lar. superior SLN Hohe Vagusläsion N. X Beweglichkeit eine Seite steht beide stehen, meist paramedian normal eine Seite steht Stimme behaucht, leise, kurze Tonhaltedauer oft fast normal Höhe, Umfang, Tragfähigkeit ↓ behaucht + näselnd Atmung meist gut Stridor, Atemnot normal meist gut Schlucken Flüssigkeiten, schwacher Husten weniger betroffen internus: stille Aspiration schwer: Reste, Nase, stille Aspiration Weitere Zeichen – – – Gaumensegel, Zäpfchen, Kulissenphänomen Typische Ursachen OP, Tumor, idiopathisch, Intubation OP beidseits, neurologisch Schilddrüsen-OP (oberer Pol) Schädelbasis, Hirnstamm Logopädie Stimmtherapie früh, Schlucken Sprechventil, Stimme, Schlucken, Beratung Umfang, Resonanz; Schlucken vor allem Schlucktherapie"},{"unit":"07","id":"h-7-7-zwei-mini-faelle","title":"7.7 · Zwei Mini-Fälle","body":"7.7 · Zwei Mini-Fälle Erwachsene · Frau D., 45, Lehrerin Nach einer Erkältung ist Frau D. seit drei Wochen heiser und behaucht. Sie hatte keine Operation. Die linke Stimmlippe steht paramedian, Gaumensegel und Rachen sind unauffällig. Die Bildgebung vom Schädel bis zum Brustkorb ist unauffällig. F11. Welche Lähmung, auf welcher Höhe? Was sagst du ihr zur Prognose, und wann sollte die Stimmtherapie beginnen? Kind · Paul, jetzt 7 Monate (aus Abschnitt 4) Paul hat eine beidseitige Stimmlippenlähmung bei Chiari-Malformation. Er hatte zweimal Atemnot bei Infekten und hat jetzt eine Tracheotomie. F12. Warum hat man zuerst den Atemweg gesichert und nicht die Stimmritze dauerhaft erweitert? Was kann die Logopädin jetzt für Paul tun? Häufige Fehlvorstellungen „An der Position erkenne ich den Läsionsort“ (z. B. nach dem Semonschen Gesetz). Historisch, heute als unzuverlässig angesehen. „Gute Stimme heißt harmlos.“ Bei beidseitiger Rekurrensparese ist die Stimme oft gut und die Atmung gefährdet. „Eine Rekurrensparese ist immer dauerhaft.“ Viele erholen sich in den ersten Monaten, die Stimme öfter als die Beweglichkeit. „Stimmtherapie lohnt sich erst, wenn klar ist, dass es dauerhaft ist.“ Leitlinien und Studien sprechen für einen frühen Beginn, auch um Pressen als Ausgleich zu verhindern. „Das Zäpfchen zeigt zur kranken Seite.“ Es wird von der gesunden Seite hinübergezogen und zeigt deshalb zur gesunden."},{"unit":"07","id":"h-zusammenfassung-in-fuenf-zeilen","title":"Zusammenfassung in fünf Zeilen","body":"Zusammenfassung in fünf Zeilen Die Position einer gelähmten Stimmlippe beschreiben, nicht zur Ortung nutzen. Einseitige Rekurrensparese: Spalt, behaucht, kurze Tonhaltedauer, Verschlucken bei Flüssigkeiten; frühe Stimmtherapie; oft Erholung der Stimme. Beidseitige Rekurrensparese: Stridor und Atemnot bei oft guter Stimme; Atemweg zuerst. N. laryngeus superior: Höhe fehlt (externus) oder stille Aspiration (internus). Hohe Vagusläsion: zusätzlich Gaumensegel, Zäpfchen zur gesunden Seite, Kulissenphänomen, schwere Schluckstörung. Aus dem Gedächtnis zeichnen · 5 Minuten, leeres Blatt Zeichne eine senkrechte gelbe Linie (N. vagus) mit vier Stufen: Hirnstamm, Schädelbasis, Abgang N. laryngeus superior, Verlauf N. laryngeus recurrens. Schreib an jede Stufe, welche Zeichen bei einer Läsion dort auftreten. Zeichne daneben drei Stimmritzen von oben: normal, einseitig gelähmt, beidseitig gelähmt beim Einatmen. Markiere die gelähmten Seiten. Vergleiche mit Abb. 7.2 und 7.3. Was fehlt, kommt auf eine Lernkarte. Lösungen zu F1–F12 (erst nach eigenem Versuch öffnen) F1. Median, paramedian, intermediär, lateral. F2. Zum Beispiel: Ein noch arbeitender Antikus zieht die Stimmlippe zur Mitte; nachgewachsene Fasern können in falsche Muskeln laufen (Synkinesie); der Muskel schwindet mit der Zeit. F3. Aus: Postikus, Lateralis, Transversus, Thyroarytänoid auf dieser Seite. Bleiben: Antikus (N. laryngeus superior) und die Empfindung oberhalb der Stimmlippen. F4. Die Stellung und Spannung der gelähmten Stimmlippe können sich verbessern, und die gesunde Seite gleicht aus, indem sie über die Mitte geht. F5. Ein möglichst guter Schluss mit guter Atem-Stimm-Koordination und Ausdauer, ohne Pressen bzw. Taschenfaltenstimme als Ausgleich. F6. Beide Öffner fallen aus, die Stimmlippen stehen nahe der Mitte: zu eng zum Einatmen, aber nah genug zum Schwingen. F7. Mehr Luft bedeutet schlechtere Stimme und manchmal schlechteren Schutz beim Schlucken. F8. Zur gesunden Seite. F9. Zum Beispiel: Gaumensegel hebt sich einseitig nicht, Zäpfchen weicht ab, Kulissenphänomen, offenes Näseln, Flüssigkeit in der Nase, fehlende Empfindung oberhalb der Stimmlippen, Speichelsee im Recessus piriformis. F10. Die Kerngebiete für die Kehlkopfmuskeln werden von beiden Großhirnhälften angesteuert; fällt eine aus, übernimmt die andere weitgehend. F11. Einseitige Rekurrensparese links, wahrscheinlich idiopathisch (Gaumen und Rachen unauffällig, also keine hohe Läsion; Bildgebung unauffällig). Prognose: gute Chance, dass sich die Stimme erholt, meist in den ersten Monaten; die Beweglichkeit kehrt seltener zurück. Stimmtherapie früh beginnen, jetzt. F12. Bei Kindern bessert sich eine beidseitige Lähmung oft spontan, und eine dauerhafte Erweiterung würde Stimme und Schluckschutz bleibend verschlechtern; deshalb erst sichern und abwarten. Die Logopädin kann mit Sprechventil an Stimme und Lautentwicklung arbeiten, das Trinken und Schlucken begleiten und die Eltern beraten."},{"unit":"07","id":"h-quellen","title":"Quellen","body":"Quellen DGPP. S2k-Leitlinie Diagnostik und Therapie von Störungen der Stimmfunktion (Dysphonien), AWMF 049-008, Version 4.0, 2023. AWMF-Register. Chandrasekhar SS et al. Clinical Practice Guideline: Improving Voice Outcomes after Thyroid Surgery. Otolaryngol Head Neck Surg 2013;148(6 Suppl):S1–S37. doi:10.1177/0194599813487301. Husain S, Sadoughi B, Mor N, Levin AM, Sulica L. Time course of recovery of idiopathic vocal fold paralysis. Laryngoscope 2018;128(1):148–152. doi:10.1002/lary.26762. Walton C et al. Unilateral vocal fold paralysis: a systematic review of speech-language pathology management. J Voice 2017;31(4):509.e7–509.e22. doi:10.1016/j.jvoice.2016.11.002. Vila PM, Bhatt NK, Paniello RC. Early-injection laryngoplasty may lower risk of thyroplasty. Laryngoscope 2018;128(4):935–940. doi:10.1002/lary.26894. Lechien JR. Management of pediatric bilateral vocal fold paralysis. Children 2024;11(4):398. doi:10.3390/children11040398. Wendler J, Seidner W, Eysholdt U. Lehrbuch der Phoniatrie und Pädaudiologie. 5. Aufl. Thieme; 2015 (Positionsbegriffe, Kulissenphänomen, Wallenberg-Syndrom). Orestes MI, Chhetri DK. Superior laryngeal nerve injury. Curr Opin Otolaryngol Head Neck Surg 2014. doi:10.1097/MOO.0000000000000097."},{"unit":"08","id":null,"title":"Abgrenzung: Was sieht aus wie eine Lähmung, ist aber keine?","body":"Kernpfad · Abschnitt 8 von 10 Abgrenzung: Was sieht aus wie eine Lähmung, ist aber keine? ≈ 20–25 MinutenBaut auf: Abschnitte 1–7Weiter: gemischte Wiederholung Nach diesem Abschnitt kannst du Mit drei Fragen (Beweglichkeit, Schluss, Schleimhaut) eine Nervenlähmung von ähnlichen Bildern trennen. Mechanische Ursachen einer unbeweglichen Stimmlippe nennen und erklären, wie man sie von einer Lähmung unterscheidet. Stimmlippenknötchen, funktionelle Dysphonie und spasmodische Dysphonie von einer Lähmung abgrenzen, besonders bei Kindern. Die Warnzeichen für eine sofortige HNO- bzw. phoniatrische Abklärung aufzählen. Warum das für dich als Logopädin wichtig ist Bei Kindern ist Heiserkeit viel häufiger durch Knötchen oder Stimmgebrauch bedingt als durch eine Nervenlähmung. Du musst aber erkennen, wann etwas nicht ins Bild passt. In Deutschland gilt: keine Stimmtherapie ohne vorherige laryngoskopische Diagnose. Deine Aufgabe ist nicht, selbst zu diagnostizieren, sondern Befunde zu verstehen, Widersprüche zu bemerken und Warnzeichen sofort weiterzuleiten."},{"unit":"08","id":"h-8-1-drei-fragen-ein-entscheidungsbaum","title":"8.1 · Drei Fragen, ein Entscheidungsbaum","body":"8.1 · Drei Fragen, ein Entscheidungsbaum Fast jede Abgrenzung beginnt mit derselben Frage: Bewegt sich die Stimmlippe? Wenn nein, ist es eine Nervenlähmung oder ein mechanisches Hindernis. Wenn ja, ist es keine Lähmung der Hauptmuskeln; dann fragt man, wie der Schluss aussieht und ob an der Schleimhaut etwas sichtbar ist. Abb. 8.1 Raute = Frage, Rechteck = Befund bzw. Diagnosegruppe, abgerundet = Ausgangssituation, rot umrandet mit „!“ = Warnzeichen. EMG = Elektromyographie des Kehlkopfs, die die elektrische Muskelaktivität misst. Abruf · ohne nachzusehen F1. Was ist die erste Frage bei jeder Heiserkeit mit Laryngoskopiebefund? F2. Welche Untersuchung trennt eine Nervenlähmung von einer mechanischen Fixierung, und was zeigt sie jeweils?"},{"unit":"08","id":"h-8-2-unbeweglich-aber-nicht-gelaehmt","title":"8.2 · Unbeweglich, aber nicht gelähmt","body":"8.2 · Unbeweglich, aber nicht gelähmt Eine Stimmlippe kann stillstehen, obwohl der Nerv intakt ist, weil das Gelenk oder die Umgebung sie festhält: Aryknorpelluxation: Der Stellknorpel springt bei einer Intubation oder Verletzung aus seinem Gelenk. Stimme behaucht wie bei einer Lähmung; der Stellknorpel steht oft sichtbar verschoben. Wichtig, weil eine frühe Reposition helfen kann. Fixierung des Krikoarytänoidgelenks, z. B. bei rheumatoider Arthritis: Das Gelenk ist entzündet oder versteift. Hintere Glottisstenose: eine Narbe zwischen den Stellknorpeln, oft nach langer Intubation. Beidseits sieht das aus wie eine beidseitige Rekurrensparese mit Stridor. Tumor, der in Muskel oder Gelenk wächst. So unterscheidet man: Das Larynx-EMG ist bei mechanischer Fixierung normal, bei Lähmung gestört. In Narkose kann die Ärztin den Stellknorpel mit einem Instrument bewegen: Ist er frei beweglich, spricht das für eine Lähmung; ist er fest, für ein mechanisches Hindernis. Die Unterscheidung ändert die Behandlung grundlegend. Abruf F3. Nenne drei mechanische Ursachen einer unbeweglichen Stimmlippe. F4. Ein Patient ist nach einer langen Intensivbehandlung mit Intubation heiser, eine Stimmlippe steht still. Warum muss man an eine Aryknorpelluxation denken, und warum ist das eilig?"},{"unit":"08","id":"h-8-3-beweglich-aber-auffaellig-schlussmuster-und-schleimhaut","title":"8.3 · Beweglich, aber auffällig: Schlussmuster und Schleimhaut","body":"8.3 · Beweglich, aber auffällig: Schlussmuster und Schleimhaut Bewegen sich beide Stimmlippen, verrät die Form des Spalts beim Phonieren viel. Diese Schlussmuster sind beschreibend, sie sagen nicht automatisch etwas über den Nerv: Abb. 8.2 Stimmritze von oben, vorne oben (wie Abb. 1.1). Magenta = unbewegliche Stimmlippe. Nur der einseitige Spalt mit unbeweglicher Seite spricht für eine Lähmung oder Fixierung; alle anderen Muster entstehen bei beweglichen Stimmlippen. Bild Beweglichkeit Schluss, Stroboskopie Typischer Klang Unterscheidet sich durch Einseitige Rekurrensparese eine Seite steht Spalt, ungleiche Schwingung, Höhenunterschied B↑ H↑, leise unbewegliche Stimmlippe; Verschlucken bei Flüssigkeit Beidseitige Rekurrensparese beide eingeschränkt enge Stimmritze fast normal; Stridor Atmung steht im Vordergrund Lähmung R. externus normal evtl. leichte Asymmetrie leicht; Höhe fehlt versagt beim Glissando nach oben; EMG Stimmlippenknötchen normal Sanduhr, steifes Cover R↑, B leicht beidseitig, symmetrisch, am vorderen-mittleren Drittel Polyp, Zyste normal einseitiger Befund R↑, doppeltönig möglich sichtbare Raumforderung Aryknorpelluxation, Gelenkfixierung eingeschränkt Spalt, Stellknorpel verschoben B↑ Intubation, Rheuma; EMG normal Hyperfunktionelle Dysphonie normal Pressen, Taschenfalten drücken mit gepresst, R wechselnd normale Anatomie; Stimmgebrauch Hypofunktionelle Dysphonie normal ovaler oder hinterer Spalt B↑, kraftlos Ermüdung; normale Beweglichkeit Spasmodische Dysphonie (Adduktortyp) in Ruhe normal aufgabenabhängige Verkrampfungen gepresst, abgehackt, „erwürgt“ besser beim Singen, Lachen, Flüstern; zentrale Ursache Presbyphonie normal durchgebogene Stimmlippen, Spindelspalt B, kraftlos, Tonhöhe verändert Alter, beidseitig Larynxpapillomatose (Kind) anfangs normal warzenartige Wucherungen R, H, später Stridor zunehmend; HPV 6/11 Die spasmodische Dysphonie ist eine fokale Dystonie, also eine Bewegungsstörung des Gehirns, die nur bestimmte Bewegungen betrifft, hier das Sprechen. Sie hat nichts mit einer Schädigung des N. vagus zu tun, obwohl die Stimme ebenfalls auffällig ist; sie wird meist mit Botulinumtoxin-Injektionen behandelt. Abruf F5. Welches Schlussmuster spricht für eine Lähmung oder Fixierung, welches für Knötchen? F6. Warum spricht „behaucht, aber normale Beweglichkeit“ gegen eine Rekurrensparese? F7. Woran erkennst du im Gespräch eine spasmodische Dysphonie, und warum ist sie keine Vagusstörung?"},{"unit":"08","id":"h-8-4-besonderheiten-bei-kindern","title":"8.4 · Besonderheiten bei Kindern","body":"8.4 · Besonderheiten bei Kindern Kinder Stimmlippenknötchen („Schreiknötchen“) sind die häufigste Ursache chronischer Heiserkeit im Schulalter. In einer randomisierten Studie mit 114 Kindern von 6–10 Jahren verbesserten direkte und indirekte Stimmtherapie die stimmbezogene Lebensqualität gleich gut. Larynxpapillomatose: gutartige, aber wiederkehrende Wucherungen durch HPV 6 und 11. Warnzeichen ist eine zunehmende Heiserkeit, später mit Atemgeräusch. Sie gehört sofort zur HNO-Ärztin, nicht in die Stimmtherapie. Laryngomalazie: weiches Knorpelgerüst über dem Kehlkopfeingang, das beim Einatmen angesaugt wird. Häufigste Ursache für Stridor beim Säugling; Schreien normal, Geräusch oft lageabhängig und beim Trinken stärker. Sie ist die wichtigste Abgrenzung zur beidseitigen Stimmlippenlähmung, die nur die Endoskopie sicher trifft. Schwaches Schreien seit Geburt, Stridor oder Trinkprobleme sind nie „nur“ Stimme."},{"unit":"08","id":"h-8-5-warnzeichen-wann-sofort-aerztlich-abklaeren","title":"8.5 · Warnzeichen: wann sofort ärztlich abklären?","body":"8.5 · Warnzeichen: wann sofort ärztlich abklären? ! Sofortige HNO- oder phoniatrische Abklärung Heiserkeit länger als 3–4 Wochen ohne Diagnose (die US-Leitlinie nennt 4 Wochen, in der deutschen Lehre werden oft 3 Wochen genannt) — und sofort bei jedem Verdacht auf eine ernste Ursache Atemgeräusch (Stridor) oder Atemnot Blut im Auswurf, Schmerzen beim Schlucken, Schluckstörung Ohrenschmerzen ohne Ohrbefund (fortgeleiteter Schmerz, z. B. bei Kehlkopf- oder Rachenkrebs) Knoten am Hals, ungewollter Gewichtsverlust, Rauchen und Alkohol in der Vorgeschichte Heiserkeit nach Operation an Hals oder Brustkorb oder nach Intubation Weitere neurologische Zeichen: Gesicht, Zunge, Gaumen, Gang, Doppelbilder, schwankende Stimme mit Ermüdung Kinder: schwaches Schreien seit Geburt, Stridor, Trinkprobleme, wiederkehrende Lungenentzündungen, zunehmende Heiserkeit Grundregel: In Deutschland beginnt Stimmtherapie erst nach laryngoskopischer Diagnose. Wenn eine Patientin ohne Befund kommt oder ein Befund nicht zu dem passt, was du hörst und siehst, verweist du zurück."},{"unit":"08","id":"h-8-6-zwei-mini-faelle","title":"8.6 · Zwei Mini-Fälle","body":"8.6 · Zwei Mini-Fälle Erwachsene · Frau H., 52, Verwaltungsangestellte Seit einem Jahr klingt ihre Stimme gepresst und „abgehackt“, als würde sie gewürgt. Beim Singen und Lachen klingt sie fast normal. In Ruhe bewegen sich beide Stimmlippen normal. F8. Welche Diagnose liegt nahe, und warum ist es keine Nervenlähmung? Was unterscheidet sie von einer hyperfunktionellen Dysphonie? Kind · Ben, 4 Jahre Ben ist seit einigen Monaten heiser, und es wird langsam schlimmer. Neuerdings atmet er im Schlaf laut. Die Eltern denken an „Schreiknötchen“, weil er viel ruft, und möchten direkt Stimmtherapie. F9. Was beunruhigt dich, an welche Erkrankung denkst du, und was tust du? Häufige Fehlvorstellungen „Unbeweglich = gelähmt.“ Auch ein verrenkter oder versteifter Stellknorpel oder eine Narbe hält die Stimmlippe fest. „Internusschwäche und Transversusschwäche sind Nervenlähmungen.“ Es sind beschreibende Schlussmuster bei beweglichen Stimmlippen. Ein kleines hinteres Dreieck ist bei vielen Frauen normal. „Spasmodische Dysphonie ist eine Störung des N. vagus.“ Sie ist eine zentrale Bewegungsstörung (Dystonie); der Nerv selbst ist gesund. „Ein heiseres Kind, das viel schreit, hat Knötchen.“ Wahrscheinlich, aber erst die Laryngoskopie sagt es; zunehmende Heiserkeit oder Atemgeräusche müssen anders abgeklärt werden. „Drei Wochen Heiserkeit sind normal, man kann noch warten.“ Bei Warnzeichen wartet man nicht; ohne Warnzeichen ist spätestens nach 3–4 Wochen eine Untersuchung nötig."},{"unit":"08","id":"h-zusammenfassung-in-fuenf-zeilen","title":"Zusammenfassung in fünf Zeilen","body":"Zusammenfassung in fünf Zeilen Erste Frage: beweglich? Nein → Nerv oder Mechanik (EMG, Prüfung des Gelenks). Ja → keine Lähmung der Hauptmuskeln. Mechanische Ursachen: Aryknorpelluxation, Gelenkfixierung, hintere Glottisstenose, Tumor. Bei beweglichen Stimmlippen: Schlussmuster und Schleimhaut entscheiden (Knötchen, Polyp, funktionell, spasmodisch, Alter). Kinder: Knötchen am häufigsten; Papillomatose und Laryngomalazie nicht übersehen. Warnzeichen sofort weiterleiten; Stimmtherapie erst nach laryngoskopischer Diagnose. Aus dem Gedächtnis zeichnen · 5 Minuten, leeres Blatt Zeichne den Entscheidungsbaum: Raute „beweglich?“, zwei Äste, je eine zweite Raute, vier Endkästen. Zeichne fünf kleine Stimmritzen mit den Schlussmustern und beschrifte sie. Schreib unten einen rot umrandeten Kasten mit mindestens sechs Warnzeichen. Vergleiche mit Abb. 8.1, 8.2 und dem Kasten in 8.5. Was fehlt, kommt auf eine Lernkarte. Lösungen zu F1–F9 (erst nach eigenem Versuch öffnen) F1. Bewegt sich die Stimmlippe? F2. Das Larynx-EMG: bei Lähmung gestört, bei mechanischer Fixierung normal. Ergänzend die Prüfung der Gelenkbeweglichkeit in Narkose. F3. Aryknorpelluxation, Fixierung des Krikoarytänoidgelenks (z. B. Rheuma), hintere Glottisstenose, Tumor. F4. Intubation kann den Stellknorpel aus dem Gelenk drücken; das sieht aus wie eine Lähmung. Eine frühe Reposition kann die Beweglichkeit wiederherstellen; später wird das schwieriger. F5. Einseitiger Spalt mit unbeweglicher Seite: Lähmung oder Fixierung. Sanduhr: Knötchen. F6. Bei einer Rekurrensparese steht die Stimmlippe still. Bewegt sie sich normal, liegt der Grund für die Behauchtheit woanders, z. B. hypofunktionelle Dysphonie, Presbyphonie oder Sulcus. F7. Die Stimme klingt gepresst und abgehackt beim Sprechen, aber besser beim Singen, Lachen oder Flüstern. Ursache ist eine Bewegungsstörung im Gehirn (Dystonie); der N. vagus und die Muskeln sind gesund. F8. Spasmodische Dysphonie vom Adduktortyp. Beweglichkeit ist in Ruhe normal, und die Auffälligkeit hängt von der Aufgabe ab. Bei einer hyperfunktionellen Dysphonie ist das Pressen gleichmäßiger und bessert sich nicht so typisch beim Singen oder Lachen; sie spricht auf Stimmtherapie an, während die spasmodische Dysphonie meist mit Botulinumtoxin behandelt wird. F9. Zunehmende Heiserkeit plus neues Atemgeräusch sind Warnzeichen; das passt nicht zu einfachen Knötchen. Denken muss man an eine Larynxpapillomatose. Keine Stimmtherapie beginnen, sondern umgehend zur HNO-Ärztin bzw. Kinder-HNO überweisen und den Eltern erklären, warum."},{"unit":"08","id":"h-quellen","title":"Quellen","body":"Quellen DGPP. S2k-Leitlinie Diagnostik und Therapie von Störungen der Stimmfunktion (Dysphonien), AWMF 049-008, Version 4.0, 2023, inkl. Kapitel zu Kindern. AWMF-Register. Stachler RJ et al. Clinical Practice Guideline: Hoarseness (Dysphonia) (Update). Otolaryngol Head Neck Surg 2018;158(1 Suppl):S1–S42. doi:10.1177/0194599817751030 (Laryngoskopie nach 4 Wochen oder früher bei ernstem Verdacht). Hartnick C et al. Indirect vs direct voice therapy for children with vocal nodules: a randomized clinical trial. JAMA Otolaryngol Head Neck Surg 2018;144(2):156–163. doi:10.1001/jamaoto.2017.2618. Wendler J, Seidner W, Eysholdt U. Lehrbuch der Phoniatrie und Pädaudiologie. 5. Aufl. Thieme; 2015 (Schlussmuster, Internus- und Transversusschwäche, funktionelle Dysphonien). Nawka T, Anders LC, Wendler J. Die auditive Beurteilung heiserer Stimmen nach dem RBH-System. Sprache Stimme Gehör 1994;18:130–133. Lechien JR. Management of pediatric bilateral vocal fold paralysis. Children 2024;11(4):398. doi:10.3390/children11040398."},{"unit":"09","id":null,"title":"Wiederholung und Probeprüfung: N. vagus und Stimme","body":"Kernpfad · Abschnitte 9 und 10 von 10 Wiederholung und Probeprüfung: N. vagus und Stimme So nutzt du diese Seite Teil 1 (Abschnitt 9) ist gemischte Wiederholung über alle acht Abschnitte, mit sofortiger Rückmeldung. Die Fragen springen absichtlich zwischen den Themen, damit du jedes Mal neu entscheiden musst. Teil 2 (Abschnitt 10) ist eine Probeprüfung mit Auswahlfragen, Kurzantworten, einer Karte zum Ausfüllen und einer mündlichen Frage; ausgewertet wird erst am Ende. Mach Teil 2 an einem anderen Tag als Teil 1, ohne Unterlagen. Teil 1 · Wiederholung Teil 2 · Probeprüfung Wiederholungsplan"},{"unit":"09","id":"h-teil-1-gemischte-wiederholung","title":"Teil 1 · Gemischte Wiederholung","body":"Teil 1 · Gemischte Wiederholung 16 Auswahlfragen, eine richtige Antwort pro Frage. Bei jeder Frage steht, aus welchem Abschnitt sie stammt. Liegst du falsch, lies die Erklärung und markiere dir den Abschnitt. 0 von 16 richtig · 0 beantwortet Beschriften · Kehlkopf von oben Beschriftung prüfen Drei Fälle · erst denken, dann aufdecken"},{"unit":"09","id":"h-teil-2-probepruefung","title":"Teil 2 · Probeprüfung","body":"Teil 2 · Probeprüfung Ohne Unterlagen, etwa 40 Minuten. Auswahlfragen werden erst bei „Prüfung auswerten“ angezeigt. Kurzantworten schreibst du auf Papier, deckst dann die Musterantwort auf und bewertest dich ehrlich mit 0, 1 oder 2 Punkten. A · 15 Auswahlfragen (je 1 Punkt) B · Die Karte ausfüllen (5 Punkte) Wähle für jeden Muskel den Nerv und die Hauptwirkung. Ein Punkt pro vollständig richtiger Zeile. Muskel Nerv Hauptwirkung C · 5 Kurzantworten (je 0–2 Punkte, Selbstbewertung) D · Mündliche Frage „Erzählen Sie mir etwas über den N. vagus und die Stimme.“ Stell eine Uhr auf 5 Minuten und sprich laut, am besten auf Deutsch und ohne Notizen. Hake danach ab, was du gesagt hast. Das zählt nicht zur Punktzahl, zeigt dir aber deine Lücken. Prüfung auswerten"},{"unit":"09","id":"h-wiederholungsplan-nach-der-pruefung","title":"Wiederholungsplan nach der Prüfung","body":"Wiederholungsplan nach der Prüfung Vergessen geht schnell, verteiltes Wiederholen hält. Nimm die Abschnitte, die die Auswertung nennt, und wiederhole sie in wachsenden Abständen: +1 Tag: die genannten Abschnitte, nur Abruffragen und „Aus dem Gedächtnis zeichnen“. +3 Tage: Teil 1 dieser Seite noch einmal komplett. +7 Tage: Gesamtkarte (Abschnitt 4) aus dem Gedächtnis zeichnen, dann Läsionsleiter (Abschnitt 7). +14 Tage: Probeprüfung Teil 2 noch einmal. +30 Tage und etwa 2 Wochen vor der echten Prüfung: alles einmal mündlich erklären. Lies nicht einfach nach. Erst abrufen, dann nachsehen; das Abrufen ist die Übung."},{"unit":"00","id":null,"title":"Vagus Course Style Guide","body":"Course on the vagus nerve and the voice · Visual rules Vagus Course Style Guide Every diagram in the course follows these rules, so she learns the visual code once and then reads each new figure without decoding it. Each rule comes with the reason it helps learning."},{"unit":"00","id":"h-colour-legend","title":"Colour legend","body":"Colour legend One meaning per colour, everywhere. At most 5–6 colours in one diagram. Colour is never the only signal: each colour has a written label and, where useful, a pattern or line style, because about 1 in 12 men has a red-green colour-vision deficiency and arteries, muscle and lesion would otherwise blur together. Swatch Meaning Backup signal (never colour alone) Nerve (general), trunk of the N. vagus Label starts with N. or R.; drawn as a solid line with arrowheads N. laryngeus superior (SLN) and its two branches Tag SLN on every structure it supplies N. laryngeus recurrens (RLN, inferior laryngeal nerve) Tag RLN on every structure it supplies Artery (only as landmarks: aortic arch, subclavian, thyroid arteries) Label starts with A.; solid fill Vein Label starts with V.; solid fill Muscle (red-brown) Label starts with M.; thin fibre lines in the fibre direction Cartilage (pale blue) Firm blue-grey outline; label Cartilago / German name Bone (beige): hyoid, skull base Stippled texture; label Os / German name Pathology / lesion site (magenta) Diagonal hatching plus a ✕ marker and the word “Läsion” Context: anything not being taught right now Grey and lighter; no tag"},{"unit":"00","id":"h-shape-legend","title":"Shape legend","body":"Shape legend Fixed shapes for schemas and flowcharts. The diamond-for-decision convention comes from standard flowchart notation (ISO 5807), so she may already know it. Shape Means Example Structure (nerve, muscle, cartilage) M. cricoarytaenoideus posterior Function or action Opens the glottis Decision or diagnostic question Fold mobile? Red flag: refer to ENT/phoniatrics. Always carries a “!” Stridor, hoarseness > 3–4 weeks Nerve path or direct causation. The arrowhead shows the direction of the signal: towards a muscle = motor, towards the nerve = sensory RLN → PCA Indirect, minor or debated link R. internus → interarytenoid twigs Focus: the one element this figure teaches Bold dark outline"},{"unit":"00","id":"h-nine-rules","title":"Nine rules","body":"Nine rules Use the colour code above, identically in every figure. A stable colour-to-meaning mapping lets colour act as a signal rather than something to decode, which cuts extraneous cognitive load. Following atlas convention (yellow nerves, red arteries) means Sobotta and Prometheus plates look familiar. Use the shape code above for every schema and flowchart. When structure, function and decision always look different, she sees the logic of a flowchart before reading a word. Learned once, it works for the whole course. Label on the structure, keep one orientation, flow one way, leave space. Labels sit on or right next to what they name, never in a separate key. Anatomical views are always anterior (patient facing you, so the patient's right is on your left) or superior for the glottis, with anterior at the top and R / L printed in the patient's frame. Flow runs left to right or top to bottom. Spatial contiguity is one of Mayer's most robust principles: separated labels force the eyes back and forth and split attention. Endoscopic images are the exception, because their orientation differs between examination methods; they always carry R/L markers taken from the source. Signal one thing. The teaching point gets the bold outline or full saturation; everything else is muted grey. Signalling guides attention to the essential element. Several highlights in one figure cancel each other out. No decoration. No clip art, stock photos, mascots or background images. Every visual must teach something. Mayer's coherence principle and the seductive-details research (Rey 2012) show that interesting but irrelevant images reduce learning. Build complex figures in 2–4 stages, for example cartilages → muscles → nerves → lesion. Segmenting and pre-training keep the number of new elements per step within working memory, which matters in anatomy, where every element interacts with the others. Reuse the same figure for the same concept. The master map below returns in every lesion section, with only the lesion added. Seeing the same layout again strengthens one mental model and makes the figure itself a retrieval cue in the exam. Give key figures a hand-drawing prompt: a simplified version she redraws from memory, step by step. Drawing from memory combines retrieval practice with generative learning (Fiorella and Mayer 2016), which works better than rereading the finished picture. Code first, real images where realism matters. Schemas are Mermaid or SVG so they can be edited and kept consistent. Laryngoscopy, stroboscopy and 3D anatomy are not redrawn; each gets a look-up card saying exactly what to find and where. Simple schematic drawings teach structure well, but recognising a paralysed fold needs real images and video."},{"unit":"00","id":"h-example-nerve-muscle-action-map","title":"Example: nerve → muscle → action map","body":"Example: nerve → muscle → action map The core figure of the course, drawn by the rules above. Step through the build-up; stage 3 is the complete reference map. 1 · Nerves 2 · + Muscles 3 · + Actions (full map) 4 · RLN lesion Hand-drawing prompt · redraw from memory Draw a yellow box “N. vagus” on the left. Split it: two teal boxes on top (R. externus, R. internus = SLN), one violet box below (RLN). From R. externus, one arrow to “CT”. From R. internus, an arrow pointing back from “sensation above”. From RLN, four arrows: PCA, LCA, IA, TA. Add “sensation below” pointing back. Write one action per muscle. Box the PCA and write “only opener”. Check against the map. Anything missing becomes a flashcard. Look-up card · when a real image is needed Find Laryngoscopy video of a left recurrent nerve palsy (Rekurrensparese links), during breathing and phonation Where Laryngopedia, entry on vocal fold paralysis (free); Wendler/Seidner/Eysholdt textbook DVD (library) Look for Left fold does not move out on breathing in; gap on phonation; left vocal process may sit lower Orientation Use the R/L marks in the source; endoscopic views are not always shown the same way Links to Stage 4 of the map above Mermaid template for flowcharts flowchart LR classDef nerve fill:#E3B505,stroke:#1B2329,color:#1B2329 classDef sln fill:#13827E,stroke:#13827E,color:#fff classDef rln fill:#6A4C9C,stroke:#6A4C9C,color:#fff classDef muscle fill:#F3E3DA,stroke:#9C4A2F,color:#1B2329 classDef action fill:#fff,stroke:#4A5862,color:#1B2329 classDef flag fill:#FDECEC,stroke:#C62828,stroke-width:3px,color:#1B2329 classDef lesion fill:#F8D8E5,stroke:#C2185B,stroke-width:3px,color:#1B2329 X[\"N. vagus (CN X)\"]:::nerve --> R[\"RLN\"]:::rln R --> P[\"M. cricoarytaenoideus post. (PCA)\"]:::muscle P --> A(\"Opens the glottis\"):::action Q{\"Fold mobile?\"} -.-> F[\"! Stridor: refer to ENT\"]:::flag"},{"unit":"00","id":"h-evidence-behind-the-rules","title":"Evidence behind the rules","body":"Evidence behind the rules Mayer RE (ed.). The Cambridge Handbook of Multimedia Learning, 3rd ed. Cambridge University Press, 2022 (coherence, signalling, spatial contiguity, segmenting, pre-training). Schroeder NL, Cenkci AT. Spatial contiguity and spatial split-attention effects in multimedia learning environments: a meta-analysis. Educ Psychol Rev 2018;30:679–701. Paivio A. Mental Representations: A Dual Coding Approach. Oxford University Press, 1986. Sweller J, van Merriënboer JJG, Paas F. Cognitive architecture and instructional design: 20 years later. Educ Psychol Rev 2019;31:261–292. Rey GD. A review of research and a meta-analysis of the seductive detail effect. Educ Res Rev 2012;7:216–237. Fiorella L, Mayer RE. Eight ways to promote generative learning. Educ Psychol Rev 2016;28:717–741. W3C. WCAG 2.2, Success Criterion 1.4.1 “Use of Color”. Okabe M, Ito K. Color Universal Design (CUD), 2008. ISO 5807:1985. Documentation symbols and conventions for flowcharts."}],"mc":[{"id":"mc-adkjov","units":["01"],"q":"Welcher Muskel ist der einzige Öffner der Stimmritze?","o":["M. cricoarytaenoideus lateralis","M. cricoarytaenoideus posterior","M. arytaenoideus transversus","M. cricothyroideus"],"a":1,"e":"Der Postikus zieht den Proc. muscularis nach hinten, der Proc. vocalis schwenkt nach außen. Alle anderen schließen oder spannen."},{"id":"mc-mrga8b","units":["02"],"q":"Der R. externus des N. laryngeus superior versorgt …","o":["den M. cricothyroideus","den M. vocalis","die Schleimhaut oberhalb der Stimmlippen","den M. cricoarytaenoideus lateralis"],"a":0,"e":"Der R. externus ist motorisch und versorgt nur den Antikus. Die Schleimhaut oberhalb versorgt der R. internus."},{"id":"mc-17ku8kj","units":["06"],"q":"Welche Hustenphase wird schwach, wenn die Stimmritze nicht fest schließen kann?","o":["Einatmen","Kompression","Ausstoß allein","Keine"],"a":1,"e":"Ohne festen Schluss baut sich in der Kompressionsphase kein Druck auf; der ganze Husten wird schwach."},{"id":"mc-13djyjx","units":["03"],"q":"Der linke N. laryngeus recurrens schlingt sich um …","o":["die A. subclavia sinistra","den Aortenbogen","die A. thyroidea inferior","das Berry-Band"],"a":1,"e":"Links um den Aortenbogen, seitlich vom Lig. arteriosum; rechts um die A. subclavia dextra."},{"id":"mc-twoyiu","units":["07"],"q":"Bei einer hohen Vagusläsion rechts weicht das Zäpfchen …","o":["nach rechts ab","nach links ab","gar nicht ab","nach vorn ab"],"a":1,"e":"Die gesunde linke Seite zieht das Zäpfchen zu sich: Es weicht zur gesunden Seite ab."},{"id":"mc-np9qh0","units":["05"],"q":"Welche Schicht trägt die Randkantenverschiebung?","o":["M. vocalis","Lig. vocale","Epithel und Reinke-Raum (Cover)","Schildknorpel"],"a":2,"e":"Die lockere Hülle (Cover) schwingt als Welle; der Muskel (Body) stellt nur die Spannung ein."},{"id":"mc-1k4a7vl","units":["08"],"q":"Ein 7-jähriges Kind hat eine Sanduhrform beim Schluss, beide Stimmlippen beweglich. Am wahrscheinlichsten:","o":["Rekurrensparese","Stimmlippenknötchen","Laryngomalazie","Aryknorpelluxation"],"a":1,"e":"Beidseitige, symmetrische Verdickungen am vorderen-mittleren Drittel bei normaler Beweglichkeit: typisch für Knötchen."},{"id":"mc-10u3o95","units":["02"],"q":"Normale Stimme, aber Joghurt im Kehlkopfvorhof ohne Husten. Welcher Ast?","o":["R. externus","R. internus","N. laryngeus recurrens","Rachenäste"],"a":1,"e":"Ohne Empfindung oberhalb der Stimmlippen startet der Schutzreflex nicht: stille Aspiration."},{"id":"mc-11bmd0u","units":["07"],"q":"Leitsymptom der beidseitigen Rekurrensparese:","o":["stark behauchte Stimme","inspiratorischer Stridor","Näseln","Verlust der hohen Töne"],"a":1,"e":"Beide Öffner fehlen; das Einatmen wird eng und laut, während die Stimme oft gut bleibt."},{"id":"mc-xle3bk","units":["01"],"q":"Der Proc. muscularis wird nach vorn gezogen. Der Proc. vocalis …","o":["schwenkt nach außen","schwenkt nach innen","bleibt stehen","kippt nach oben"],"a":1,"e":"Zug nach vorn (Lateralis) dreht den Hebel so, dass der Proc. vocalis zur Mitte schwenkt: Adduktion."},{"id":"mc-1fpk09l","units":["03"],"q":"Ein nicht-rekurrenter N. laryngeus …","o":["ist links häufiger","kommt rechts vor, meist mit A. lusoria","ist bei jedem 10. Menschen vorhanden","betrifft den R. externus"],"a":1,"e":"Rechts bei etwa 0,7 %, meist zusammen mit einer A. lusoria."},{"id":"mc-xm2hxy","units":["06"],"q":"Die Hebung des Kehlkopfs beim Schlucken …","o":["steuert der N. laryngeus recurrens","steuert der R. externus","leisten Muskeln oberhalb des Zungenbeins mit anderen Hirnnerven","gibt es nicht"],"a":2,"e":"N. trigeminus, N. facialis, N. hypoglossus und Halsnerven heben; der N. vagus schließt, schiebt und fühlt."},{"id":"mc-1risy25","units":["08"],"q":"Nach langer Intubation steht eine Stimmlippe still, das Larynx-EMG ist normal. Am ehesten:","o":["Rekurrensparese","Aryknorpelluxation oder Gelenkfixierung","Lähmung des R. externus","Presbyphonie"],"a":1,"e":"Normales EMG spricht gegen eine Nervenlähmung und für ein mechanisches Hindernis."},{"id":"mc-1d006z2","units":["03"],"q":"Wenn sich der N. laryngeus recurrens vor dem Eintritt teilt, führt die motorischen Fasern …","o":["der hintere Ast","der vordere Ast","beide gleich","keiner"],"a":1,"e":"Der vordere Ast führt fast alle motorischen Fasern, auch für den Postikus; der hintere ist überwiegend sensibel."},{"id":"mc-yfxjns","units":["06"],"q":"Erster Hinweis auf eine Stimmlippenlähmung beim Säugling ist oft …","o":["ein näselndes Lallen","Probleme beim Trinken","eine zu hohe Stimme","Schielen"],"a":1,"e":"Husten oder Verschlucken beim Trinken, lange Trinkzeiten, Atempausen, Lungenentzündungen."},{"id":"mc-7olwdh","units":["05"],"q":"Welcher Muskel überwiegt in der Kopfstimme?","o":["M. thyroarytaenoideus","M. cricothyroideus","M. cricoarytaenoideus posterior","M. arytaenoideus"],"a":1,"e":"Der Antikus dehnt die Stimmlippen dünn; nur die Ränder schwingen."}],"figs":[{"unit":"01","abb":"Abb. 1.1","n":14},{"unit":"01","abb":"Abb. 1.2","n":4},{"unit":"01","abb":"Abb. 1.3","n":11},{"unit":"01","abb":"Abb. 1.4","n":16},{"unit":"02","abb":"Abb. 2.1","n":20},{"unit":"02","abb":"Abb. 2.2","n":11},{"unit":"02","abb":"Abb. 2.3","n":12},{"unit":"02","abb":"Abb. 2.4","n":11},{"unit":"02","abb":"Abb. 2.5","n":16},{"unit":"03","abb":"Abb. 3.1","n":16},{"unit":"03","abb":"Abb. 3.2","n":11},{"unit":"03","abb":"Abb. 3.3","n":11},{"unit":"03","abb":"Abb. 3.4","n":24},{"unit":"04","abb":"Abb. 4.2","n":11},{"unit":"05","abb":"Abb. 5.1","n":10},{"unit":"05","abb":"Abb. 5.2","n":10},{"unit":"05","abb":"Abb. 5.3","n":18},{"unit":"06","abb":"Abb. 6.1","n":11},{"unit":"06","abb":"Abb. 6.2","n":15},{"unit":"06","abb":"Abb. 6.3","n":7},{"unit":"07","abb":"Abb. 7.1","n":8},{"unit":"07","abb":"Abb. 7.2","n":6},{"unit":"07","abb":"Abb. 7.3","n":13},{"unit":"08","abb":"Abb. 8.1","n":23},{"unit":"08","abb":"Abb. 8.2","n":9}]};
